            char[][] grid = new char[n][m];
            int startRow = -1;
            int startCol = -1;

            for (int i = 0; i < n; i++) {
                String rowStr = scanner.next();
                grid[i] = rowStr.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            String pathStr = scanner.next();
            int[] path = new int[pathStr.length()];
            for (int i = 0; i < pathStr.length(); i++) {
                path[i] = pathStr.charAt(i) - '0';
            }

            int validPathCount = countValidPaths(grid, n, m, startRow, startCol, path);
            System.out.println(validPathCount);
        }
    }

    private static int countValidPaths(char[][] grid, int n, int m, int startRow, int startCol, int[] path) {
        int[] dirPermutation = {0, 1, 2, 3};
        return generatePermutations(dirPermutation, 0, grid, n, m, startRow, startCol, path);
    }

    private static int generatePermutations(int[] dirs, int index, char[][] grid, int n, int m,
                                            int startRow, int startCol, int[] path) {
        if (index == dirs.length) {
            return simulate(grid, n, m, startRow, startCol, path) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < dirs.length; i++) {
            swap(dirs, index, i);
            count += generatePermutations(dirs, index + 1, grid, n, m, startRow, startCol, path);
            swap(dirs, index, i); // backtrack
        }
        return count;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private static boolean simulate(char[][] grid, int n, int m, int startRow, int startCol, int[] path) {
        int r = startRow;
        int c = startCol;

        for (int step = 0; step < path.length; step++) {
            // Check bounds and cell content before moving
            if (r < 0 || r >= n || c < 0 || c >= m) return false;
            char currentCell = grid[r][c];
            if (currentCell == 'E') return true;
            if (currentCell == '#') return false;

            // Apply movement based on the current step's direction index
            int dirIdx = path[step];
            r += DIRECTIONS[dirIdx][0];
            c += DIRECTIONS[dirIdx][1];
        }

        // Check if we landed on 'E' after exhausting all steps
        return r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == 'E';
    }
}

import java.util.Scanner;

/**
 * Refactored solution for Codeforces 908B.
 * 
 * Improvements:
 * 1. Removed magic numbers (ASCII '0', direction indices).
 * 2. Extracted logic into helper methods (findStart, simulate, permute).
 * 3. Replaced verbose nested loops for permutations with a recursive backtracking approach.
 * 4. Used descriptive variable names.
 * 5. Encapsulated movement logic using a constant array for directions.
 */
public class Codeforces908B {

    // Direction mappings corresponding to indices 0, 1, 2, 3
    // 0: Down (row + 1), 1: Right (col + 1), 2: Up (row - 1), 3: Left (col - 1)
    private static final int[][] MOVES = {
        {1, 0},  // Down
        {0, 1},  // Right
        {-1, 0}, // Up
        {0, -1}  // Left
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Reading dimensions
        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Reading grid and finding start position
        char[][] grid = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Reading the path string and converting to integer array
        String pathString = scanner.next();
        int[] pathSteps = new int[pathString.length()];
        for (int i = 0; i < pathString.length(); i++) {
            // '0' is ASCII 48. Using char arithmetic for clarity.
            pathSteps[i] = pathString.charAt(i) - '0';
        }

        // Generate all permutations of directions [0, 1, 2, 3]
        // and count how many valid paths exist from 'S' to 'E'.
        int[] perm = {0, 1, 2, 3};
        int validPathCount = countValidPermutations(perm, 0, grid, pathSteps, startRow, startCol, rows, cols);

        System.out.println(validPathCount);
        scanner.close();
    }

    /**
     * Recursively generates permutations of the perm array.
     * When a full permutation is formed, it simulates the path.
     */
    private static int countValidPermutations(int[] perm, int index, char[][] grid, int[] pathSteps,
                                              int startRow, int startCol, int rows, int cols) {
        // Base case: permutation is complete
        if (index == perm.length) {
            return simulatePath(grid, perm, pathSteps, startRow, startCol, rows, cols) ? 1 : 0;
        }

        int count = 0;
        // Try all possible values for the current index
        for (int i = index; i < perm.length; i++) {
            swap(perm, index, i); // Place a new value at current index
            count += countValidPermutations(perm, index + 1, grid, pathSteps, startRow, startCol, rows, cols);
            swap(perm, index, i); // Backtrack to restore state
        }
        return count;
    }

    /**
     * Simulates the path based on the current direction mapping (perm).
     * Returns true if 'E' is reached, false otherwise.
     */
    private static boolean simulatePath(char[][] grid, int[] perm, int[] pathSteps,
                                        int startRow, int startCol, int rows, int cols) {
        int currRow = startRow;
        int currCol = startCol;

        for (int step : pathSteps) {
            // 'step' is the digit from the input (0-3).
            // perm[step] maps this digit to a specific direction index (0-3).
            int directionIndex = perm[step];

            int[] move = MOVES[directionIndex];
            currRow += move[0];
            currCol += move[1];

            // Check boundaries
            if (currRow < 0 || currRow >= rows || currCol < 0 || currCol >= cols) {
                return false;
            }

            char cell = grid[currRow][currCol];

            // Check for obstacles
            if (cell == '#') {
                return false;
            }

            // Check for destination
            if (cell == 'E') {
                return true;
            }
        }

        // If the path string ends and 'E' was not reached
        return false;
    }

    /**
     * Helper method to swap elements in an array.
     */
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.util.Scanner;

public class GB17B {
    // Direction vectors corresponding to indices 0, 1, 2, 3: Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            int startR = -1;
            int startC = -1;

            // Read grid and locate the starting position 'S'
            for (int i = 0; i < rows; i++) {
                String rowStr = scanner.next();
                grid[i] = rowStr.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startR = i;
                        startC = j;
                    }
                }
            }

            String key = scanner.next();
            int validCount = countValidPaths(grid, key, startR, startC);
            System.out.println(validCount);
        }
    }

    /**
     * Generates all permutations of 4 directions and counts how many 
     * successfully navigate from 'S' to 'E' following the given key.
     */
    private static int countValidPaths(char[][] grid, String key, int startR, int startC) {
        int[] perm = new int[4];
        boolean[] used = new boolean[4];
        return generatePermutations(perm, used, 0, grid, key, startR, startC);
    }

    /**
     * Recursive backtracking method to generate all 4! = 24 permutations.
     */
    private static int generatePermutations(int[] perm, boolean[] used, int index, 
                                            char[][] grid, String key, int startR, int startC) {
        if (index == 4) {
            return canReachEnd(grid, key, 0, perm, startR, startC) ? 1 : 0;
        }

        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[index] = i;
                count += generatePermutations(perm, used, index + 1, grid, key, startR, startC);
                used[i] = false; // Backtrack
            }
        }
        return count;
    }

    /**
     * Recursively follows the path defined by 'key' using the direction mapping in 'perm'.
     * Returns true if 'E' is reached, false otherwise.
     */
    private static boolean canReachEnd(char[][] grid, String key, int keyIdx, int[] perm, int r, int c) {
        if (keyIdx == key.length()) {
            return false; // Completed all moves without reaching 'E'
        }

        int dirDigit = key.charAt(keyIdx) - '0';
        int actualDirIdx = -1;

        // Find which permutation position maps to the requested direction digit
        for (int i = 0; i < 4; i++) {
            if (perm[i] == dirDigit) {
                actualDirIdx = i;
                break;
            }
        }

        if (actualDirIdx == -1) {
            return false; // Invalid direction digit in key
        }

        int nr = r + DR[actualDirIdx];
        int nc = c + DC[actualDirIdx];

        // Check bounds and obstacles
        if (!isInBounds(nr, nc, grid) || grid[nr][nc] == '#') {
            return false;
        }

        // Check if destination reached
        if (grid[nr][nc] == 'E') {
            return true;
        }

        // Continue recursively
        return canReachEnd(grid, key, keyIdx + 1, perm, nr, nc);
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isInBounds(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < (grid.length > 0 ? grid[0].length : 0);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solves the grid path simulation problem by testing all permutations
 * of direction mappings against a sequence of moves.
 */
public class Codeforces {

    // Direction mappings: 0=Down, 1=Left, 2=Right, 3=Up
    private static final int[] DR = {1, 0, 0, -1};
    private static final int[] DC = {0, -1, 1, 0};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String moves = scanner.next();
        scanner.close();

        // Generate all permutations of [0, 1, 2, 3]
        List<int[]> permutations = new ArrayList<>();
        int[] initial = {0, 1, 2, 3};
        generatePermutations(initial, 0, permutations);

        int successCount = 0;
        for (int[] perm : permutations) {
            if (simulatePath(grid, rows, cols, startRow, startCol, perm, moves)) {
                successCount++;
            }
        }

        System.out.println(successCount);
    }

    /**
     * Generates all permutations of the given array using backtracking.
     */
    private static void generatePermutations(int[] arr, int start, List<int[]> result) {
        if (start == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            generatePermutations(arr, start + 1, result);
            swap(arr, start, i);
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates a path based on a direction permutation and a move sequence.
     * Returns true if 'E' is reached, false otherwise.
     */
    private static boolean simulatePath(char[][] grid, int rows, int cols,
                                        int startRow, int startCol,
                                        int[] perm, String moves) {
        // Map each digit character to its corresponding direction index.
        // perm[k] is the digit that maps to direction k (0=Down, 1=Left, 2=Right, 3=Up)
        int[] dirMap = new int[4];
        for (int k = 0; k < 4; k++) {
            int digit = perm[k];
            dirMap[digit] = k;
        }

        int r = startRow;
        int c = startCol;

        for (int i = 0; i < moves.length(); i++) {
            char ch = moves.charAt(i);
            int dirIdx = dirMap[ch - '0'];

            r += DR[dirIdx];
            c += DC[dirIdx];

            // Check bounds and obstacles
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#') {
                return false;
            }
            if (grid[r][c] == 'E') {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        GridPathSolver solver = new GridPathSolver();
        solver.solve(in, out);
        out.flush();
        out.close();
    }

    /**
     * Solves the grid path problem by testing all valid direction permutations.
     */
    static class GridPathSolver {
        // Direction deltas: 0=Left, 1=Up, 2=Right, 3=Down
        private static final int[] DR = {0, -1, 0, 1};
        private static final int[] DC = {-1, 0, 1, 0};
        private static final int NUM_DIRS = 4;

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = in.nextCharTable(n, m);
            String movesStr = in.next();

            int[] moves = new int[movesStr.length()];
            for (int i = 0; i < movesStr.length(); i++) {
                moves[i] = movesStr.charAt(i) - '0';
            }

            int startRow = -1;
            int startCol = -1;
            search:
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == 'S') {
                        startRow = r;
                        startCol = c;
                        break search;
                    }
                }
            }

            int[] dirMapping = new int[NUM_DIRS];
            boolean[] used = new boolean[NUM_DIRS];
            int validCount = countValidPermutations(dirMapping, used, 0, n, m, grid, moves, startRow, startCol);

            out.print(validCount);
        }

        /**
         * Recursively generates all permutations of direction mappings and counts valid paths.
         */
        private int countValidPermutations(int[] dirMapping, boolean[] used, int index, int n, int m,
                                           char[][] grid, int[] moves, int startRow, int startCol) {
            if (index == NUM_DIRS) {
                return isValidPathWithMapping(dirMapping, n, m, grid, moves, startRow, startCol) ? 1 : 0;
            }

            int count = 0;
            for (int d = 0; d < NUM_DIRS; d++) {
                if (!used[d]) {
                    used[d] = true;
                    dirMapping[index] = d;
                    count += countValidPermutations(dirMapping, used, index + 1, n, m, grid, moves, startRow, startCol);
                    used[d] = false;
                }
            }
            return count;
        }

        /**
         * Simulates movement on the grid using the provided direction mapping.
         * Returns true if the path reaches 'E' without hitting walls or boundaries.
         */
        private boolean isValidPathWithMapping(int[] dirMapping, int n, int m, char[][] grid, int[] moves,
                                               int startRow, int startCol) {
            int currentRow = startRow;
            int currentCol = startCol;

            for (int moveIndex : moves) {
                int dir = dirMapping[moveIndex];
                currentRow += DR[dir];
                currentCol += DC[dir];

                if (currentRow < 0 || currentRow >= n || currentCol < 0 || currentCol >= m ||
                    grid[currentRow][currentCol] == '#') {
                    return false;
                }
                if (grid[currentRow][currentCol] == 'E') {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast input reader for competitive programming and batch processing.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public char[][] nextCharTable(int rows, int columns) {
            char[][] table = new char[rows][];
            for (int i = 0; i < rows; ++i) {
                table[i] = next().toCharArray();
                if (table[i].length != columns) {
                    throw new IllegalArgumentException("Row length mismatch: expected " + columns + ", got " + table[i].length);
                }
            }
            return table;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(readLine());
            }
            return tokenizer.nextToken();
        }

        public String readLine() {
            try {
                String line = reader.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                return line;
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }
    }
}

import java.util.Scanner;

/**
 * Solves a maze pathfinding problem by counting how many permutations of 
 * four distinct movement directions successfully guide a path from 'S' to 'E'.
 */
public class MazePathCounter {

    // Direction vectors: Right, Left, Up, Down
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};
    private static final int NUM_DIRS = DIRECTIONS.length;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after the last integer

        char[][] maze = new char[rows][];
        for (int i = 0; i < rows; i++) {
            maze[i] = scanner.nextLine().toCharArray();
        }

        String ops = scanner.hasNextLine() ? scanner.nextLine() : "";

        Position start = findPosition(maze, 'S');
        Position end = findPosition(maze, 'E');

        int validPaths = countValidPaths(maze, ops, start, end);
        System.out.println(validPaths);
    }

    /**
     * Locates the starting or ending position in the maze grid.
     */
    private static Position findPosition(char[][] maze, char target) {
        for (int r = 0; r < maze.length; r++) {
            for (int c = 0; c < maze[r].length; c++) {
                if (maze[r][c] == target) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Position not found: " + target);
    }

    /**
     * Initiates permutation generation and aggregates successful path counts.
     */
    private static int countValidPaths(char[][] maze, String ops, Position start, Position end) {
        int[] perm = new int[NUM_DIRS];
        boolean[] used = new boolean[NUM_DIRS];
        return generatePermutations(maze, ops, start, end, perm, used, 0);
    }

    /**
     * Recursively generates all permutations of direction indices using backtracking.
     */
    private static int generatePermutations(char[][] maze, String ops, Position start, Position end,
                                            int[] perm, boolean[] used, int index) {
        if (index == NUM_DIRS) {
            return simulatePath(maze, ops, start, end, perm) ? 1 : 0;
        }

        int count = 0;
        for (int i = 0; i < NUM_DIRS; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[index] = i;
                count += generatePermutations(maze, ops, start, end, perm, used, index + 1);
                used[i] = false; // Backtrack
            }
        }
        return count;
    }

    /**
     * Simulates movement through the maze using a given direction permutation.
     * Returns true if the endpoint is reached without hitting a wall or boundary.
     */
    private static boolean simulatePath(char[][] maze, String ops, Position start, Position end, int[] perm) {
        int r = start.row;
        int c = start.col;

        for (int i = 0; i < ops.length(); i++) {
            char op = ops.charAt(i);
            int dirIndex = op - '0';

            // Safely ignore invalid operation characters
            if (dirIndex < 0 || dirIndex > 3) {
                continue;
            }

            int[] dir = perm[dirIndex];
            r += dir[0];
            c += dir[1];

            // Check boundaries and walls
            if (r < 0 || r >= maze.length || c < 0 || c >= maze[0].length || maze[r][c] == '#') {
                return false;
            }

            // Check if endpoint is reached
            if (r == end.row && c == end.col) {
                return true;
            }
        }
        return false;
    }

    /**
     * Immutable record-like class to store 2D grid coordinates.
     */
    private static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored Maze Solver.
 * 
 * Improvements made:
 * 1. Class renamed to 'MazeSolver' for descriptive naming.
 * 2. Variable names updated for clarity (e.g., 'rows', 'cols', 'validCount').
 * 3. Logic separated into helper methods:
 *    - findStart: Locates the starting position.
 *    - isSafe: Centralized boundary and obstacle checking.
 *    - simulate: Handles path traversal logic.
 *    - countValidPaths: Recursively generates permutations of direction mappings.
 *    - swap: Helper for permutation logic.
 * 4. Replaced hardcoded nested loops for permutation generation with a cleaner recursive approach.
 * 5. Removed redundant boundary checks and consolidated logic in 'simulate'.
 * 6. Added comments and improved code structure.
 */
public class MazeSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read maze grid
        char[][] maze = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                maze[i] = scanner.next().toCharArray();
            }
        }

        // Read direction string
        String directionsStr = "";
        if (scanner.hasNext()) {
            directionsStr = scanner.next();
        }
        char[] directions = directionsStr.toCharArray();

        // Find starting position 'S'
        int[] startPos = findStart(maze);
        int startR = startPos[0];
        int startC = startPos[1];

        // Initialize mapping array: maps input digit '0'-'3' to direction index 0-3
        // Default mapping: '0'->0 (Down), '1'->1 (Up), '2'->2 (Right), '3'->3 (Left)
        int[] mapping = {0, 1, 2, 3};

        // Count valid permutations of the direction mapping
        int validCount = countValidPaths(mapping, 0, maze, startR, startC, directions);

        System.out.println(validCount);
        scanner.close();
    }

    /**
     * Finds the coordinates of the starting point 'S' in the grid.
     */
    private static int[] findStart(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == 'S') {
                    return new int[]{r, c};
                }
            }
        }
        // Fallback if 'S' is not found (though problem constraints imply it exists)
        return new int[]{0, 0};
    }

    /**
     * Checks if a position is within grid bounds and not a wall ('#').
     */
    private static boolean isSafe(char[][] grid, int r, int c) {
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length) {
            return false;
        }
        if (grid[r][c] == '#') {
            return false;
        }
        return true;
    }

    /**
     * Simulates the path traversal based on the current direction mapping.
     * 
     * @param grid The maze grid.
     * @param r Current row.
     * @param c Current column.
     * @param directions String of movement instructions.
     * @param mapping Array mapping input digits to movement directions.
     * @return true if 'E' is reached, false otherwise.
     */
    private static boolean simulate(char[][] grid, int r, int c, char[] directions, int[] mapping) {
        // Check starting position validity
        if (!isSafe(grid, r, c)) {
            return false;
        }
        // If start is already 'E'
        if (grid[r][c] == 'E') {
            return true;
        }

        for (char inputChar : directions) {
            // Map input character ('0'-'3') to direction index
            int directionIndex = mapping[inputChar - '0'];

            // Apply movement based on direction index
            // 0: Down (r+1), 1: Up (r-1), 2: Right (c+1), 3: Left (c-1)
            if (directionIndex == 0) {
                r++;
            } else if (directionIndex == 1) {
                r--;
            } else if (directionIndex == 2) {
                c++;
            } else if (directionIndex == 3) {
                c--;
            }

            // Check validity of new position
            if (!isSafe(grid, r, c)) {
                return false;
            }
            // Check if goal reached
            if (grid[r][c] == 'E') {
                return true;
            }
        }

        // If loop completes, we are at a valid position but did not reach 'E'
        return false;
    }

    /**
     * Recursively generates all permutations of the mapping array and counts valid paths.
     * 
     * @param mapping The array to permute.
     * @param index Current index being fixed in the permutation.
     * @param grid The maze grid.
     * @param startR Starting row.
     * @param startC Starting column.
     * @param directions Movement instructions.
     * @return Count of valid permutations.
     */
    private static int countValidPaths(int[] mapping, int index, char[][] grid, int startR, int startC, char[] directions) {
        // Base case: permutation complete
        if (index == mapping.length) {
            return simulate(grid, startR, startC, directions, mapping) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < mapping.length; i++) {
            // Swap elements to generate permutation
            swap(mapping, index, i);

            // Recurse for the next index
            count += countValidPaths(mapping, index + 1, grid, startR, startC, directions);

            // Backtrack (swap back to restore original order for next iteration)
            swap(mapping, index, i);
        }
        return count;
    }

    /**
     * Swaps two elements in an integer array.
     */
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for New Year and Buggy Bot.
 * 
 * Improvements made:
 * 1. Encapsulated state: Removed static fields (R, C, maze) to make the class instance-based and thread-safe.
 * 2. Resource Management: Used try-with-resources for automatic closing of IO streams.
 * 3. Readability: Replaced complex mathematical expressions for movement deltas with explicit constant arrays.
 * 4. Structure: Extracted logic into methods (init, solve, simulatePath, generatePermutations) for better separation of concerns.
 * 5. Permutation Logic: Replaced deeply nested loops with a clean recursive backtracking approach.
 * 6. Safety: Added bounds checking for input reading to prevent IndexOutOfBoundsException.
 */
public class NewYearAndBuggyBot {

    // Constants for movement deltas derived from the original logic:
    // Index 0: (0, -1) -> Left
    // Index 1: (-1, 0) -> Up
    // Index 2: (0, 1)  -> Right
    // Index 3: (1, 0)  -> Down
    // These correspond to the behavior of the original code's arithmetic logic.
    private static final int[] DELTA_ROW = {0, -1, 0, 1};
    private static final int[] DELTA_COL = {-1, 0, 1, 0};

    // Instance variables to hold problem state
    private int rows;
    private int cols;
    private boolean[][] maze;
    private int startRow;
    private int startCol;
    private int endRow;
    private int endCol;
    private char[] directions;
    private int validPermutationsCount;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are closed properly
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            NewYearAndBuggyBot solver = new NewYearAndBuggyBot();
            solver.init(in);
            solver.solve();
            out.println(solver.getAnswer());

            out.flush();
        }
    }

    /**
     * Reads input from the BufferedReader and initializes the solver state.
     */
    private void init(BufferedReader in) throws IOException {
        String line = in.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        if (st.hasMoreTokens()) {
            rows = Integer.parseInt(st.nextToken());
        }
        if (st.hasMoreTokens()) {
            cols = Integer.parseInt(st.nextToken());
        }

        maze = new boolean[rows][cols];
        startRow = 0;
        startCol = 0;
        endRow = 0;
        endCol = 0;

        for (int r = 0; r < rows; r++) {
            String rowLine = in.readLine();
            // Safety check for empty lines or unexpected EOF
            if (rowLine == null) break;

            int length = Math.min(rowLine.length(), cols);
            for (int c = 0; c < length; c++) {
                char ch = rowLine.charAt(c);
                if (ch == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (ch == 'E') {
                    endRow = r;
                    endCol = c;
                }
                // true represents a wall ('#'), false represents an open space
                maze[r][c] = (ch == '#');
            }
        }

        String directionsLine = in.readLine();
        if (directionsLine != null) {
            directions = directionsLine.toCharArray();
        } else {
            directions = new char[0];
        }
    }

    /**
     * Orchestrates the solution by generating permutations and counting valid ones.
     */
    private void solve() {
        int[] currentMapping = new int[4];
        boolean[] used = new boolean[4];
        validPermutationsCount = 0;

        // Generate all permutations of the direction mapping (0..3)
        generatePermutations(0, currentMapping, used);
    }

    /**
     * Recursively generates all permutations of the direction mapping.
     * 
     * @param index The current index in the mapping array being filled.
     * @param currentMapping The array storing the current permutation.
     * @param used Boolean array to track which direction indices (0-3) have been used.
     */
    private void generatePermutations(int index, int[] currentMapping, boolean[] used) {
        // Base case: If we have assigned directions for all 4 slots
        if (index == 4) {
            if (simulatePath(currentMapping)) {
                validPermutationsCount++;
            }
            return;
        }

        // Try every possible direction index (0 to 3) for the current slot
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                currentMapping[index] = i;

                // Recurse to fill the next slot
                generatePermutations(index + 1, currentMapping, used);

                // Backtrack
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the bot's movement using the provided direction mapping.
     * 
     * @param directionMapping An array where index i maps input digit i to a direction code (0-3).
     * @return true if the bot successfully reaches the end position, false otherwise.
     */
    private boolean simulatePath(int[] directionMapping) {
        int r = startRow;
        int c = startCol;

        for (char moveChar : directions) {
            // If we have already reached the end, stop moving
            if (r == endRow && c == endCol) {
                break;
            }

            int moveIndex = moveChar - '0';
            // Validate input character is within expected range '0'-'3'
            if (moveIndex < 0 || moveIndex > 3) {
                return false;
            }

            // Get the actual direction code from the current permutation mapping
            int directionCode = directionMapping[moveIndex];

            // Apply movement using pre-defined deltas
            r += DELTA_ROW[directionCode];
            c += DELTA_COL[directionCode];

            // Check boundaries and walls
            if (r < 0 || r >= rows || c < 0 || c >= cols || maze[r][c]) {
                return false;
            }
        }

        // Success if we are currently at the end position
        return (r == endRow && c == endCol);
    }

    /**
     * Returns the count of valid direction mappings found.
     */
    private int getAnswer() {
        return validPermutationsCount;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for Codeforces 908B (or similar grid pathfinding problem).
 * 
 * Improvements:
 * 1. Readability: Used meaningful variable names and separated concerns (Input, Logic, Simulation).
 * 2. Maintainability: Extracted permutation logic into a recursive helper.
 * 3. Type Safety: Used an Enum for Directions to avoid magic numbers.
 * 4. Structure: Cleaned up nested loops and control flow.
 */
public class Main {

    // Enum to represent grid directions with their coordinate deltas
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dr; // Delta row
        final int dc; // Delta col

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    // Array of all possible directions for easy iteration
    private static final Direction[] DIRECTIONS = {Direction.UP, Direction.DOWN, Direction.LEFT, Direction.RIGHT};

    // Counter for valid permutations
    private static int ans = 0;

    public static void main(String[] args) throws IOException {
        // Fast I/O
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        // Grid storage: true if wall
        boolean[][] isWall = new boolean[n][m];
        int startR = 0, startC = 0, endR = 0, endC = 0;

        // Parse Grid
        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            if (row == null) break; 
            for (int j = 0; j < m; j++) {
                char c = row.charAt(j);
                if (c == '#') {
                    isWall[i][j] = true;
                } else if (c == 'S') {
                    startR = i;
                    startC = j;
                } else if (c == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }

        // Parse Instructions
        String instLine = br.readLine();
        if (instLine == null) instLine = "";
        char[] instructions = instLine.toCharArray();

        // mapping[digit] stores the index in DIRECTIONS array assigned to that input digit
        int[] mapping = new int[4]; 
        boolean[] usedDirs = new boolean[4];

        // Generate all permutations of direction assignments
        permute(0, mapping, usedDirs, n, m, startR, startC, endR, endC, instructions, isWall);

        System.out.println(ans);
    }

    /**
     * Recursively generates all permutations of direction assignments.
     * mapping[digitIndex] = directionIndex
     */
    private static void permute(int digitIndex, int[] mapping, boolean[] usedDirs,
                                int n, int m, int startR, int startC, int endR, int endC,
                                char[] instructions, boolean[][] isWall) {

        // Base case: All 4 digits (0-3) have been assigned a direction
        if (digitIndex == 4) {
            if (simulate(n, m, startR, startC, endR, endC, instructions, isWall, mapping)) {
                ans++;
            }
            return;
        }

        // Try assigning each unused direction to the current digit
        for (int d = 0; d < 4; d++) {
            if (!usedDirs[d]) {
                mapping[digitIndex] = d;
                usedDirs[d] = true;

                permute(digitIndex + 1, mapping, usedDirs, n, m, startR, startC, endR, endC, instructions, isWall);

                usedDirs[d] = false; // Backtrack
            }
        }
    }

    /**
     * Simulates the path based on the current direction mapping.
     * Returns true if the path successfully reaches the end point.
     */
    private static boolean simulate(int n, int m, int startR, int startC, int endR, int endC,
                                    char[] instructions, boolean[][] isWall, int[] mapping) {
        int r = startR;
        int c = startC;

        for (char inst : instructions) {
            // 1. Check Bounds
            if (r < 0 || r >= n || c < 0 || c >= m) {
                return false;
            }

            // 2. Check if End is reached (Stop moving if reached)
            if (r == endR && c == endC) {
                return true;
            }

            // 3. Check Wall
            if (isWall[r][c]) {
                return false;
            }

            // 4. Move
            int digit = inst - '0';
            // Safety check for valid instruction digit
            if (digit < 0 || digit > 3) return false;

            Direction d = DIRECTIONS[mapping[digit]];
            r += d.dr;
            c += d.dc;
        }

        // If loop finishes, check if we are exactly at the end
        return r == endR && c == endC;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer tokenizer;

    public Main() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(System.out);
    }

    public void run() {
        try {
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
        }
    }

    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = next().toCharArray();
        }

        String directionStr = next();
        int[] directionSequence = new int[directionStr.length()];
        for (int i = 0; i < directionStr.length(); i++) {
            directionSequence[i] = directionStr.charAt(i) - '0';
        }

        Point start = new Point();
        Point end = new Point();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 'S') {
                    start.r = r;
                    start.c = c;
                } else if (grid[r][c] == 'E') {
                    end.r = r;
                    end.c = c;
                }
            }
        }

        int[] perm = new int[4];
        boolean[] used = new boolean[4];
        int validCount = countValidPermutations(perm, used, 0, n, m, grid, directionSequence, start, end);

        writer.println(validCount);
    }

    /**
     * Recursively generates all permutations of [0, 1, 2, 3] and counts how many
     * result in a valid path reaching the goal.
     */
    private int countValidPermutations(int[] perm, boolean[] used, int index, int n, int m, char[][] grid, int[] directionSequence, Point start, Point end) {
        if (index == 4) {
            return simulatePath(n, m, grid, directionSequence, start, end, perm) ? 1 : 0;
        }
        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[index] = i;
                count += countValidPermutations(perm, used, index + 1, n, m, grid, directionSequence, start, end);
                used[i] = false;
            }
        }
        return count;
    }

    /**
     * Simulates movement based on a direction permutation and the given sequence.
     * Returns true if the goal is reached at any step.
     */
    private boolean simulatePath(int n, int m, char[][] grid, int[] directionSequence, Point start, Point end, int[] perm) {
        int r = start.r;
        int c = start.c;

        // Direction mappings: 0 -> Down, 1 -> Right, 2 -> Up, 3 -> Left
        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int seqIdx : directionSequence) {
            int dirIdx = perm[seqIdx];
            int nr = r + dr[dirIdx];
            int nc = c + dc[dirIdx];

            // Check if the next step lands exactly on the goal
            if (nr == end.r && nc == end.c) {
                return true;
            }
            // Check boundaries and obstacles
            if (nr < 0 || nr >= n || nc < 0 || nc >= m || grid[nr][nc] == '#') {
                return false;
            }
            r = nr;
            c = nc;
        }
        return false;
    }

    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) throw new IOException("Unexpected end of input");
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private static class Point {
        int r, c;
    }
}

import java.io.OutputStream;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    // Direction deltas: 0=UP, 1=DOWN, 2=LEFT, 3=RIGHT
    private static final int[] DIR_ROW = {-1, 1, 0, 0};
    private static final int[] DIR_COL = {0, 0, -1, 1};

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.close();
    }

    static class TaskB {
        public void solve(Scanner in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][cols];
            int startRow = 0, startCol = 0, endRow = 0, endCol = 0;

            // Parse grid and locate start/end positions
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    if (cell == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (cell == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            String moveSequence = in.next();

            // Generate all permutations of direction mappings and count valid paths
            int[] directionOrder = new int[4];
            boolean[] used = new boolean[4];
            int validCount = generatePermutations(directionOrder, used, 0, 
                    startRow, startCol, endRow, endCol, grid, rows, cols, moveSequence);

            out.println(validCount);
        }

        /**
         * Recursively generates all permutations of [0, 1, 2, 3] representing 
         * the mapping from move characters to actual directions.
         */
        private int generatePermutations(int[] directionOrder, boolean[] used, int depth,
                                         int startRow, int startCol, int endRow, int endCol,
                                         char[][] grid, int rows, int cols, String moveSequence) {
            if (depth == 4) {
                return checkPath(directionOrder, startRow, startCol, endRow, endCol, grid, rows, cols, moveSequence) ? 1 : 0;
            }

            int count = 0;
            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    directionOrder[depth] = i;
                    count += generatePermutations(directionOrder, used, depth + 1,
                            startRow, startCol, endRow, endCol, grid, rows, cols, moveSequence);
                    used[i] = false;
                }
            }
            return count;
        }

        /**
         * Simulates a path based on the given direction mapping and move sequence.
         * Returns true if the path reaches the destination without hitting walls or boundaries.
         */
        private boolean checkPath(int[] directionOrder, int startRow, int startCol, int endRow, int endCol,
                                  char[][] grid, int rows, int cols, String moveSequence) {
            int r = startRow;
            int c = startCol;

            for (int i = 0; i < moveSequence.length(); i++) {
                int moveCharIndex = moveSequence.charAt(i) - '0';
                int actualDirIndex = directionOrder[moveCharIndex];

                r += DIR_ROW[actualDirIndex];
                c += DIR_COL[actualDirIndex];

                // Check boundaries and walls
                if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#') {
                    return false;
                }
                // Check if destination reached
                if (r == endRow && c == endCol) {
                    return true;
                }
            }
            return false;
        }
    }
}

import java.util.Scanner;

public class P908B {
    // Direction mappings: 0=Right, 1=Left, 2=Down, 3=Up
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char WALL_CHAR = '#';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            Coordinate start = null;
            Coordinate end = null;
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    char cell = grid[i][j];
                    if (cell == START_CHAR) {
                        start = new Coordinate(i, j);
                    } else if (cell == END_CHAR) {
                        end = new Coordinate(i, j);
                    }
                }
            }

            char[] path = scanner.next().toCharArray();

            int[] perm = new int[4];
            boolean[] used = new boolean[4];
            int[] validCount = new int[1];

            generatePermutations(perm, used, 0, grid, n, m, path, start, end, validCount);

            System.out.println(validCount[0]);
        }
    }

    private static void generatePermutations(int[] perm, boolean[] used, int index,
                                             char[][] grid, int n, int m, char[] path,
                                             Coordinate start, Coordinate end, int[] validCount) {
        if (index == perm.length) {
            if (isValid(grid, n, m, path, perm, start, end)) {
                validCount[0]++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[index] = i;
                generatePermutations(perm, used, index + 1, grid, n, m, path, start, end, validCount);
                used[i] = false;
            }
        }
    }

    private static boolean isValid(char[][] grid, int n, int m, char[] path, int[] perm,
                                   Coordinate start, Coordinate end) {
        int curRow = start.row;
        int curCol = start.col;

        for (char c : path) {
            int directionIndex = c - '0';
            if (directionIndex < 0 || directionIndex > 3) {
                return false;
            }

            int moveDir = perm[directionIndex];
            int nextRow = curRow + DX[moveDir];
            int nextCol = curCol + DY[moveDir];

            if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= m) {
                return false;
            }
            if (grid[nextRow][nextCol] == WALL_CHAR) {
                return false;
            }
            if (nextRow == end.row && nextCol == end.col) {
                return true;
            }

            curRow = nextRow;
            curCol = nextCol;
        }
        return false;
    }

    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class NewYearBuggyBot {

    // Direction vectors corresponding to indices 0, 1, 2, 3
    // 0: Down (row + 1), 1: Right (col + 1), 2: Up (row - 1), 3: Left (col - 1)
    private static final Point[] DIRECTIONS = {
        new Point(1, 0),
        new Point(0, 1),
        new Point(-1, 0),
        new Point(0, -1)
    };

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        // Check for empty input
        if (!sc.hasNext()) {
            pw.close();
            return;
        }

        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // Consume the newline character after integers

        // Use a 2D boolean array for obstacles instead of HashMap for better performance and readability
        boolean[][] obstacles = new boolean[n][m];
        Point start = null;
        Point end = null;

        // Parse the maze
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                if (j < line.length()) {
                    char c = line.charAt(j);
                    switch (c) {
                        case 'S':
                            start = new Point(i, j);
                            break;
                        case 'E':
                            end = new Point(i, j);
                            break;
                        case '#':
                            obstacles[i][j] = true;
                            break;
                        default:
                            break;
                    }
                }
            }
        }

        String instructions = sc.hasNext() ? sc.nextLine() : "";
        sc.close();

        // Basic validation
        if (start == null || end == null) {
            pw.println(0);
            pw.close();
            return;
        }

        // Generate permutations of directions [0, 1, 2, 3]
        // mapping[i] stores the physical direction index assigned to instruction key 'i' (0-3)
        int[] mapping = new int[4];
        boolean[] used = new boolean[4];
        int validCount = countValidMappings(0, mapping, used, start, end, obstacles, instructions, n, m);

        pw.println(validCount);
        pw.close();
    }

    /**
     * Recursively generates permutations of direction indices [0, 1, 2, 3].
     * mapping[index] will hold the physical direction assigned to the instruction character ('0' + index).
     */
    private static int countValidMappings(int index, int[] mapping, boolean[] used,
            Point start, Point end, boolean[][] obstacles, String instructions, int n, int m) {

        // Base case: All 4 instruction keys (0-3) have been assigned a unique physical direction
        if (index == 4) {
            return simulate(start, end, obstacles, mapping, instructions, n, m) ? 1 : 0;
        }

        int count = 0;
        // Try assigning each unused physical direction to the current instruction key
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                mapping[index] = i; 

                count += countValidMappings(index + 1, mapping, used, start, end, obstacles, instructions, n, m);

                used[i] = false; // Backtrack
            }
        }
        return count;
    }

    /**
     * Simulates the bot's movement based on a specific direction mapping.
     */
    private static boolean simulate(Point start, Point end, boolean[][] obstacles, int[] mapping,
            String instructions, int n, int m) {

        Point current = new Point(start.r, start.c);

        for (int i = 0; i < instructions.length(); i++) {
            char instr = instructions.charAt(i);

            // Ignore characters that are not '0', '1', '2', '3'
            if (instr < '0' || instr > '3') {
                continue;
            }

            int dirIndex = instr - '0';
            // mapping[dirIndex] gives the physical direction (0-3) for this instruction
            int physicalDir = mapping[dirIndex];
            Point move = DIRECTIONS[physicalDir];

            // Update position
            current.r += move.r;
            current.c += move.c;

            // Check if reached destination
            if (current.r == end.r && current.c == end.c) {
                return true;
            }

            // Check bounds
            if (current.r < 0 || current.r >= n || current.c < 0 || current.c >= m) {
                return false;
            }

            // Check obstacles
            if (obstacles[current.r][current.c]) {
                return false;
            }
        }

        return false;
    }

    /**
     * Represents a coordinate in the grid.
     */
    public static class Point {
        int r; // Row (corresponds to x in original code)
        int c; // Column (corresponds to y in original code)

        public Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private final FastScanner in;
    private final PrintWriter out;

    public Main() {
        try {
            in = new FastScanner(new File("input.txt"));
            out = new PrintWriter(new File("output.txt"));
        } catch (FileNotFoundException e) {
            in = new FastScanner(System.in);
            out = new PrintWriter(System.out);
        }
    }

    public void run() {
        solve();
        out.flush();
        out.close();
    }

    private void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        String moves = in.next();

        // directionMap[i] stores the digit code (0-3) that corresponds to direction i
        // Index mapping: 0=North, 1=East, 2=South, 3=West
        int[] directionMap = new int[4];
        boolean[] used = new boolean[4];
        int validCount = generatePermutations(grid, moves, n, m, directionMap, used, 0);

        out.println(validCount);
    }

    /**
     * Generates all permutations of direction codes [0, 1, 2, 3] and counts how many
     * allow reaching the goal 'E' from 'S' using the given move sequence.
     */
    private int generatePermutations(char[][] grid, String moves, int n, int m,
                                     int[] perm, boolean[] used, int idx) {
        if (idx == 4) {
            return canReach(grid, moves, perm, n, m) ? 1 : 0;
        }

        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[idx] = i;
                count += generatePermutations(grid, moves, n, m, perm, used, idx + 1);
                used[i] = false;
            }
        }
        return count;
    }

    /**
     * Simulates movement on the grid based on the current direction mapping.
     * Returns true if 'E' is reached, false otherwise.
     */
    private boolean canReach(char[][] grid, String moves, int[] directionMap, int n, int m) {
        int r = 0, c = 0;
        // Locate start position
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    r = i;
                    c = j;
                    break;
                }
            }
        }

        for (int i = 0; i < moves.length(); i++) {
            int dirCode = moves.charAt(i) - '0';
            int dr = 0, dc = 0;

            // directionMap[0] = North, [1] = East, [2] = South, [3] = West
            if (dirCode == directionMap[0]) dr = -1;
            else if (dirCode == directionMap[1]) dc = 1;
            else if (dirCode == directionMap[2]) dr = 1;
            else if (dirCode == directionMap[3]) dc = -1;

            r += dr;
            c += dc;

            // Check bounds
            if (r < 0 || r >= n || c < 0 || c >= m) return false;
            // Check obstacles
            if (grid[r][c] == '#') return false;
            // Check goal
            if (grid[r][c] == 'E') return true;
        }
        return false;
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        FastScanner(File file) throws FileNotFoundException {
            br = new BufferedReader(new FileReader(file));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Solution {

    public static void main(String[] args) {
        // Increase stack size to prevent StackOverflowError on deep recursion
        new Thread(null, new Solution(), "Solution", 1 << 26).start();
    }

    public void run() {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = in.next();
            if (tStr != null) {
                int totalTestCases = Integer.parseInt(tStr);
                for (int i = 0; i < totalTestCases; i++) {
                    processTestCase(in, out);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads one test case, processes it, and writes the result.
     * All state is kept local to avoid cross-test-case contamination.
     */
    private void processTestCase(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n + 1][m + 1];
        int startX = 0;
        int startY = 0;

        // 1-indexed grid layout for easier boundary checks
        for (int i = 1; i <= n; i++) {
            String row = in.next();
            for (int j = 0; j < row.length(); j++) {
                grid[i][j + 1] = row.charAt(j);
                if (grid[i][j + 1] == 'S') {
                    startX = i;
                    startY = j + 1;
                }
            }
        }

        String directions = in.next();
        int validPathCount = countValidPermutations(grid, startX, startY, directions);
        out.println(validPathCount);
    }

    /**
     * Generates all permutations of {'U', 'L', 'R', 'D'} and counts how many
     * successfully navigate from 'S' to 'E'.
     */
    private int countValidPermutations(char[][] grid, int startX, int startY, String directions) {
        char[] directionSet = {'U', 'L', 'R', 'D'};
        int[] count = {0};
        permuteAndCheck(grid, startX, startY, directionSet, 0, directionSet.length - 1, count, directions);
        return count[0];
    }

    /**
     * Standard backtracking permutation generator.
     */
    private void permuteAndCheck(char[][] grid, int startX, int startY, char[] c, int l, int r, 
                                 int[] count, String directions) {
        if (l == r) {
            if (canReachEnd(grid, startX, startY, c, directions)) {
                count[0]++;
            }
        } else {
            for (int i = l; i <= r; i++) {
                swap(c, l, i);
                permuteAndCheck(grid, startX, startY, c, l + 1, r, count, directions);
                swap(c, l, i); // Backtrack
            }
        }
    }

    /**
     * Entry point for the recursive pathfinding simulation.
     */
    private boolean canReachEnd(char[][] grid, int x, int y, char[] c, String directions) {
        int n = grid.length - 1;
        int m = grid[0].length - 1;
        return check(grid, x, y, c, 0, directions, n, m);
    }

    /**
     * Recursively simulates movement based on the current permutation and direction string.
     */
    private boolean check(char[][] grid, int x, int y, char[] c, int ind, String directions, int n, int m) {
        // Boundary and wall checks
        if (x <= 0 || y <= 0 || x > n || y > m || grid[x][y] == '#') {
            return false;
        }
        // Reached the target
        if (grid[x][y] == 'E') {
            return true;
        }
        // No more moves to process
        if (ind >= directions.length()) {
            return false;
        }

        // Map direction string digit to the current permutation index
        int dirIndex = directions.charAt(ind) - '0';
        if (dirIndex < 0 || dirIndex >= c.length) {
            dirIndex = 0; // Fallback for malformed input
        }
        char move = c[dirIndex];

        int nextX = x;
        int nextY = y;

        switch (move) {
            case 'U': nextX--; break;
            case 'D': nextX++; break;
            case 'R': nextY++; break;
            case 'L': nextY--; break;
        }

        return check(grid, nextX, nextY, c, ind + 1, directions, n, m);
    }

    /**
     * Swaps two elements in a character array.
     */
    private void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Standard fast I/O helper using BufferedReader and StringTokenizer.
     * Replaces the fragile custom byte-buffer reader with a maintainable standard library approach.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the path permutation counting problem.
     */
    static class TaskB {
        private static final char START_CHAR = 'S';
        private static final char END_CHAR = 'E';
        private static final char WALL_CHAR = '#';
        private static final char DIR_OFFSET = '0';

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = in.nextCharacterMap(n, m);
            String pathSequence = in.nextString();

            // Extract start and end coordinates once to avoid O(24 * N * M) scanning
            int[] start = findPosition(grid, START_CHAR);
            int[] end = findPosition(grid, END_CHAR);

            int[] directions = {0, 1, 2, 3};
            int validPathCount = 0;

            // Iterate through all permutations of directions
            do {
                if (canReachDestination(grid, start, end, pathSequence, directions)) {
                    validPathCount++;
                }
            } while (PermutationUtils.nextPermutation(directions));

            out.println(validPathCount);
        }

        /**
         * Locates the coordinates of a specific character in the grid.
         */
        private int[] findPosition(char[][] grid, char target) {
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (grid[i][j] == target) {
                        return new int[]{i, j};
                    }
                }
            }
            // Should not be reached given valid problem constraints
            return new int[]{-1, -1};
        }

        /**
         * Simulates movement along the path using a given direction permutation.
         * Returns true if the path ends exactly at the destination without 
         * hitting walls or going out of bounds prematurely.
         */
        private boolean canReachDestination(char[][] grid, int[] start, int[] end, 
                                            String pathSequence, int[] directions) {
            int r = start[0];
            int c = start[1];
            int targetR = end[0];
            int targetC = end[1];

            for (int i = 0; i < pathSequence.length(); i++) {
                int dirIndex = pathSequence.charAt(i) - DIR_OFFSET;
                r += GridUtils.DELTA_ROW[directions[dirIndex]];
                c += GridUtils.DELTA_COL[directions[dirIndex]];

                // Stop early if out of bounds, hits a wall, or reaches target prematurely
                if (!GridUtils.isValidCell(r, c, grid.length, grid[0].length) ||
                    grid[r][c] == WALL_CHAR ||
                    (r == targetR && c == targetC)) {
                    break;
                }
            }
            return r == targetR && c == targetC;
        }
    }

    /**
     * Utility class for grid boundary and coordinate validation.
     */
    static class GridUtils {
        // Direction deltas: Down, Left, Up, Right
        public static final int[] DELTA_ROW = {1, 0, -1, 0};
        public static final int[] DELTA_COL = {0, -1, 0, 1};

        /**
         * Checks if the given coordinates are within the grid boundaries.
         */
        public static boolean isValidCell(int row, int col, int rowCount, int colCount) {
            return row >= 0 && row < rowCount && col >= 0 && col < colCount;
        }
    }

    /**
     * Utility class for generating the next lexicographical permutation.
     */
    static class PermutationUtils {
        /**
         * Rearranges the array into the next lexicographically greater permutation.
         * @param p The array to permute
         * @return true if a next permutation exists, false if it's the last permutation
         */
        public static boolean nextPermutation(int[] p) {
            for (int a = p.length - 2; a >= 0; --a) {
                if (p[a] < p[a + 1]) {
                    for (int b = p.length - 1; ; --b) {
                        if (p[b] > p[a]) {
                            swap(p, a, b);
                            reverse(p, a + 1, p.length - 1);
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private static void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }

        private static void reverse(int[] arr, int start, int end) {
            while (start < end) {
                swap(arr, start++, end--);
            }
        }
    }

    /**
     * Fast input reader optimized for competitive programming environments.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readChar() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = readChar();
            while (isSpaceChar(c)) {
                c = readChar();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readChar();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = readChar();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = readChar();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = readChar();
            while (isSpaceChar(c)) {
                c = readChar();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = readChar();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = readChar();
            while (isSpaceChar(c)) {
                c = readChar();
            }
            return (char) c;
        }

        public char[] nextCharacterArray(int n) {
            char[] chars = new char[n];
            for (int i = 0; i < n; i++) {
                chars[i] = nextCharacter();
            }
            return chars;
        }

        public char[][] nextCharacterMap(int n, int m) {
            char[][] map = new char[n][];
            for (int i = 0; i < n; i++) {
                map[i] = nextCharacterArray(m);
            }
            return map;
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class MazeSolver {

    /**
     * Represents the four cardinal directions with their corresponding 
     * row (dy) and column (dx) offsets.
     */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int dy;
        final int dx;

        Direction(int dy, int dx) {
            this.dy = dy;
            this.dx = dx;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt(); // rows
        int m = scanner.nextInt(); // columns

        int[][] grid = new int[n][m];
        int startX = 0, startY = 0, endX = 0, endY = 0;

        // Parse the grid and locate start/end positions
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                char ch = line.charAt(j);
                switch (ch) {
                    case 'S':
                        startX = j;
                        startY = i;
                        grid[i][j] = 0; // Walkable
                        break;
                    case 'E':
                        endX = j;
                        endY = i;
                        grid[i][j] = 0; // Walkable
                        break;
                    case '#':
                        grid[i][j] = 1; // Wall
                        break;
                    default:
                        grid[i][j] = 0; // Walkable ('.')
                        break;
                }
            }
        }

        String commands = scanner.next();
        scanner.close();

        // Generate all 24 permutations of the 4 directions
        List<List<Direction>> permutations = generatePermutations();
        int successCount = 0;

        // Test each permutation against the command sequence
        for (List<Direction> perm : permutations) {
            if (simulate(commands, perm, startX, startY, endX, endY, n, m, grid)) {
                successCount++;
            }
        }

        System.out.println(successCount);
    }

    /**
     * Generates all permutations of the 4 directions using backtracking.
     */
    private static List<List<Direction>> generatePermutations() {
        List<List<Direction>> results = new ArrayList<>();
        boolean[] used = new boolean[4];
        backtrack(new ArrayList<>(), used, results);
        return results;
    }

    private static void backtrack(List<Direction> current, boolean[] used, List<List<Direction>> results) {
        if (current.size() == 4) {
            results.add(new ArrayList<>(current));
            return;
        }
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current.add(Direction.values()[i]);
                backtrack(current, used, results);
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates movement through the grid using a specific direction permutation.
     * Returns true if the path reaches the destination, false otherwise.
     */
    private static boolean simulate(char[] commands, List<Direction> perm, int startX, int startY,
                                    int endX, int endY, int n, int m, int[][] grid) {
        int cx = startX;
        int cy = startY;

        for (char c : commands) {
            int idx = c - '0';
            if (idx < 0 || idx > 3) return false; // Invalid command digit

            Direction dir = perm.get(idx);
            cx += dir.dx;
            cy += dir.dy;

            // Check bounds and walls
            if (cx < 0 || cx >= m || cy < 0 || cy >= n || grid[cy][cx] == 1) {
                return false;
            }

            // Check if destination is reached
            if (cx == endX && cy == endY) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;
import java.util.Arrays;

/**
 * Refactored Maze Solver.
 * 
 * This program calculates the number of valid direction mappings (permutations of 
 * digits 0-3 to movement directions) that allow a path from 'S' to 'E' following 
 * a specific sequence of rules.
 * 
 * Refactoring improvements:
 * 1. Readable Class and Variable Names: 'GFG' -> 'MazeSolver', 's1/s2' -> 'startR/startC'.
 * 2. Encapsulation: Logic separated into methods (parsing, simulation, permutation).
 * 3. Type Safety: Used Enum for Directions instead of magic integers.
 * 4. Robust Input Parsing: Replaced error-prone split("") with toCharArray() and digit validation.
 * 5. Maintainability: Removed deep nesting and redundant code blocks.
 */
public class MazeSolver {

    // Enum to represent movement directions with row (dr) and column (dc) offsets
    enum Direction {
        RIGHT(0, 1),  // Row change 0, Column change +1
        LEFT(0, -1),  // Row change 0, Column change -1
        DOWN(1, 0),   // Row change +1, Column change 0
        UP(-1, 0);    // Row change -1, Column change 0

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after integers

        char[][] maze = new char[n][m];
        int startR = -1;
        int startC = -1;

        // Read the maze grid
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            // Parse characters into the grid
            for (int j = 0; j < m && j < line.length(); j++) {
                maze[i][j] = line.charAt(j);
                if (maze[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        // Read the rules string
        String rulesLine = scanner.hasNextLine() ? scanner.nextLine() : "";

        // Parse rules: extract digits from the string robustly
        int[] rules = new int[rulesLine.length()];
        int ruleCount = 0;
        for (char c : rulesLine.toCharArray()) {
            if (Character.isDigit(c)) {
                rules[ruleCount++] = c - '0';
            }
        }
        // Resize array to actual number of rules found
        if (ruleCount < rules.length) {
            rules = Arrays.copyOf(rules, ruleCount);
        }

        // Define the set of directions to permute
        List<Direction> directions = Arrays.asList(
            Direction.RIGHT, Direction.LEFT, Direction.DOWN, Direction.UP
        );

        // Generate all permutations of directions
        // Each permutation represents a mapping:
        // Index 0 (Digit 0) -> Direction at index 0 of permutation
        // Index 1 (Digit 1) -> Direction at index 1 of permutation
        // ... and so on.
        List<List<Direction>> permutations = getPermutations(directions);

        int validPathCount = 0;

        // Test each permutation to see if it allows reaching 'E'
        for (List<Direction> perm : permutations) {
            if (canReachEnd(maze, startR, startC, rules, perm)) {
                validPathCount++;
            }
        }

        System.out.println(validPathCount);
        scanner.close();
    }

    /**
     * Simulates movement on the maze based on a specific direction mapping.
     * 
     * @param maze The grid
     * @param startR Starting row
     * @param startC Starting column
     * @param rules Sequence of moves (digits 0-3)
     * @param mapping List where index corresponds to digit and value to Direction
     * @return true if 'E' is reached, false otherwise
     */
    private static boolean canReachEnd(char[][] maze, int startR, int startC, int[] rules, List<Direction> mapping) {
        // If start position is invalid, path cannot exist
        if (startR == -1 || startC == -1) {
            return false;
        }

        int r = startR;
        int c = startC;
        int n = maze.length;
        int m = maze[0].length;

        for (int ruleVal : rules) {
            // Validate rule value (should be 0-3)
            if (ruleVal < 0 || ruleVal >= 4) {
                continue; 
            }

            Direction dir = mapping.get(ruleVal);
            r += dir.dr;
            c += dir.dc;

            // Check boundaries
            if (r < 0 || r >= n || c < 0 || c >= m) {
                return false; // Hit boundary
            }

            char cell = maze[r][c];
            if (cell == '#') {
                return false; // Hit obstacle
            }
            if (cell == 'E') {
                return true; // Reached destination
            }
        }
        return false;
    }

    /**
     * Generates all permutations of a list of items using recursion.
     */
    private static List<List<Direction>> getPermutations(List<Direction> items) {
        List<List<Direction>> result = new ArrayList<>();
        if (items.isEmpty()) {
            result.add(new ArrayList<>());
            return result;
        }

        for (int i = 0; i < items.size(); i++) {
            Direction current = items.get(i);
            List<Direction> remaining = new ArrayList<>(items);
            remaining.remove(i);

            List<List<Direction>> subPerms = getPermutations(remaining);
            for (List<Direction> sub : subPerms) {
                List<Direction> newPerm = new ArrayList<>();
                newPerm.add(current);
                newPerm.addAll(sub);
                result.add(newPerm);
            }
        }
        return result;
    }
}

import java.io.*;
import java.util.*;

public class GridPathSolver {
    // Direction vectors: Down, Up, Right, Left
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private int rows, cols;
    private char[][] grid;
    private int startX, startY, endX, endY;
    private String path;
    private int validCount;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            GridPathSolver solver = new GridPathSolver();
            solver.readInput(scanner);
            solver.solve();
            out.println(solver.getValidCount());
        } catch (Exception e) {
            out.println(0);
        } finally {
            out.flush();
        }
    }

    private void readInput(FastScanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                if (cell == 'S') {
                    startX = i;
                    startY = j;
                } else if (cell == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }
        path = scanner.next();
    }

    private void solve() {
        int[] assignment = {0, 1, 2, 3};
        validCount = 0;
        generatePermutations(assignment, 0);
    }

    private void generatePermutations(int[] arr, int start) {
        if (start == arr.length) {
            if (canReachDestination(arr)) {
                validCount++;
            }
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            generatePermutations(arr, start + 1);
            swap(arr, start, i); // backtrack
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private boolean canReachDestination(int[] assignment) {
        int x = startX;
        int y = startY;

        for (int i = 0; i < path.length(); i++) {
            if (x == endX && y == endY) {
                break; // Reached destination early, stop processing remaining path
            }
            if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y] == '#') {
                return false; // Out of bounds or hit obstacle
            }
            int dirIndex = assignment[path.charAt(i) - '0'];
            x += DIRECTIONS[dirIndex][0];
            y += DIRECTIONS[dirIndex][1];
        }
        return x == endX && y == endY;
    }

    public int getValidCount() {
        return validCount;
    }

    // Fast I/O helper class to replace the original Reader
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static FastScanner in;
    private static PrintWriter out;

    public static void main(String[] args) throws IOException {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        char[] pathDigits = in.next().toCharArray();

        char[] directions = {'D', 'L', 'U', 'R'};
        List<char[]> permutations = new ArrayList<>();
        generatePermutations(permutations, directions, 0, directions.length - 1);

        int startR = -1, startC = -1;
        int endR = -1, endC = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }

        int validCount = 0;
        for (char[] perm : permutations) {
            if (isValidPath(perm, grid, startR, startC, endR, endC, n, m, pathDigits)) {
                validCount++;
            }
        }

        out.println(validCount);
        out.flush();
        out.close();
    }

    /**
     * Validates if a given direction permutation successfully navigates from start to end
     * following the sequence of digit characters in pathDigits.
     */
    private static boolean isValidPath(char[] perm, char[][] grid, int startR, int startC,
                                       int endR, int endC, int n, int m, char[] pathDigits) {
        int curR = startR;
        int curC = startC;

        for (char digit : pathDigits) {
            int dirIndex = digit - '0';
            char move = perm[dirIndex];

            if (move == 'D') curR++;
            else if (move == 'U') curR--;
            else if (move == 'L') curC--;
            else if (move == 'R') curC++;

            // Check bounds and obstacles immediately after each move
            if (curR < 0 || curR >= n || curC < 0 || curC >= m || grid[curR][curC] == '#') {
                return false;
            }
            if (curR == endR && curC == endC) {
                return true;
            }
        }
        return false;
    }

    /**
     * Generates all permutations of the character array and stores copies in the result list.
     */
    private static void generatePermutations(List<char[]> result, char[] arr, int left, int right) {
        if (left == right) {
            result.add(Arrays.copyOf(arr, arr.length));
        } else {
            for (int i = left; i <= right; i++) {
                swap(arr, left, i);
                generatePermutations(result, arr, left + 1, right);
                swap(arr, left, i);
            }
        }
    }

    private static void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        char nextChar() throws IOException {
            return next().charAt(0);
        }
    }
}

