/**
 * Refactored Grid Path Solver.
 * 
 * Key Refactoring Changes:
 * 1. Class Naming: Renamed 'BB' to 'GridPathSolver' for clarity.
 * 2. Variable Naming: Renamed generic variables (n, m, a, sx, sy, dx, dy, cnt) to descriptive names.
 * 3. Structure: Extracted logic into helper methods (simulatePath, generatePermutations) to reduce complexity.
 * 4. Control Flow: Replaced nested loops with labeled 'continue' (continue lop) with a recursive permutation generator and boolean returns.
 * 5. Resource Management: Used try-with-resources for PrintWriter to ensure proper flushing and closing.
 * 6. Error Handling: Removed 'throws Throwable' and implemented proper exception handling within the scanner and main block.
 * 7. FastScanner: Cleaned up the custom scanner implementation.
 */
public class GridPathSolver {

    public static void main(String[] args) {
        // Use try-with-resources to ensure PrintWriter is closed and flushed automatically
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastScanner scanner = new FastScanner();

            try {
                // Read grid dimensions
                String nStr = scanner.next();
                String mStr = scanner.next();

                if (nStr == null || mStr == null) return;

                int rows = Integer.parseInt(nStr);
                int cols = Integer.parseInt(mStr);

                char[][] grid = new char[rows][cols];
                int startRow = -1;
                int startCol = -1;

                // Read the grid and locate the Start position ('S')
                for (int i = 0; i < rows; i++) {
                    String line = scanner.next();
                    if (line != null) {
                        grid[i] = line.toCharArray();
                        for (int j = 0; j < cols; j++) {
                            // Ensure we don't go out of bounds if line is shorter than cols
                            if (j < grid[i].length) {
                                if (grid[i][j] == 'S') {
                                    startRow = i;
                                    startCol = j;
                                }
                            }
                        }
                    }
                }

                // Read the sequence of moves
                String moves = scanner.next();
                if (moves == null) moves = "";

                // Direction mappings: 
                // Index 0: Right  (row +0, col +1)
                // Index 1: Left   (row +0, col -1)
                // Index 2: Down   (row +1, col +0)
                // Index 3: Up     (row -1, col +0)
                // This matches the original dx={0,0,1,-1} and dy={1,-1,0,0}
                int[] dRow = {0, 0, 1, -1};
                int[] dCol = {1, -1, 0, 0};

                // 'mapping' array represents the permutation.
                // mapping[k] stores the direction index (0-3) corresponding to input digit k.
                // We need to check all permutations of {0, 1, 2, 3}.
                int[] directionMapping = {0, 1, 2, 3};

                // Counter for valid paths (using array to allow modification in recursive calls)
                int[] validPathCount = new int[1];

                // Generate all permutations of directions and check paths
                generatePermutations(0, directionMapping, grid, dRow, dCol, moves, startRow, startCol, validPathCount);

                out.println(validPathCount[0]);

            } catch (Exception e) {
                e.printStackTrace();
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Recursively generates all permutations of the directionMapping array.
     * For each permutation, it simulates the path to see if it is valid.
     */
    private static void generatePermutations(int index, int[] mapping, char[][] grid, 
                                             int[] dRow, int[] dCol, String moves, 
                                             int startRow, int startCol, int[] validPathCount) {
        // Base case: All positions filled with a permutation
        if (index == mapping.length) {
            if (simulatePath(startRow, startCol, grid, dRow, dCol, moves, mapping)) {
                validPathCount[0]++;
            }
            return;
        }

        // Recursive step: Swap elements to generate permutations
        for (int i = index; i < mapping.length; i++) {
            swap(mapping, index, i);
            generatePermutations(index + 1, mapping, grid, dRow, dCol, moves, startRow, startCol, validPathCount);
            swap(mapping, index, i); // Backtrack (restore array state)
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the path based on the current direction mapping.
     * 
     * @param r Current row
     * @param c Current column
     * @param grid The grid map
     * @param dRow Direction deltas for rows
     * @param dCol Direction deltas for cols
     * @param moves The sequence of move instructions
     * @param mapping The current permutation mapping input digits to directions
     * @return true if 'E' is reached during the path, false otherwise
     */
    private static boolean simulatePath(int r, int c, char[][] grid, int[] dRow, int[] dCol, 
                                        String moves, int[] mapping) {
        // If start position is invalid, path is invalid
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            return false;
        }

        for (int i = 0; i < moves.length(); i++) {
            int moveCharIndex = moves.charAt(i) - '0';

            // Validate input digit is within 0-3 range
            if (moveCharIndex < 0 || moveCharIndex > 3) {
                return false; 
            }

            int directionIndex = mapping[moveCharIndex];

            // Apply movement
            r += dRow[directionIndex];
            c += dCol[directionIndex];

            // Check boundaries
            if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
                return false;
            }

            // Safety check for array access
            if (c >= grid[r].length) {
                 return false;
            }

            char cell = grid[r][c];

            // Check for obstacles
            if (cell == '#') {
                return false;
            }

            // Check for destination
            if (cell == 'E') {
                return true;
            }
        }
        // If path completes without hitting 'E'
        return false;
    }

    /**
     * Fast I/O Helper Class to handle input parsing efficiently.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem by counting valid direction permutations.
 * Refactored for improved readability, maintainability, and adherence to best practices.
 */
public class Main {
    // Direction vectors: Right, Left, Up, Down
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};
    private static final int DIRECTION_COUNT = 4;

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }
        String instructions = sc.next();

        int startX = -1, startY = -1, endX = -1, endY = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startX = i;
                    startY = j;
                } else if (grid[i][j] == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }

        int validPathsCount = 0;

        // Generate all permutations of 4 distinct directions (0-3)
        for (int d0 = 0; d0 < DIRECTION_COUNT; d0++) {
            for (int d1 = 0; d1 < DIRECTION_COUNT; d1++) {
                if (d1 == d0) continue;
                for (int d2 = 0; d2 < DIRECTION_COUNT; d2++) {
                    if (d2 == d0 || d2 == d1) continue;
                    for (int d3 = 0; d3 < DIRECTION_COUNT; d3++) {
                        if (d3 == d0 || d3 == d1 || d3 == d2) continue;

                        int[] dirOrder = {d0, d1, d2, d3};
                        if (simulatePath(grid, n, m, startX, startY, endX, endY, instructions, dirOrder)) {
                            validPathsCount++;
                        }
                    }
                }
            }
        }

        System.out.println(validPathsCount);
    }

    /**
     * Simulates movement on the grid according to the given instruction string
     * and a specific permutation of directions.
     * 
     * @return true if the path successfully reaches the destination, false otherwise
     */
    private static boolean simulatePath(char[][] grid, int n, int m,
                                        int startX, int startY, int endX, int endY,
                                        String instructions, int[] dirOrder) {
        int x = startX;
        int y = startY;

        for (int i = 0; i < instructions.length(); i++) {
            int digit = instructions.charAt(i) - '0';
            int directionIndex = dirOrder[digit];

            x += DX[directionIndex];
            y += DY[directionIndex];

            if (!isWithinBounds(x, y, n, m, grid)) {
                return false;
            }
            if (x == endX && y == endY) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a coordinate is within grid bounds and not an obstacle.
     */
    private static boolean isWithinBounds(int x, int y, int n, int m, char[][] grid) {
        return x >= 0 && x < n && y >= 0 && y < m && grid[x][y] != '#';
    }

    /**
     * Fast input reader optimized for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    // Direction deltas corresponding to indices 0, 1, 2, 3 (Right, Left, Up, Down)
    private static final int[] DELTA_X = {0, 0, -1, 1};
    private static final int[] DELTA_Y = {1, -1, 0, 0};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int[] startPos = findStart(grid);
        int[] path = scanner.next().toCharArray();

        // Convert character digits to integer indices (0-3)
        for (int i = 0; i < path.length; i++) {
            path[i] -= '0';
        }

        int[] directionPermutation = {0, 1, 2, 3};
        int successCount = 0;

        // Iterate through all permutations of directions
        do {
            if (simulatePath(grid, n, m, startPos, path, directionPermutation)) {
                successCount++;
            }
        } while (nextPermutation(directionPermutation));

        System.out.println(successCount);
    }

    /**
     * Locates the starting position 'S' in the grid.
     */
    private static int[] findStart(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'S') {
                    return new int[]{i, j};
                }
            }
        }
        // Fallback; problem constraints guarantee 'S' exists
        return new int[]{0, 0};
    }

    /**
     * Simulates a path based on a specific direction permutation.
     * Returns true if the path reaches 'E', false otherwise.
     */
    private static boolean simulatePath(char[][] grid, int n, int m, int[] start, int[] path, int[] perm) {
        int x = start[0];
        int y = start[1];

        for (char stepDir : path) {
            int dirIndex = stepDir - '0';
            x += DELTA_X[perm[dirIndex]];
            y += DELTA_Y[perm[dirIndex]];

            // Check bounds and obstacles
            if (x < 0 || x >= n || y < 0 || y >= m || grid[x][y] == '#') {
                return false;
            }
            // Check for end position
            if (grid[x][y] == 'E') {
                return true;
            }
        }
        return false;
    }

    /**
     * Generates the next lexicographical permutation of an array.
     * Returns false if the array is already in descending order.
     */
    private static boolean nextPermutation(int[] arr) {
        int i = arr.length - 1;
        while (i > 0 && arr[i - 1] >= arr[i]) {
            i--;
        }
        if (i <= 0) return false;

        int j = arr.length - 1;
        while (arr[j] <= arr[i - 1]) {
            j--;
        }

        swap(arr, i - 1, j);
        reverse(arr, i, arr.length - 1);
        return true;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private static void reverse(int[] arr, int i, int j) {
        while (i < j) {
            int temp = arr[i];
            arr[i++] = arr[j];
            arr[j--] = temp;
        }
    }

    /**
     * A maintainable, standard FastScanner implementation.
     * Replaces the overly complex custom I/O class with a clean, readable alternative.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;

public class Main {
    // Direction vectors: 0=Left, 1=Down, 2=Right, 3=Up
    private static final int[][] DIRECTIONS = {
        {0, -1},
        {1, 0},
        {0, 1},
        {-1, 0}
    };

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure proper cleanup of I/O streams
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out))) {

            String[] dims = reader.readLine().trim().split("\\s+");
            int n = Integer.parseInt(dims[0]);
            int m = Integer.parseInt(dims[1]);

            String[] field = new String[n];
            int startX = 0;
            int startY = 0;

            for (int i = 0; i < n; i++) {
                field[i] = reader.readLine();
                int sIndex = field[i].indexOf('S');
                if (sIndex != -1) {
                    startX = i;
                    startY = sIndex;
                }
            }

            String moveStr = reader.readLine().trim();
            int[] moves = new int[moveStr.length()];
            for (int i = 0; i < moveStr.length(); i++) {
                // Efficiently convert char digit to int
                moves[i] = moveStr.charAt(i) - '0';
            }

            int successCount = countSuccessfulPermutations(moves, field, n, m, startX, startY);
            writer.write(Integer.toString(successCount));
        }
    }

    private static int countSuccessfulPermutations(int[] moves, String[] field, int n, int m, int startX, int startY) {
        int[] currentPerm = new int[4];
        boolean[] used = new boolean[4];
        return generateAndCount(currentPerm, used, 0, moves, field, n, m, startX, startY);
    }

    // Generates all permutations of direction indices and counts successful paths
    private static int generateAndCount(int[] currentPerm, boolean[] used, int depth, int[] moves, 
                                        String[] field, int n, int m, int startX, int startY) {
        if (depth == 4) {
            return simulatePath(currentPerm, moves, field, n, m, startX, startY) ? 1 : 0;
        }
        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                currentPerm[depth] = i;
                count += generateAndCount(currentPerm, used, depth + 1, moves, field, n, m, startX, startY);
                used[i] = false;
            }
        }
        return count;
    }

    // Simulates movement along a given direction permutation
    private static boolean simulatePath(int[] dirOrder, int[] moves, String[] field, int n, int m, 
                                        int startX, int startY) {
        int x = startX;
        int y = startY;

        for (int move : moves) {
            int[] dir = DIRECTIONS[dirOrder[move]];
            x += dir[0];
            y += dir[1];

            // Check boundary conditions
            if (x < 0 || x >= n || y < 0 || y >= m) {
                return false;
            }

            char cell = field[x].charAt(y);
            if (cell == '#') {
                return false; // Hit obstacle
            }
            if (cell == 'E') {
                return true; // Reached destination
            }
        }
        return false;
    }
}

