    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a maze navigation problem by testing all valid permutations of
 * direction mappings (South, North, East, West) against a given sequence.
 */
public class USACO {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] maze = new char[rows][cols];
            int startX = -1;
            int startY = -1;

            // Read maze grid and locate the starting position 'S'
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                if (line == null) break;
                for (int j = 0; j < cols; j++) {
                    maze[i][j] = line.charAt(j);
                    if (maze[i][j] == 'S') {
                        startX = j;
                        startY = i;
                    }
                }
            }

            String directionSequence = reader.readLine();
            if (directionSequence == null) {
                directionSequence = "";
            }

            int validPathCount = countValidMappings(rows, cols, maze, startX, startY, directionSequence);
            System.out.println(validPathCount);
        }
    }

    /**
     * Iterates through all permutations of 4 distinct digits (0-3) to map
     * to South, North, East, and West directions. Simulates each mapping
     * and counts how many successfully reach the exit 'E'.
     */
    private static int countValidMappings(int rows, int cols, char[][] maze,
                                          int startX, int startY, String sequence) {
        int validCount = 0;

        // 4^4 = 256 combinations. Each combination represents a potential mapping
        // of the digits 0-3 to the four cardinal directions.
        for (int i = 0; i < 256; i++) {
            int southDir = i % 4;
            int northDir = (i / 4) % 4;
            int eastDir = (i / 16) % 4;
            int westDir = (i / 64) % 4;

            // Check if all four direction digits are distinct
            if (areDistinct(southDir, northDir, eastDir, westDir)) {
                if (simulatePath(rows, cols, maze, startX, startY, sequence,
                                 southDir, northDir, eastDir, westDir)) {
                    validCount++;
                }
            }
        }
        return validCount;
    }

    private static boolean areDistinct(int a, int b, int c, int d) {
        return a != b && a != c && a != d && b != c && b != d && c != d;
    }

    /**
     * Simulates movement on the maze according to the given direction sequence
     * and the provided digit-to-direction mapping.
     * Returns true if the path reaches 'E' at least once without dying first.
     */
    private static boolean simulatePath(int rows, int cols, char[][] maze,
                                        int startX, int startY, String sequence,
                                        int southDir, int northDir, int eastDir, int westDir) {
        int x = startX;
        int y = startY;
        boolean reachedExit = false;
        boolean isDead = false;

        for (int i = 0; i < sequence.length(); i++) {
            int currentDir = sequence.charAt(i) - '0';
            int dx = 0;
            int dy = 0;

            // Determine movement based on mapping
            if (currentDir == southDir) dy = 1;
            else if (currentDir == northDir) dy = -1;
            else if (currentDir == eastDir) dx = 1;
            else if (currentDir == westDir) dx = -1;

            // Apply movement
            x += dx;
            y += dy;

            // Check for out-of-bounds or wall collision
            if (x < 0 || x >= cols || y < 0 || y >= rows || maze[y][x] == '#') {
                isDead = true;
            }

            // Check for exit. Only count if not already dead.
            // Mark as dead to prevent double-counting the same path.
            if (!isDead && maze[y][x] == 'E') {
                reachedExit = true;
                isDead = true;
            }
        }

        return reachedExit;
    }
}

import java.util.Scanner;
import java.util.Optional;

/**
 * Main class containing solutions for competitive programming problems.
 * Refactored for improved maintainability, readability, type safety, and resource management.
 */
public class Main {

    // ================= Constants =================

    /** Characters considered valid for Problem A */
    private static final String VALID_CHARS = "aiueo13579";

    /** Grid boundary and special cell markers for Problem B */
    private static final char BOUNDARY = '#';
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';

    /**
     * Direction mappings: 0=Left, 1=Up, 2=Right, 3=Down
     * Format: [dr, dc]
     */
    private static final int[] DIR_DR = {0, -1, 0, 1};
    private static final int[] DIR_DC = {-1, 0, 1, 0};

    // ================= Entry Point =================

    public static void main(String[] args) {
        // Use try-with-resources to guarantee Scanner is closed, preventing resource leaks
        try (Scanner sc = new Scanner(System.in)) {
            Main solution = new Main();
            solution.solveB(sc);
        }
    }

    // ================= Problem Solvers =================

    /**
     * Solves Problem A: Counts vowels and odd digits in a string.
     */
    private void solveA(Scanner sc) {
        if (!sc.hasNext()) return;
        String str = sc.next();
        long count = str.chars()
                .filter(ch -> VALID_CHARS.indexOf(ch) != -1)
                .count();
        System.out.println(count);
    }

    /**
     * Solves Problem B: Grid simulation evaluating all permutations of directional mappings.
     */
    private void solveB(Scanner sc) {
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // Consume the newline character after M

        // Initialize grid with padding boundaries
        char[][] grid = new char[n + 2][m + 2];
        for (int r = 0; r <= n + 1; r++) {
            for (int c = 0; c <= m + 1; c++) {
                grid[r][c] = BOUNDARY;
            }
        }

        int startRow = -1;
        int startCol = -1;

        // Read grid rows and locate the starting position
        for (int r = 1; r <= n; r++) {
            String line = sc.nextLine();
            for (int c = 1; c <= m; c++) {
                char ch = line.charAt(c - 1);
                grid[r][c] = ch;
                if (ch == START_CHAR) {
                    startRow = r;
                    startCol = c;
                }
            }
        }

        String instructions = sc.next();
        long successCount = 0;

        // Iterate over all permutations of 4 directions (4! = 24 combinations)
        for (int d0 = 0; d0 < 4; d0++) {
            for (int d1 = 0; d1 < 4; d1++) {
                if (d1 == d0) continue;
                for (int d2 = 0; d2 < 4; d2++) {
                    if (d2 == d0 || d2 == d1) continue;
                    for (int d3 = 0; d3 < 4; d3++) {
                        if (d3 == d0 || d3 == d1 || d3 == d2) continue;

                        // Map instruction characters '0'-'3' to actual direction indices
                        int[] directionMap = {d0, d1, d2, d3};
                        int row = startRow;
                        int col = startCol;
                        boolean reachedEnd = false;

                        // Simulate movement based on the instruction string
                        for (int i = 0; i < instructions.length(); i++) {
                            char asc = instructions.charAt(i);
                            int dirIndex = asc - '0';
                            int dir = directionMap[dirIndex];

                            row += DIR_DR[dir];
                            col += DIR_DC[dir];

                            if (grid[row][col] == BOUNDARY) {
                                break;
                            }
                            if (grid[row][col] == END_CHAR) {
                                successCount++;
                                reachedEnd = true;
                                break;
                            }
                        }
                    }
                }
            }
        }
        System.out.println(successCount);
    }

    // Stub methods for Problems C-F (maintained for template completeness)
    private void solveC(Scanner sc) { if (sc.hasNextInt()) System.out.println(sc.nextInt()); }
    private void solveD(Scanner sc) { if (sc.hasNextInt()) System.out.println(sc.nextInt()); }
    private void solveE(Scanner sc) { if (sc.hasNextInt()) System.out.println(sc.nextInt()); }
    private void solveF(Scanner sc) { if (sc.hasNextInt()) System.out.println(sc.nextInt()); }

    // ================= Data Structures & Algorithms =================

    /**
     * Interface representing a weighted directed graph.
     */
    static interface Graph {
        void link(int from, int to, long cost);
        Optional<Long> getCost(int from, int to);
        int getVertexNum();
    }

    /**
     * Interface for computing maximum flow in a network.
     */
    static interface FlowResolver {
        long maxFlow(int from, int to);
    }

    /**
     * Adjacency matrix implementation of a graph using primitive arrays for performance.
     */
    static class ArrayGraph implements Graph {
        private final long[][] capacity;
        private final int vertexCount;

        public ArrayGraph(int vertexCount) {
            this.vertexCount = vertexCount;
            this.capacity = new long[vertexCount][vertexCount];
        }

        @Override
        public void link(int from, int to, long cost) {
            capacity[from][to] = cost;
        }

        @Override
        public Optional<Long> getCost(int from, int to) {
            long c = capacity[from][to];
            return c > 0 ? Optional.of(c) : Optional.empty();
        }

        @Override
        public int getVertexNum() {
            return vertexCount;
        }
    }

    /**
     * DFS-based Max Flow resolver. Modifies the graph in-place to simulate residual edges.
     */
    static class DfsFlowResolver implements FlowResolver {
        private final Graph graph;
        // Safe upper bound to prevent overflow during residual capacity calculations
        private static final long MAX_SAFE_FLOW = Long.MAX_VALUE / 3;

        public DfsFlowResolver(Graph graph) {
            this.graph = graph;
        }

        @Override
        public long maxFlow(int from, int to) {
            long totalFlow = 0;
            long currentFlow;
            do {
                currentFlow = findAugmentingPath(from, to, MAX_SAFE_FLOW, new boolean[graph.getVertexNum()]);
                totalFlow += currentFlow;
            } while (currentFlow > 0);
            return totalFlow;
        }

        private long findAugmentingPath(int current, int target, long flow, boolean[] visited) {
            visited[current] = true;
            if (current == target) {
                return flow;
            }
            for (int next = 0; next < graph.getVertexNum(); next++) {
                if (visited[next]) continue;

                Optional<Long> capacity = graph.getCost(current, next);
                if (capacity.isPresent() && capacity.get() > 0) {
                    long pushed = Math.min(flow, capacity.get());
                    long returned = findAugmentingPath(next, target, pushed, visited);
                    if (returned > 0) {
                        graph.link(current, next, capacity.get() - returned);
                        graph.link(next, current, graph.getCost(next, current).orElse(0L) + returned);
                        return returned;
                    }
                }
            }
            return 0;
        }
    }

    /**
     * Binary Indexed Tree (Fenwick Tree) for efficient prefix sum queries and updates.
     */
    static class BinaryIndexedTree {
        private final long[] tree;

        public BinaryIndexedTree(int size) {
            this.tree = new long[size + 1];
        }

        /**
         * Adds a value to a specific index.
         */
        public void add(int index, long value) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i] += value;
            }
        }

        /**
         * Returns the prefix sum up to a specific index.
         */
        public long query(int index) {
            long sum = 0;
            for (int i = index; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }
}

import java.util.Scanner;

public class TaskB {
    // Constants for direction indices to improve readability and maintainability
    private static final int DIR_UP = 0;
    private static final int DIR_DOWN = 1;
    private static final int DIR_LEFT = 2;
    private static final int DIR_RIGHT = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions (rows and columns)
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after the dimensions

        char[][] maze = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        // Read the maze grid
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // Convert line to char array for easier indexing
            // Note: Assuming valid input where line length matches cols
            if (line.length() >= cols) {
                maze[i] = line.substring(0, cols).toCharArray();
            } else {
                maze[i] = line.toCharArray();
            }

            // Find the starting position 'S'
            int sIndex = line.indexOf('S');
            if (sIndex != -1) {
                startRow = i;
                startCol = sIndex;
            }
        }

        // Read the movement instructions
        String instructions = scanner.hasNextLine() ? scanner.nextLine() : "";

        // Prepare for permutation search
        // We need to map each direction (UP, DOWN, LEFT, RIGHT) to a unique input digit (0, 1, 2, 3).
        // currentMapping[d] stores the input digit that corresponds to direction d.
        int[] currentMapping = new int[4]; 
        boolean[] usedDigits = new boolean[4]; // To track used digits in permutation
        int[] count = {0}; // Use array to allow modification in recursive method

        // Start permutation generation
        generatePermutations(0, currentMapping, usedDigits, maze, startRow, startCol, instructions, count);

        System.out.println(count[0]);
        scanner.close();
    }

    /**
     * Recursively generates all permutations of digits 0-3 assigned to directions.
     * @param directionIndex The current direction index being assigned (0 to 3)
     * @param currentMapping Array storing which digit triggers which direction
     * @param usedDigits Boolean array to track which digits have been used
     * @param maze The maze grid
     * @param startRow Starting row coordinate
     * @param startCol Starting column coordinate
     * @param instructions The string of movement commands
     * @param count Mutable integer holder for the result count
     */
    private static void generatePermutations(int directionIndex, int[] currentMapping, boolean[] usedDigits,
                                             char[][] maze, int startRow, int startCol,
                                             String instructions, int[] count) {
        // Base case: All directions (0-3) have been assigned a digit
        if (directionIndex == 4) {
            if (simulatePath(maze, startRow, startCol, instructions, currentMapping)) {
                count[0]++;
            }
            return;
        }

        // Try assigning each unused digit to the current direction
        for (int digit = 0; digit < 4; digit++) {
            if (!usedDigits[digit]) {
                usedDigits[digit] = true;
                currentMapping[directionIndex] = digit;

                // Recurse to assign the next direction
                generatePermutations(directionIndex + 1, currentMapping, usedDigits, maze, startRow, startCol, instructions, count);

                // Backtrack
                usedDigits[digit] = false;
            }
        }
    }

    /**
     * Simulates the path based on the current direction mapping.
     * Returns true if the path reaches 'E', false otherwise.
     */
    private static boolean simulatePath(char[][] maze, int startRow, int startCol,
                                        String instructions, int[] dirToDigit) {
        int x = startCol;
        int y = startRow;
        int rows = maze.length;
        int cols = (rows > 0) ? maze[0].length : 0;

        for (int i = 0; i < instructions.length(); i++) {
            char c = instructions.charAt(i);
            // Convert char digit to integer value (e.g., '1' -> 1)
            // Original code used ASCII '0' (48).
            int inputDigit = c - 48;

            // Find which direction corresponds to this input digit
            // dirToDigit array maps Direction Index -> Input Digit
            int direction = -1;
            for (int d = 0; d < 4; d++) {
                if (dirToDigit[d] == inputDigit) {
                    direction = d;
                    break;
                }
            }

            // If the digit doesn't map to any direction (shouldn't happen with valid permutation), skip
            if (direction == -1) continue;

            // Update coordinates based on direction
            if (direction == DIR_UP) {
                y--;
            } else if (direction == DIR_DOWN) {
                y++;
            } else if (direction == DIR_LEFT) {
                x--;
            } else if (direction == DIR_RIGHT) {
                x++;
            }

            // Check boundaries
            if (x < 0 || x >= cols || y < 0 || y >= rows) {
                return false;
            }

            // Safety check for malformed grid lines (shorter than expected)
            if (x >= maze[y].length) {
                return false;
            }

            // Check cell content
            char currentCell = maze[y][x];

            if (currentCell == '#') {
                return false; // Hit obstacle
            }
            if (currentCell == 'E') {
                return true; // Reached destination
            }
        }
        return false;
    }
}

import java.util.*;

/**
 * Solves a grid pathfinding problem where a sequence of directional moves
 * must be followed to reach an endpoint. Counts how many direction 
 * permutations allow a valid path from Start to End.
 */
public class GridPathSolver {
    private int numRows;
    private int numCols;
    private char[][] grid;
    private int startRow, startCol, endRow, endCol;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after dimensions

            GridPathSolver solver = new GridPathSolver(rows, cols);
            solver.readGrid(scanner);

            String sequence = scanner.hasNextLine() ? scanner.nextLine().trim() : "";
            System.out.println(solver.countValidPermutations(sequence));
        } finally {
            scanner.close();
        }
    }

    public GridPathSolver(int rows, int cols) {
        this.numRows = rows;
        this.numCols = cols;
        this.grid = new char[rows][cols];
    }

    /**
     * Reads the grid from input, locates 'S' (Start) and 'E' (End).
     */
    private void readGrid(Scanner scanner) {
        for (int i = 0; i < numRows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < numCols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    /**
     * Generates all permutations of directions and counts how many allow a valid path.
     */
    private int countValidPermutations(String sequence) {
        List<int[]> permutations = new ArrayList<>();
        int[] initialOrder = {0, 1, 2, 3};
        permute(initialOrder, 0, permutations);

        int validCount = 0;
        for (int[] dirOrder : permutations) {
            if (simulatePath(dirOrder, sequence) == 1) {
                validCount++;
            }
        }
        return validCount;
    }

    /**
     * Recursively generates all permutations of the array.
     */
    private void permute(int[] arr, int start, List<int[]> result) {
        if (start == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            permute(arr, start + 1, result);
            swap(arr, start, i);
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates movement along the grid following the direction sequence.
     * Returns 1 if the endpoint is reached, 0 otherwise.
     */
    private int simulatePath(int[] directionOrder, String sequence) {
        int r = startRow;
        int c = startCol;

        for (int i = 0; i < sequence.length(); i++) {
            int d = sequence.charAt(i) - '0';
            int[] nextPos = getMovedPosition(r, c, d, directionOrder);

            if (nextPos == null) {
                return 0; // Invalid move or obstacle encountered
            }

            r = nextPos[0];
            c = nextPos[1];

            if (r == endRow && c == endCol) {
                return 1; // Destination reached
            }
        }
        return 0;
    }

    /**
     * Calculates the next position based on the direction code and current mapping.
     * Returns null if the move is out of bounds or hits an obstacle.
     */
    private int[] getMovedPosition(int r, int c, int d, int[] directionOrder) {
        // Find which index in the permutation corresponds to direction d
        int dirIndex = -1;
        for (int i = 0; i < 4; i++) {
            if (directionOrder[i] == d) {
                dirIndex = i;
                break;
            }
        }
        if (dirIndex == -1) return null;

        int dr = 0, dc = 0;
        // Map permutation indices to cardinal directions
        switch (dirIndex) {
            case 0: dr = -1; break; // Up
            case 1: dr = 1;  break; // Down
            case 2: dc = 1;  break; // Right
            case 3: dc = -1; break; // Left
        }

        int nr = r + dr;
        int nc = c + dc;

        if (!inBounds(nr, nc) || grid[nr][nc] == '#') {
            return null;
        }
        return new int[]{nr, nc};
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < numRows && c >= 0 && c < numCols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid path problem by checking all permutations of direction mappings.
 * Reads a grid with start ('S') and end ('E') positions, along with a sequence of directions.
 * Counts how many permutations of direction mappings allow a valid path from S to E.
 */
public class PathPermutationSolver {

    // Direction vectors corresponding to indices 0, 1, 2, 3
    // 0: Right, 1: Down, 2: Left, 3: Up
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {1, 0},  // Down
        {0, -1}, // Left
        {-1, 0}  // Up
    };

    private int rows, cols;
    private int startRow, startCol, endRow, endCol;
    private char[][] grid;
    private char[] directionSequence;

    public static void main(String[] args) {
        PathPermutationSolver solver = new PathPermutationSolver();
        try {
            solver.solve();
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
        }
    }

    private void solve() throws IOException {
        FastScanner scanner = new FastScanner();

        rows = scanner.nextInt();
        cols = scanner.nextInt();

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (cell == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        directionSequence = scanner.next().toCharArray();

        int[] permutation = {0, 1, 2, 3};
        int validCount = 0;

        // Check the initial permutation, then generate subsequent ones
        do {
            if (checkPath(permutation)) {
                validCount++;
            }
        } while (nextPermutation(permutation));

        System.out.println(validCount);
    }

    /**
     * Simulates movement based on a direction permutation.
     * Returns true if the path reaches 'E' without hitting boundaries or walls.
     */
    private boolean checkPath(int[] permutation) {
        int row = startRow;
        int col = startCol;

        for (char c : directionSequence) {
            int originalDirection = c - '0';
            int mappedDirection = permutation[originalDirection];

            row += DIRECTIONS[mappedDirection][0];
            col += DIRECTIONS[mappedDirection][1];

            if (isOutOfBounds(row, col) || grid[row][col] == '#') {
                return false;
            }
            if (grid[row][col] == 'E') {
                return true;
            }
        }

        return row == endRow && col == endCol;
    }

    private boolean isOutOfBounds(int row, int col) {
        return row < 0 || row >= rows || col < 0 || col >= cols;
    }

    /**
     * Generates the next lexicographical permutation of the array in-place.
     * Returns false when the array is in descending order (last permutation).
     */
    private boolean nextPermutation(int[] p) {
        int i = p.length - 2;
        while (i >= 0 && p[i] >= p[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }

        int j = p.length - 1;
        while (p[j] <= p[i]) {
            j--;
        }

        swap(p, i, j);

        int left = i + 1;
        int right = p.length - 1;
        while (left < right) {
            swap(p, left, right);
            left++;
            right--;
        }
        return true;
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Lightweight scanner for whitespace-delimited tokens.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class GridPathSolver {

    // Constants for Cell Types
    private static final int CELL_WALL = 0;
    private static final int CELL_PATH = 1;
    private static final int CELL_EXIT = 10;

    // Constants for Directions (Indices)
    private static final int DIR_LEFT = 0;
    private static final int DIR_UP = 1;
    private static final int DIR_RIGHT = 2;
    private static final int DIR_DOWN = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Parse grid and find start position
        int[][] grid = new int[rows][cols];
        int[] startCoords = new int[2]; // [row, col]
        startCoords[0] = 0; 
        startCoords[1] = 0;

        parseGrid(scanner, rows, cols, grid, startCoords);

        // Read movement path
        String path = "";
        if (scanner.hasNext()) {
            path = scanner.next();
        }

        // Generate all permutations of directions "0123"
        List<String> permutations = generatePermutations("0123");

        int totalCount = 0;

        // Simulate path for each permutation
        for (String perm : permutations) {
            totalCount += simulate(grid, path, perm, startCoords[0], startCoords[1]);
        }

        System.out.println(totalCount);
        scanner.close();
    }

    /**
     * Parses the grid input from the scanner.
     * Maps characters to integer values.
     */
    private static void parseGrid(Scanner scanner, int rows, int cols, int[][] grid, int[] startCoords) {
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                if (c == '#') {
                    grid[i][j] = CELL_WALL;
                } else if (c == '.') {
                    grid[i][j] = CELL_PATH;
                } else if (c == 'E') {
                    grid[i][j] = CELL_EXIT;
                } else if (c == 'S') {
                    grid[i][j] = CELL_PATH; // Start is treated as a path
                    startCoords[0] = i;
                    startCoords[1] = j;
                } else {
                    // Fallback, though problem constraints usually imply valid chars
                    grid[i][j] = CELL_PATH; 
                }
            }
        }
    }

    /**
     * Simulates the path based on a specific direction permutation.
     * Returns the number of exits reached.
     */
    private static int simulate(int[][] grid, String path, String permutation, int startX, int startY) {
        int x = startX;
        int y = startY;
        int hits = 0;

        // Pre-calculate direction mapping based on permutation
        // permutation is a string like "2013"
        // index 0 corresponds to input command '0'
        // value at index 0 is the direction index to take
        int[] dirMap = new int[4];
        for (int k = 0; k < 4; k++) {
            dirMap[k] = permutation.charAt(k) - '0';
        }

        for (int i = 0; i < path.length(); i++) {
            char command = path.charAt(i);
            if (command < '0' || command > '3') continue; // Skip invalid commands if any

            int directionIndex = dirMap[command - '0'];

            // Determine move based on direction index
            int dx = 0;
            int dy = 0;

            switch (directionIndex) {
                case DIR_LEFT:  // 0
                    dy = -1;
                    break;
                case DIR_UP:    // 1
                    dx = -1;
                    break;
                case DIR_RIGHT: // 2
                    dy = 1;
                    break;
                case DIR_DOWN:  // 3
                    dx = 1;
                    break;
                default:
                    continue; // Should not happen
            }

            // Check bounds
            int nextX = x + dx;
            int nextY = y + dy;

            if (nextX < 0 || nextX >= grid.length || nextY < 0 || nextY >= grid[0].length) {
                break; // Out of bounds, stop path
            }

            int cellValue = grid[nextX][nextY];

            if (cellValue == CELL_WALL) {
                break; // Hit wall, stop path
            } else if (cellValue == CELL_EXIT) {
                hits++;
                break; // Hit exit, count and stop path
            } else {
                // It's a path (CELL_PATH), move there
                x = nextX;
                y = nextY;
            }
        }
        return hits;
    }

    /**
     * Generates all permutations of the input string.
     */
    private static List<String> generatePermutations(String str) {
        List<String> results = new ArrayList<>();
        permute(str.toCharArray(), 0, results);
        return results;
    }

    private static void permute(char[] arr, int k, List<String> results) {
        if (k == arr.length) {
            results.add(new String(arr));
        } else {
            for (int i = k; i < arr.length; i++) {
                swap(arr, i, k);
                permute(arr, k + 1, results);
                swap(arr, i, k); // Backtrack
            }
        }
    }

    private static void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.StringTokenizer;

public class B {
    // Direction vectors: Up, Right, Down, Left
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int numRows = sc.nextInt();
        int numCols = sc.nextInt();

        char[][] grid = new char[numRows][];
        int startRow = -1;
        int startCol = -1;

        // Read grid and locate start position
        for (int i = 0; i < numRows; i++) {
            grid[i] = sc.next().toCharArray();
            for (int j = 0; j < numCols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Parse movement sequence (digits 0-3 map to direction indices)
        String seqStr = sc.next();
        int[] seq = new int[seqStr.length()];
        for (int i = 0; i < seqStr.length(); i++) {
            seq[i] = seqStr.charAt(i) - '0';
        }

        // Generate all permutations of directions and count valid paths to 'E'
        int[] perm = new int[4];
        boolean[] used = new boolean[4];
        int[] count = {0}; // Wrapper to allow modification within recursion

        generatePermutations(perm, 0, used, seq, grid, startRow, startCol, count);
        System.out.println(count[0]);
    }

    /**
     * Recursively generates all permutations of direction indices (0-3).
     * For each permutation, simulates the path and increments the counter if 'E' is reached.
     */
    private static void generatePermutations(int[] perm, int idx, boolean[] used, int[] seq, 
                                             char[][] grid, int startRow, int startCol, int[] count) {
        if (idx == 4) {
            if (simulatePath(perm, seq, grid, startRow, startCol)) {
                count[0]++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[idx] = i;
                generatePermutations(perm, idx + 1, used, seq, grid, startRow, startCol, count);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates movement according to the sequence and direction permutation.
     * Returns true if 'E' is reached, false if out of bounds, obstacle hit, or sequence ends.
     */
    private static boolean simulatePath(int[] perm, int[] seq, char[][] grid, int startRow, int startCol) {
        int r = startRow;
        int c = startCol;

        for (int step : seq) {
            int dirIdx = perm[step];
            r += DX[dirIdx];
            c += DY[dirIdx];

            if (!isValid(grid, r, c)) {
                return false;
            }
            if (grid[r][c] == 'E') {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within bounds and not an obstacle.
     */
    private static boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[r].length && grid[r][c] != '#';
    }

    /**
     * Fast I/O scanner for competitive programming style inputs.
     */
    public static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;

public class TaskB {
    // Magic constants replaced with meaningful names
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char WALL_CHAR = '#';

    // Direction deltas: Down, Right, Up, Left
    private static final int[] DELTA_ROW = {1, 0, -1, 0};
    private static final int[] DELTA_COL = {0, 1, 0, -1};

    public static void main(String[] args) {
        new TaskB(System.in, System.out);
    }

    public TaskB(InputStream inputStream, OutputStream outputStream) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        PrintWriter writer = new PrintWriter(outputStream);

        try {
            Solver solver = new Solver(reader, writer);
            Thread thread = new Thread(solver, "TaskB-Solver");
            // Increase stack size to prevent StackOverflowError during deep recursion
            thread.setStackSize(1 << 29);
            thread.start();
            thread.join();
        } catch (IOException | InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Failed to execute solver", e);
        } finally {
            try {
                reader.close();
            } catch (IOException e) {
                // Ignore close errors on input stream
            }
            writer.flush();
            writer.close();
        }
    }

    /**
     * Encapsulates the core solving logic. Separated from I/O and thread management
     * for better testability and maintainability.
     */
    static class Solver implements Runnable {
        private final BufferedReader reader;
        private final PrintWriter writer;

        private int rows, cols, stepCount;
        private char[][] grid;
        private char[] directionSequence;
        private int[] directionPermutation;

        Solver(BufferedReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        @Override
        public void run() {
            try {
                solve();
            } catch (IOException e) {
                throw new RuntimeException("IO error during solving", e);
            }
        }

        void solve() throws IOException {
            String[] tokens = reader.readLine().trim().split("\\s+");
            rows = Integer.parseInt(tokens[0]);
            cols = Integer.parseInt(tokens[1]);

            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            directionSequence = reader.readLine().toCharArray();
            stepCount = directionSequence.length;

            // Locate starting position
            int startRow = -1, startCol = -1;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        startRow = i;
                        startCol = j;
                        break;
                    }
                }
                if (startRow != -1) break;
            }

            // directionPermutation maps a requested direction index (0-3) to the actual movement index.
            // Initially, requested direction N maps to actual direction N.
            directionPermutation = new int[]{0, 1, 2, 3};
            int successfulPaths = 0;

            // Evaluate the initial permutation, then generate all subsequent permutations
            do {
                if (dfs(startRow, startCol, 0)) {
                    successfulPaths++;
                }
            } while (nextPermutation(directionPermutation));

            writer.println(successfulPaths);
        }

        /**
         * Depth-First Search to determine if a valid path exists from (row, col)
         * following the direction sequence under the current permutation.
         */
        private boolean dfs(int row, int col, int stepIndex) {
            // Boundary check
            if (row < 0 || row >= rows || col < 0 || col >= cols) {
                return false;
            }

            // Reached destination
            if (grid[row][col] == END_CHAR) {
                return true;
            }

            // Hit wall or exhausted all steps
            if (grid[row][col] == WALL_CHAR || stepIndex == stepCount) {
                return false;
            }

            // Determine movement direction based on current permutation
            // Note: Input is guaranteed to contain '0'-'3'
            int requestedDir = directionSequence[stepIndex] - '0';
            int actualDirIndex = directionPermutation[requestedDir];

            // Recurse to next step
            return dfs(row + DELTA_ROW[actualDirIndex],
                       col + DELTA_COL[actualDirIndex],
                       stepIndex + 1);
        }

        /**
         * Generates the next lexicographical permutation of the array in-place.
         * Returns false if the array is already in descending order.
         */
        private boolean nextPermutation(int[] array) {
            if (array.length <= 1) return false;

            // 1. Find the largest index i such that array[i] < array[i + 1]
            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            // 2. If no such index exists, the permutation is the last one
            if (i < 0) return false;

            // 3. Find the largest index j such that array[j] > array[i]
            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            // 4. Swap array[i] and array[j]
            swap(array, i, j);

            // 5. Reverse the sequence from array[i + 1] up to the end
            int left = i + 1;
            int right = array.length - 1;
            while (left < right) {
                swap(array, left, right);
                left++;
                right--;
            }

            return true;
        }

        private void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class MazeSolver {

    // Direction vectors: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
        {0, 1},   // Right
        {0, -1},  // Left
        {1, 0},   // Down
        {-1, 0}   // Up
    };

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char WALL_CHAR = '#';

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read grid dimensions
        String rowsStr = scanner.next();
        String colsStr = scanner.next();
        if (rowsStr == null || colsStr == null) return;

        int rows = Integer.parseInt(rowsStr);
        int cols = Integer.parseInt(colsStr);

        char[][] maze = new char[rows][];
        int startRow = -1;
        int startCol = -1;

        // Parse maze and locate start position
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            if (line == null) break;
            maze[i] = line.toCharArray();
            int startIdx = line.indexOf(START_CHAR);
            if (startIdx != -1) {
                startRow = i;
                startCol = startIdx;
            }
        }

        String commands = scanner.next();
        if (commands == null) {
            System.out.println(0);
            return;
        }

        int validPermutationCount = countValidPermutations(maze, commands, startRow, startCol);
        System.out.println(validPermutationCount);
    }

    /**
     * Generates all permutations of directions [0,1,2,3] and counts how many
     * allow a valid path from start to end using the given commands.
     */
    private static int countValidPermutations(char[][] maze, String commands, int startRow, int startCol) {
        int[] permutation = {0, 1, 2, 3};
        return generatePermutations(maze, commands, permutation, 0, startRow, startCol);
    }

    /**
     * Recursive backtracking to generate permutations.
     */
    private static int generatePermutations(char[][] maze, String commands, int[] permutation, int index, int startRow, int startCol) {
        if (index == permutation.length) {
            return canNavigate(maze, commands, permutation, startRow, startCol) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < permutation.length; i++) {
            swap(permutation, index, i);
            count += generatePermutations(maze, commands, permutation, index + 1, startRow, startCol);
            swap(permutation, index, i); // Backtrack
        }
        return count;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates movement through the maze using a specific direction mapping.
     * Returns true if the path stays within bounds, avoids walls, and reaches the end.
     */
    private static boolean canNavigate(char[][] maze, String commands, int[] directionMap, int startRow, int startCol) {
        int curRow = startRow;
        int curCol = startCol;

        for (int k = 0; k < commands.length(); k++) {
            int cmdIndex = commands.charAt(k) - '0';

            // Validate command range to prevent ArrayIndexOutOfBoundsException
            if (cmdIndex < 0 || cmdIndex > 3) {
                return false;
            }

            int dir = directionMap[cmdIndex];
            curRow += DIRECTIONS[dir][0];
            curCol += DIRECTIONS[dir][1];

            // Boundary and wall checks (short-circuit evaluation ensures safety)
            if (curRow < 0 || curCol < 0 || 
                curRow >= maze.length || curCol >= maze[curRow].length || 
                maze[curRow][curCol] == WALL_CHAR) {
                return false;
            }

            // Check if destination is reached
            if (maze[curRow][curCol] == END_CHAR) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast input reader for competitive programming / performance-critical contexts.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;

public class Main {

    // All 24 permutations of the four directions: L, R, U, D
    private static final char[][] PERMUTATIONS = {
        {'L', 'R', 'U', 'D'}, {'L', 'R', 'D', 'U'},
        {'L', 'U', 'R', 'D'}, {'L', 'U', 'D', 'R'},
        {'L', 'D', 'U', 'R'}, {'L', 'D', 'R', 'U'},
        {'R', 'L', 'U', 'D'}, {'R', 'L', 'D', 'U'},
        {'R', 'U', 'L', 'D'}, {'R', 'U', 'D', 'L'},
        {'R', 'D', 'U', 'L'}, {'R', 'D', 'L', 'U'},
        {'U', 'R', 'L', 'D'}, {'U', 'R', 'D', 'L'},
        {'U', 'L', 'R', 'D'}, {'U', 'L', 'D', 'R'},
        {'U', 'D', 'L', 'R'}, {'U', 'D', 'R', 'L'},
        {'D', 'R', 'U', 'L'}, {'D', 'R', 'L', 'U'},
        {'D', 'U', 'R', 'L'}, {'D', 'U', 'L', 'R'},
        {'D', 'L', 'U', 'R'}, {'D', 'L', 'R', 'U'}
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            // Parse grid and locate start ('S') and end ('E') positions
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    if (cell == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (cell == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            String moves = scanner.next();
            int successfulPaths = 0;

            // Test each direction permutation
            for (char[] perm : PERMUTATIONS) {
                if (canReach(grid, rows, cols, startRow, startCol, endRow, endCol, perm, moves)) {
                    successfulPaths++;
                }
            }

            System.out.println(successfulPaths);
        }
    }

    /**
     * Simulates movement on the grid based on a direction permutation and a sequence of moves.
     * Returns true if the destination 'E' is reached without hitting boundaries or obstacles.
     */
    private static boolean canReach(char[][] grid, int rows, int cols, int startR, int startC,
                                    int endR, int endC, char[] perm, String moves) {
        int r = startR;
        int c = startC;

        for (int i = 0; i < moves.length(); i++) {
            int dirIndex = moves.charAt(i) - '0';
            if (dirIndex < 0 || dirIndex >= 4) {
                return false; // Invalid move index encountered
            }

            char dir = perm[dirIndex];
            int dr = 0, dc = 0;

            // Determine direction vector
            switch (dir) {
                case 'L': dc = -1; break;
                case 'R': dc = 1;  break;
                case 'U': dr = -1; break;
                case 'D': dr = 1;  break;
                default:  return false;
            }

            r += dr;
            c += dc;

            // Check boundaries and obstacles
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#') {
                return false;
            }

            // Check if destination reached
            if (r == endR && c == endC) {
                return true;
            }
        }
        return false;
    }
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Solves a grid pathfinding problem by testing all permutations of directional mappings.
 * The input path string uses digits '0'-'3' to represent directions, which are mapped
 * to Up, Down, Left, Right according to each permutation.
 */
public class GridPathSolver {

    // Precomputed permutations of direction indices (0-3) representing all possible mappings
    private static final String[] DIRECTION_INDEX_PERMUTATIONS = {
        "0123", "0132", "0213", "0231", "0321", "0312",
        "1023", "1032", "1203", "1230", "1320", "1302",
        "2103", "2130", "2013", "2031", "2301", "2310",
        "3120", "3102", "3210", "3201", "3021", "3012"
    };

    private final FastInput scanner;
    private final PrintWriter outputWriter;

    private int numRows, numCols;
    private char[][] grid;
    private int startRow, startCol, endRow, endCol;
    private String pathSequence;

    public GridPathSolver() {
        this(System.in);
    }

    public GridPathSolver(InputStream inputStream) {
        this.scanner = new FastInput(inputStream);
        this.outputWriter = new PrintWriter(System.out);
    }

    /**
     * Entry point for execution. Orchestrates input reading, solving, and output.
     */
    public void run() {
        long startTime = System.currentTimeMillis();
        try {
            solve();
        } finally {
            outputWriter.flush();
        }
    }

    private void solve() {
        readInput();
        int validPathCount = countSuccessfulPaths();
        outputWriter.println(validPathCount);
    }

    private void readInput() {
        numRows = scanner.nextInt();
        numCols = scanner.nextInt();
        grid = new char[numRows][numCols];

        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                char cell = scanner.nextChar();
                grid[i][j] = cell;
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (cell == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }
        pathSequence = scanner.next();
    }

    private int countSuccessfulPaths() {
        int successCount = 0;
        for (String perm : DIRECTION_INDEX_PERMUTATIONS) {
            char[] directionMap = perm.toCharArray();
            if (canReachEnd(startRow, startCol, 0, directionMap)) {
                successCount++;
            }
        }
        return successCount;
    }

    /**
     * Recursively checks if the end position can be reached following the path sequence
     * under the current direction mapping.
     *
     * @param row           Current row position
     * @param col           Current column position
     * @param pathIndex     Current index in the path sequence
     * @param directionMap  Array mapping indices 0-3 to Up, Down, Left, Right characters
     * @return true if 'E' is reached, false otherwise
     */
    private boolean canReachEnd(int row, int col, int pathIndex, char[] directionMap) {
        if (!isWithinBounds(row, col) || grid[row][col] == '#') {
            return false;
        }
        if (grid[row][col] == 'E') {
            return true;
        }
        if (pathIndex >= pathSequence.length()) {
            return false;
        }

        char requiredDirection = pathSequence.charAt(pathIndex);
        switch (requiredDirection) {
            case directionMap[0]: // Up
                return canReachEnd(row - 1, col, pathIndex + 1, directionMap);
            case directionMap[1]: // Down
                return canReachEnd(row + 1, col, pathIndex + 1, directionMap);
            case directionMap[2]: // Left
                return canReachEnd(row, col - 1, pathIndex + 1, directionMap);
            case directionMap[3]: // Right
                return canReachEnd(row, col + 1, pathIndex + 1, directionMap);
            default:
                // Character in path sequence doesn't match any mapped direction
                return false;
        }
    }

    private boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < numRows && col >= 0 && col < numCols;
    }

    /**
     * Fast input reader optimized for competitive programming scenarios.
     * Encapsulated to keep business logic separate from I/O concerns.
     */
    private static class FastInput {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int bufferPointer = 0;
        private int bytesRead = 0;

        public FastInput(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                bytesRead = inputStream.read(buffer, 0, buffer.length);
                if (bytesRead <= 0) {
                    throw new InputMismatchException();
                }
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }

        private boolean isSpaceChar(int c) {
            return c <= 32;
        }

        private int skip() throws IOException {
            int c;
            while ((c = read()) != -1 && isSpaceChar(c));
            return c;
        }

        public String next() throws IOException {
            int c = skip();
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(c)) {
                sb.appendCodePoint(c);
                c = read();
            }
            return sb.toString();
        }

        public char nextChar() throws IOException {
            return (char) skip();
        }

        public int nextInt() throws IOException {
            int c = skip();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = read();
            }
            return result * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        new GridPathSolver().run();
    }
}

import java.util.Scanner;

/**
 * A solver for the maze navigation problem.
 * It determines how many valid mappings of command digits (0-3) to 
 * physical directions (Up, Down, Left, Right) allow the agent to reach the exit.
 */
public class MazeSolver {

    /**
     * Enum representing the four cardinal directions.
     * Defines the delta (dx, dy) for movement in the grid.
     */
    enum Direction {
        UP(0, -1),
        DOWN(0, 1),
        LEFT(-1, 0),
        RIGHT(1, 0);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    // Instance variables to hold the state of the maze
    private int rows;
    private int cols;
    private char[][] grid;
    private String commands;
    private int startX;
    private int startY;

    /**
     * Constructs the solver and reads the maze configuration from the input.
     *
     * @param scanner The scanner reading from System.in
     */
    public MazeSolver(Scanner scanner) {
        readInput(scanner);
    }

    /**
     * Reads the grid dimensions, the grid content, and the command string.
     */
    private void readInput(Scanner scanner) {
        if (!scanner.hasNextInt()) return;

        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        this.grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                String rowString = scanner.next();
                for (int j = 0; j < rowString.length(); j++) {
                    char cell = rowString.charAt(j);
                    grid[i][j] = cell;
                    if (cell == 'S') {
                        this.startX = j;
                        this.startY = i;
                    }
                }
            }
        }

        if (scanner.hasNext()) {
            this.commands = scanner.next();
        } else {
            this.commands = "";
        }
    }

    /**
     * Calculates the total number of valid direction mappings.
     *
     * @return The count of valid permutations.
     */
    public int solve() {
        // The available physical directions to map to the digits 0, 1, 2, 3
        Direction[] allDirections = {Direction.UP, Direction.DOWN, Direction.LEFT, Direction.RIGHT};

        // We need to find a permutation of directions for digits 0-3.
        // This is equivalent to checking all permutations of the allDirections array.
        return countValidMappings(allDirections, new boolean[4], new Direction[4], 0);
    }

    /**
     * Recursive helper to generate permutations of directions and check validity.
     *
     * @param options   The available directions to assign.
     * @param used      Boolean array tracking which directions are currently assigned.
     * @param mapping   The current partial mapping (index 0 is for digit '0', etc.).
     * @param index     The current digit (0-3) we are assigning a direction for.
     * @return          The number of valid complete mappings found.
     */
    private int countValidMappings(Direction[] options, boolean[] used, Direction[] mapping, int index) {
        // Base case: All digits 0-3 have been assigned a direction
        if (index == 4) {
            if (simulate(mapping)) {
                return 1;
            }
            return 0;
        }

        int validCount = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                // Assign direction to the current digit
                used[i] = true;
                mapping[index] = options[i];

                // Recurse for the next digit
                validCount += countValidMappings(options, used, mapping, index + 1);

                // Backtrack
                used[i] = false;
            }
        }
        return validCount;
    }

    /**
     * Simulates the movement based on a specific direction mapping.
     *
     * @param mapping An array where index 0-3 corresponds to the direction for command '0'-'3'.
     * @return true if the exit 'E' is reached, false otherwise.
     */
    private boolean simulate(Direction[] mapping) {
        int currX = startX;
        int currY = startY;

        // Iterate through each command in the sequence
        for (char commandChar : commands.toCharArray()) {
            int digit = commandChar - '0';

            // Safety check for invalid characters in command string
            if (digit < 0 || digit > 3) {
                continue; 
            }

            Direction dir = mapping[digit];
            currX += dir.dx;
            currY += dir.dy;

            // Check boundaries
            if (currX < 0 || currX >= cols || currY < 0 || currY >= rows) {
                return false;
            }

            // Check for walls
            if (grid[currY][currX] == '#') {
                return false;
            }

            // Check for exit
            if (grid[currY][currX] == 'E') {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        MazeSolver solver = new MazeSolver(scanner);
        System.out.println(solver.solve());
        scanner.close();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.NoSuchElementException;

/**
 * A solver for the Maze Path Counter problem.
 * This class reads a grid, a path string, and counts how many permutations
 * of direction mappings (0-3 to Up/Down/Left/Right) allow a valid path
 * from 'S' to 'E'.
 */
public class MazePathCounter {

    // Direction deltas: Up, Down, Left, Right
    private static final int[] DELTA_Y = {-1, 1, 0, 0};
    private static final int[] DELTA_X = {0, 0, -1, 1};

    // State variables
    private int rows, cols;
    private char[][] grid;
    private int startY, startX, endY, endX;
    private char[] pathMoves;

    // I/O resources
    private FastScanner scanner;
    private PrintWriter out;

    public static void main(String[] args) {
        MazePathCounter solver = new MazePathCounter();
        solver.solve();
    }

    /**
     * Orchestrates the solving process.
     */
    private void solve() {
        // Initialize I/O
        scanner = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        try {
            readInput();
            computeResult();
        } catch (Exception e) {
            // In a production environment, proper error handling/logging would go here.
            // For competitive programming, we can assume valid input format.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads the grid and path string from input.
     */
    private void readInput() {
        if (!scanner.hasNext()) return;

        rows = scanner.nextInt();
        cols = scanner.nextInt();

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startY = i;
                    startX = j;
                } else if (grid[i][j] == 'E') {
                    endY = i;
                    endX = j;
                }
            }
        }

        String moveString = scanner.next();
        pathMoves = moveString.toCharArray();
    }

    /**
     * Computes the number of valid direction permutations.
     */
    private void computeResult() {
        // directionMap maps a digit index (0-3) to a direction index (0-3).
        // We need to find all permutations of [0, 1, 2, 3] assigned to indices [0, 1, 2, 3].
        int[] directionMap = new int[4]; 
        boolean[] used = new boolean[4];

        int validCount = generatePermutations(directionMap, used, 0);
        out.println(validCount);
    }

    /**
     * Recursively generates all permutations of the direction map.
     * 
     * @param directionMap The array storing the current permutation.
     * @param used         Boolean array to track used directions.
     * @param index        Current digit index (0-3) we are assigning a direction to.
     * @return             Number of valid paths found with the generated maps.
     */
    private int generatePermutations(int[] directionMap, boolean[] used, int index) {
        // Base case: A full permutation is generated
        if (index == 4) {
            return simulatePath(directionMap) ? 1 : 0;
        }

        int count = 0;
        // Try assigning each unused direction to the current digit index
        for (int d = 0; d < 4; d++) {
            if (!used[d]) {
                used[d] = true;
                directionMap[index] = d;

                count += generatePermutations(directionMap, used, index + 1);

                used[d] = false; // Backtrack
            }
        }
        return count;
    }

    /**
     * Simulates the path based on the direction mapping.
     * Returns true if the path reaches the destination 'E'.
     * Converted from recursive DFS to iterative simulation for better stack safety.
     */
    private boolean simulatePath(int[] directionMap) {
        int y = startY;
        int x = startX;

        // Check if starting position is already the goal
        if (y == endY && x == endX) {
            return true;
        }

        for (char moveChar : pathMoves) {
            int digit = moveChar - '0';

            // Safety check for invalid characters in input string
            if (digit < 0 || digit > 3) {
                return false; 
            }

            int directionIndex = directionMap[digit];
            int nextY = y + DELTA_Y[directionIndex];
            int nextX = x + DELTA_X[directionIndex];

            // Check bounds
            if (nextY < 0 || nextY >= rows || nextX < 0 || nextX >= cols) {
                return false; // Path goes out of bounds
            }

            // Check wall
            if (grid[nextY][nextX] == '#') {
                return false; // Path hits a wall
            }

            // Move
            y = nextY;
            x = nextX;

            // Check if reached goal
            if (y == endY && x == endX) {
                return true;
            }
        }

        // If loop finishes and we haven't returned true, we didn't reach goal
        return false;
    }

    /**
     * FastScanner utility class for efficient input reading.
     */
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[2048];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int nextByte() {
            if (!hasNextByte()) {
                return -1;
            }
            return buffer[ptr++];
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrint(buffer[ptr])) {
                ptr++;
            }
            return hasNextByte();
        }

        private boolean isPrint(int ch) {
            return ch >= '!' && ch <= '~';
        }

        public String next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            StringBuilder sb = new StringBuilder();
            int b = -1;
            while (isPrint(b = nextByte())) {
                sb.appendCodePoint(b);
            }
            return sb.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class MainB {
    // Direction deltas: down, right, up, left
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                board[i] = row != null ? row.toCharArray() : new char[0];
            }

            String s = sc.next();
            if (s == null) s = "";

            // Pre-compute start position instead of scanning on every base case
            int startR = -1, startC = -1;
            outer:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (board[i].length > j && board[i][j] == 'S') {
                        startR = i;
                        startC = j;
                        break outer;
                    }
                }
            }

            // assignment[digit] stores the direction index (0-3) mapped to digit 0-3
            int[] assignment = new int[4];
            boolean[] used = new boolean[4];
            int[] validPaths = new int[1];

            backtrack(0, s, board, n, m, startR, startC, assignment, used, validPaths);

            out.println(validPaths[0]);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Generates all permutations of direction assignments for digits 0-3.
     */
    private static void backtrack(int digitIdx, String s, char[][] board, int n, int m,
                                  int startR, int startC, int[] assignment, boolean[] used, int[] validPaths) {
        if (digitIdx == 4) {
            simulatePath(s, board, n, m, startR, startC, assignment, validPaths);
            return;
        }

        for (int d = 0; d < 4; d++) {
            if (!used[d]) {
                used[d] = true;
                assignment[digitIdx] = d;
                backtrack(digitIdx + 1, s, board, n, m, startR, startC, assignment, used, validPaths);
                used[d] = false; // Backtrack
            }
        }
    }

    /**
     * Simulates the path based on the current direction assignment and counts valid routes to 'E'.
     */
    private static void simulatePath(String s, char[][] board, int n, int m,
                                     int startR, int startC, int[] assignment, int[] validPaths) {
        int r = startR;
        int c = startC;

        for (int i = 0; i < s.length(); i++) {
            int dirIdx = s.charAt(i) - '0';
            if (dirIdx < 0 || dirIdx > 3) return; // Safety check for invalid digits

            int d = assignment[dirIdx];
            r += DR[d];
            c += DC[d];

            // Check bounds and obstacles
            if (r < 0 || r >= n || c < 0 || c >= m || board[r][c] == '#') {
                return;
            }
            // Reached destination
            if (board[r][c] == 'E') {
                validPaths[0]++;
                return;
            }
        }
    }

    /**
     * Standard fast I/O utility replacing the verbose custom StdIn class.
     * Improves maintainability while preserving performance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputScanner in = new InputScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(1, in, out);

        out.close();
    }

    static class TaskB {
        // Direction constants for clarity
        private static final int UP = 0;
        private static final int DOWN = 1;
        private static final int LEFT = 2;
        private static final int RIGHT = 3;

        private int n, m;
        private String[] grid;
        private int startRow, startCol;
        private int[] permutation = {UP, DOWN, LEFT, RIGHT};

        public void solve(int testNumber, InputScanner in, PrintWriter out) {
            // Read grid dimensions
            int[] dimensions = in.readIntArr();
            n = dimensions[0];
            m = dimensions[1];

            // Read grid and locate starting position
            grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = in.readString();
                int sIndex = grid[i].indexOf('S');
                if (sIndex != -1) {
                    startRow = i;
                    startCol = sIndex;
                }
            }

            // Read movement path string
            String path = in.readString();

            int validPathsCount = 0;
            // Try all permutations of the movement sequence
            do {
                if (simulatePath(path)) {
                    validPathsCount++;
                }
            } while (nextPermutation(permutation));

            out.println(validPathsCount);
        }

        /**
         * Simulates the path according to the current permutation.
         * Returns true if the path successfully reaches 'E', false otherwise.
         */
        private boolean simulatePath(String path) {
            int row = startRow;
            int col = startCol;

            for (int i = 0; i < path.length(); i++) {
                int digit = path.charAt(i) - '0';
                int direction = getDirectionIndex(digit);

                // Apply movement based on direction index
                switch (direction) {
                    case UP:    row--; break;
                    case DOWN:  row++; break;
                    case LEFT:  col--; break;
                    case RIGHT: col++; break;
                }

                // Check boundary conditions
                if (row < 0 || row >= n || col < 0 || col >= m) {
                    return false;
                }

                char cell = grid[row].charAt(col);
                if (cell == '#') {
                    return false; // Hit obstacle
                }
                if (cell == 'E') {
                    return true; // Reached target
                }
            }
            return false; // Path ended without reaching target
        }

        /**
         * Finds the index of the given digit within the current permutation.
         * This maps the digit from the input string to a specific direction.
         */
        private int getDirectionIndex(int digit) {
            for (int i = 0; i < permutation.length; i++) {
                if (permutation[i] == digit) {
                    return i;
                }
            }
            return -1; // Should not occur with valid input
        }

        /**
         * Generates the next lexicographical permutation of the array.
         * Returns false if the array is already in descending order.
         */
        private boolean nextPermutation(int[] a) {
            int i = a.length - 1;
            while (i > 0 && a[i - 1] >= a[i]) {
                i--;
            }
            if (i <= 0) {
                return false;
            }

            int j = a.length - 1;
            while (a[j] <= a[i - 1]) {
                j--;
            }

            swap(a, i - 1, j);

            int left = i;
            int right = a.length - 1;
            while (left < right) {
                swap(a, left, right);
                left++;
                right--;
            }
            return true;
        }

        private void swap(int[] a, int i, int j) {
            int temp = a[i];
            a[i] = a[j];
            a[j] = temp;
        }
    }

    static class InputScanner {
        private final BufferedReader br;

        public InputScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }

        public String readString() {
            return readLine();
        }

        public String[] readStringArr() {
            String line = readLine();
            if (line == null) {
                return new String[0];
            }
            return line.split("\\s+");
        }

        public int[] readIntArr() {
            String[] parts = readStringArr();
            int[] arr = new int[parts.length];
            for (int i = 0; i < parts.length; i++) {
                arr[i] = Integer.parseInt(parts[i]);
            }
            return arr;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        // Initialize FastScanner and PrintWriter for efficient I/O
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Process test cases until end of input
        while (sc.hasNext()) {
            try {
                solve(sc, out);
            } catch (Exception e) {
                // In case of unexpected errors, stop processing
                break;
            }
        }
        // Ensure all output is written
        out.flush();
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        // Read dimensions N and M
        if (!sc.hasNext()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();

        // Grid initialization using 1-based indexing for convenience
        char[][] maze = new char[n + 1][m + 1];
        int startX = 0, startY = 0;
        int endX = 0, endY = 0;

        // Read the maze grid
        for (int i = 1; i <= n; i++) {
            String row = sc.next();
            for (int j = 1; j <= m; j++) {
                if (j <= row.length()) {
                    maze[i][j] = row.charAt(j - 1);
                } else {
                    // Fallback for malformed input, though unlikely in valid test cases
                    maze[i][j] = ' '; 
                }

                if (maze[i][j] == 'S') {
                    startX = i;
                    startY = j;
                } else if (maze[i][j] == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }

        // Read the path instruction string
        String pathString = sc.next();

        // Permutation array: maps input digit (1-4) to direction code (1-4).
        // Index 0 corresponds to digit '1', Index 3 to digit '4'.
        // Initial state: Digit 1 -> Dir 1, Digit 2 -> Dir 2, etc.
        int[] directionMap = {1, 2, 3, 4};

        int successfulPathsCount = 0;

        // Iterate through all permutations of directions
        // The do-while loop ensures we process the initial permutation [1, 2, 3, 4] as well
        do {
            int cx = startX;
            int cy = startY;
            boolean reachedEnd = false;

            // Simulate the path based on the current direction mapping
            for (int i = 0; i < pathString.length(); i++) {
                char c = pathString.charAt(i);

                // Ensure character is a valid digit '1'-'4'
                if (c < '1' || c > '4') continue;

                int digit = c - '0';
                // Get the direction code defined by the current permutation
                int directionCode = directionMap[digit - 1];

                // Determine movement delta based on direction code
                // 1: Up (-1, 0)
                // 2: Right (0, 1)
                // 3: Down (1, 0)
                // 4: Left (0, -1)
                int dr = 0;
                int dc = 0;

                if (directionCode == 1) dr = -1;
                else if (directionCode == 2) dc = 1;
                else if (directionCode == 3) dr = 1;
                else if (directionCode == 4) dc = -1;

                // Apply movement
                cx += dr;
                cy += dc;

                // Check boundaries
                if (cx < 1 || cx > n || cy < 1 || cy > m) {
                    break;
                }

                // Check walls
                if (maze[cx][cy] == '#') {
                    break;
                }

                // Check if destination reached
                if (cx == endX && cy == endY) {
                    reachedEnd = true;
                    break;
                }
            }

            if (reachedEnd) {
                successfulPathsCount++;
            }

        } while (PermutationGenerator.nextPermutation(directionMap));

        out.println(successfulPathsCount);
    }

    /**
     * Utility class to generate permutations of an integer array.
     * Implements the standard algorithm to find the next lexicographical permutation.
     */
    static class PermutationGenerator {

        /**
         * Transforms the array to the next lexicographical permutation.
         * @param num The array to permute.
         * @return true if the next permutation was generated, false if it was the last one.
         */
        public static boolean nextPermutation(int[] num) {
            if (num.length <= 1) return false;

            int i = num.length - 2;
            while (i >= 0 && num[i] >= num[i + 1]) i--;

            if (i < 0) return false;

            int j = num.length - 1;
            while (j > i && num[j] <= num[i]) j--;

            swap(num, i, j);
            reverse(num, i + 1, num.length - 1);
            return true;
        }

        private static void swap(int[] num, int i, int j) {
            int temp = num[i];
            num[i] = num[j];
            num[j] = temp;
        }

        private static void reverse(int[] num, int start, int end) {
            while (start < end) {
                swap(num, start, end);
                start++;
                end--;
            }
        }
    }

    /**
     * Fast I/O helper class to handle input reading efficiently.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        /**
         * Reads the next token from input.
         * @return The next token string, or null if end of stream.
         */
        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        /**
         * Checks if there is more input available.
         * @return true if there is a next token.
         */
        boolean hasNext() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Reads the next integer.
         * @return The next integer.
         */
        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A solver for a maze pathfinding problem.
 * It reads a grid, a starting position, and a sequence of moves.
 * It then determines how many permutations of direction mappings (0-3 -> u/d/l/r)
 * allow the path to reach the exit 'E' without hitting walls '#' or going out of bounds.
 */
public class MazeSolver {

    // Grid dimensions
    private int rows;
    private int cols;

    // The maze grid
    private char[][] grid;

    // Starting position coordinates
    private int startRow;
    private int startCol;

    // The sequence of moves to simulate
    private char[] moveSequence;

    // Mapping from move index (0-3) to direction character
    // e.g., directionMap[0] might be 'u', meaning move '0' is 'up'
    private char[] directionMap;

    // Counter for successful paths
    private int successCount;

    // Possible directions
    private static final char[] BASE_DIRECTIONS = {'u', 'd', 'l', 'r'};

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        MazeSolver solver = new MazeSolver(reader);
        solver.run();
    }

    public MazeSolver(BufferedReader reader) throws IOException {
        initialize(reader);
    }

    /**
     * Parses the input to populate the grid and move sequence.
     */
    private void initialize(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null) {
            return;
        }

        StringTokenizer st = new StringTokenizer(line);
        if (st.hasMoreTokens()) {
            this.rows = Integer.parseInt(st.nextToken());
        }
        if (st.hasMoreTokens()) {
            this.cols = Integer.parseInt(st.nextToken());
        }

        grid = new char[rows][cols];
        directionMap = new char[4]; // Indices 0, 1, 2, 3

        for (int i = 0; i < rows; i++) {
            String rowLine = reader.readLine();
            // Ensure we don't go out of bounds if line is short
            int length = (rowLine != null) ? rowLine.length() : 0;
            for (int j = 0; j < cols; j++) {
                if (j < length) {
                    grid[i][j] = rowLine.charAt(j);
                    if (grid[i][j] == 'S') {
                        this.startRow = i;
                        this.startCol = j;
                    }
                }
            }
        }

        String moveLine = reader.readLine();
        if (moveLine != null) {
            this.moveSequence = moveLine.toCharArray();
        } else {
            this.moveSequence = new char[0];
        }
    }

    /**
     * Executes the solving logic: generates permutations and checks paths.
     */
    public void run() {
        // Generate all permutations of the base directions
        // We pass a clone to avoid modifying the constant array
        permute(BASE_DIRECTIONS.clone(), 0);

        System.out.println(successCount);
    }

    /**
     * Recursively generates permutations of the character array.
     * This replaces the inefficient nested loops and HashSet logic from the original code.
     */
    private void permute(char[] arr, int start) {
        if (start == arr.length) {
            // A full permutation has been generated.
            // Assign it to the directionMap lookup table.
            System.arraycopy(arr, 0, directionMap, 0, arr.length);

            // Check if this mapping allows reaching the exit
            if (checkPath()) {
                successCount++;
            }
            return;
        }

        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            permute(arr, start + 1);
            swap(arr, start, i); // Backtrack to restore array state
        }
    }

    private void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the path based on the current directionMap.
     * Returns true if the exit 'E' is reached, false otherwise.
     */
    private boolean checkPath() {
        int currentRow = startRow;
        int currentCol = startCol;

        for (char moveChar : moveSequence) {
            // Convert char digit (e.g., '0') to integer index (0)
            // This is more efficient than Integer.parseInt(v[i]+"")
            int moveIndex = moveChar - '0';

            // Safety check: ensure moveIndex is within valid range [0, 3]
            if (moveIndex < 0 || moveIndex >= 4) {
                continue; 
            }

            // Get the direction associated with this move index
            char direction = directionMap[moveIndex];

            // Update coordinates based on direction
            switch (direction) {
                case 'u': currentRow--; break;
                case 'd': currentRow++; break;
                case 'l': currentCol--; break;
                case 'r': currentCol++; break;
                default: 
                    // Should not happen given the permutation logic
                    break; 
            }

            // Check if the new position is out of bounds
            if (currentRow < 0 || currentRow >= rows || currentCol < 0 || currentCol >= cols) {
                return false;
            }

            // Check if the new position is a wall
            if (grid[currentRow][currentCol] == '#') {
                return false;
            }

            // Check if the new position is the exit
            if (grid[currentRow][currentCol] == 'E') {
                return true;
            }
        }

        // If the loop finishes without reaching 'E', return false
        return false;
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.Writer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.List;

public class BuggyBot {

    private static final char START_CHAR = 'S';
    private static final char EXIT_CHAR = 'E';
    private static final char OBSTACLE_CHAR = '#';

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        int rows = in.readInt();
        int cols = in.readInt();

        char[][] grid = new char[rows][cols];
        int startX = 0, startY = 0, exitX = 0, exitY = 0;

        for (int i = 0; i < rows; i++) {
            String line = in.readString();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START_CHAR) {
                    startX = i;
                    startY = j;
                } else if (grid[i][j] == EXIT_CHAR) {
                    exitX = i;
                    exitY = j;
                }
            }
        }

        String moves = in.readString();

        // Directions corresponding to '0', '1', '2', '3'
        // Up, Right, Down, Left
        int[][] directions = {
            {-1, 0},
            {0, 1},
            {1, 0},
            {0, -1}
        };

        List<int[][]> permutations = new ArrayList<>();
        generatePermutations(directions, 0, directions.length - 1, permutations);

        int validCount = 0;
        for (int[][] perm : permutations) {
            if (canReach(grid, startX, startY, exitX, exitY, perm, moves)) {
                validCount++;
            }
        }

        out.printLine(validCount);
        out.flush();
    }

    /**
     * Generates all permutations of the given array using backtracking.
     * Creates deep copies at each leaf to prevent shared reference mutations.
     */
    private static void generatePermutations(int[][] arr, int left, int right, List<int[][]> result) {
        if (left == right) {
            // Deep copy to avoid the shallow-copy bug present in the original code
            int[][] copy = new int[arr.length][2];
            for (int i = 0; i < arr.length; i++) {
                copy[i] = Arrays.copyOf(arr[i], 2);
            }
            result.add(copy);
            return;
        }

        for (int i = left; i <= right; i++) {
            swap(arr, left, i);
            generatePermutations(arr, left + 1, right, result);
            swap(arr, left, i); // Backtrack to restore original state
        }
    }

    private static void swap(int[][] arr, int i, int j) {
        int[] temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Checks if a given sequence of moves reaches the exit without hitting obstacles or boundaries.
     */
    private static boolean canReach(char[][] grid, int startX, int startY,
                                    int exitX, int exitY, int[][] directions, String moves) {
        int x = startX;
        int y = startY;

        for (int i = 0; i < moves.length(); i++) {
            int moveIndex = moves.charAt(i) - '0';
            x += directions[moveIndex][0];
            y += directions[moveIndex][1];

            // Check boundaries
            if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) {
                return false;
            }

            // Check obstacles
            if (grid[x][y] == OBSTACLE_CHAR) {
                return false;
            }

            // Check if exit reached
            if (x == exitX && y == exitY) {
                return true;
            }
        }
        return false;
    }

    // -----------------------------------------------------------------------
    // Standard Competitive Programming I/O Utilities (kept for compatibility)
    // -----------------------------------------------------------------------

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() { return readString(); }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() { writer.close(); }
        public void flush() { writer.flush(); }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem where a sequence of movement commands
 * must be mapped to directional permutations to reach an endpoint.
 */
public class GridPathSolver {

    // Grid cell constants
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = '#';

    // Direction mappings: index 0=Down, 1=Up, 2=Left, 3=Right
    private static final int[] DIR_DELTA_I = {1, -1, 0, 0};
    private static final int[] DIR_DELTA_J = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic stream management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner sc = new FastScanner(br);
            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            int startI = -1, endI = -1, startJ = -1, endJ = -1;

            // Parse grid and locate start/end positions
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == START_CHAR) {
                        startI = i;
                        startJ = j;
                    } else if (grid[i][j] == END_CHAR) {
                        endI = i;
                        endJ = j;
                    }
                }
            }

            String path = sc.next();
            int[][] permutations = generatePermutations();
            int validPathCount = 0;

            // Test each permutation of direction mappings
            for (int[] dirMapping : permutations) {
                if (isValidPath(grid, n, m, startI, startJ, endI, endJ, path, dirMapping)) {
                    validPathCount++;
                }
            }

            out.println(validPathCount);
            out.flush();
        }
    }

    /**
     * Simulates movement along the grid using a specific direction mapping.
     * Returns true if the path successfully reaches the endpoint without 
     * hitting obstacles or going out of bounds.
     */
    private static boolean isValidPath(char[][] grid, int n, int m,
                                       int startI, int startJ,
                                       int endI, int endJ,
                                       String path, int[] dirMapping) {
        int ci = startI;
        int cj = startJ;

        for (int k = 0; k < path.length(); k++) {
            // Check current cell validity
            if (ci < 0 || ci >= n || cj < 0 || cj >= m || grid[ci][cj] == OBSTACLE_CHAR) {
                return false;
            }
            // Early exit if endpoint is reached
            if (grid[ci][cj] == END_CHAR) {
                return true;
            }

            // Apply mapped direction
            int commandIndex = path.charAt(k) - '0';
            int d = dirMapping[commandIndex];
            ci += DIR_DELTA_I[d];
            cj += DIR_DELTA_J[d];
        }

        // Validate final position after exhausting the path string
        return ci >= 0 && ci < n && cj >= 0 && cj < m &&
               grid[ci][cj] != OBSTACLE_CHAR &&
               grid[ci][cj] == END_CHAR;
    }

    /**
     * Generates all permutations of the base direction array {0, 1, 2, 3}.
     * This replaces the hardcoded 24-element array, improving maintainability.
     */
    private static int[][] generatePermutations() {
        int[] base = {0, 1, 2, 3};
        return permute(base, 0);
    }

    private static int[][] permute(int[] arr, int k) {
        if (k == arr.length) {
            return new int[][]{arr.clone()};
        }

        int[][] result = new int[0][];
        for (int i = k; i < arr.length; i++) {
            swap(arr, i, k);
            int[][] subPerms = permute(arr, k + 1);
            result = concatArrays(result, subPerms);
            swap(arr, i, k); // Backtrack
        }
        return result;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private static int[][] concatArrays(int[][] a, int[][] b) {
        int[][] res = new int[a.length + b.length][];
        System.arraycopy(a, 0, res, 0, a.length);
        System.arraycopy(b, 0, res, a.length, b.length);
        return res;
    }

    /**
     * Fast input reader for competitive programming / high-throughput scenarios.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A solver for a maze pathfinding problem.
 * It reads a grid, a start position, and a sequence of moves represented by digits.
 * It determines how many permutations of direction mappings (0-3 -> Up/Left/Right/Down)
 * allow the path to successfully reach the target 'E'.
 */
public class MazeSolver {

    // Grid dimensions
    private int rows;
    private int cols;

    // The grid representing the maze
    private char[][] grid;

    // Coordinates of the starting point 'S'
    private int startRow;
    private int startCol;

    // The sequence of moves (digits '0'-'3')
    private String moveSequence;

    // Direction offsets: Up, Left, Right, Down
    // Indices correspond to direction mapping: 0->Up, 1->Left, 2->Right, 3->Down
    private static final int[] DR = {-1, 0, 0, 1};
    private static final int[] DC = {0, -1, 1, 0};

    public static void main(String[] args) {
        MazeSolver solver = new MazeSolver();
        solver.runFromSystemIO();
    }

    /**
     * Entry point for reading from System.in and writing to System.out.
     */
    public void runFromSystemIO() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic to read input, process the maze, and output the result.
     */
    private void solve(FastScanner in, PrintWriter out) {
        // Read dimensions
        if (!in.hasMoreTokens()) return;

        rows = in.nextInt();
        cols = in.nextInt();

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Find start position 'S' and initialize traversal state
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                    // Treat start position as empty space for traversal purposes
                    grid[i][j] = '.';
                }
            }
        }

        // Read the move sequence string
        moveSequence = in.next();

        // Prepare for permutation generation
        // directionMap maps a digit (0-3) to a direction index (0-3)
        int[] directionMap = new int[4]; 
        // usedDirections tracks which direction indices have been assigned in the current permutation
        boolean[] usedDirections = new boolean[4];

        // Calculate and print the number of valid permutations
        int result = countValidPermutations(directionMap, usedDirections, 0);
        out.println(result);
    }

    /**
     * Recursively generates all permutations of direction mappings.
     * It attempts to map digits '0', '1', '2', '3' to the 4 directions.
     *
     * @param directionMap Array storing the current mapping (digit -> direction index)
     * @param usedDirections Boolean array tracking used direction indices
     * @param currentDigit The digit (0-3) currently being assigned a direction
     * @return The count of valid permutations that lead to the target 'E'
     */
    private int countValidPermutations(int[] directionMap, boolean[] usedDirections, int currentDigit) {
        // Base case: All digits 0-3 have been assigned a direction
        if (currentDigit == 4) {
            return simulatePath(directionMap);
        }

        int validCount = 0;

        // Try assigning each unused direction to the current digit
        for (int dirIdx = 0; dirIdx < 4; dirIdx++) {
            if (!usedDirections[dirIdx]) {
                // Assign direction
                usedDirections[dirIdx] = true;
                directionMap[currentDigit] = dirIdx;

                // Recurse to assign the next digit
                validCount += countValidPermutations(directionMap, usedDirections, currentDigit + 1);

                // Backtrack: unassign direction to try the next option
                usedDirections[dirIdx] = false;
            }
        }

        return validCount;
    }

    /**
     * Simulates the path traversal based on the provided direction mapping.
     *
     * @param directionMap The mapping of digits to directions
     * @return 1 if the target 'E' is reached, 0 otherwise
     */
    private int simulatePath(int[] directionMap) {
        int r = startRow;
        int c = startCol;

        // Iterate through each move in the sequence
        for (int i = 0; i < moveSequence.length(); i++) {
            char moveChar = moveSequence.charAt(i);
            int digit = moveChar - '0';

            // Safety check for valid digit range
            if (digit < 0 || digit > 3) {
                continue; 
            }

            int dir = directionMap[digit];
            r += DR[dir];
            c += DC[dir];

            // Check bounds
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return 0; // Path went out of bounds
            }

            // Check obstacle
            if (grid[r][c] == '#') {
                return 0; // Path hit a wall
            }

            // Check target
            if (grid[r][c] == 'E') {
                return 1; // Target reached
            }
        }

        return 0; // Path completed but did not reach 'E'
    }

    /**
     * Helper class for fast input reading.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /**
         * Checks if there are more tokens available in the input.
         */
        public boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                    return false;
                }
                if (line == null) {
                    return false;
                }
                st = new StringTokenizer(line);
            }
            return true;
        }

        /**
         * Reads the next token from the input.
         */
        public String next() {
            if (hasMoreTokens()) {
                return st.nextToken();
            }
            return null;
        }

        /**
         * Reads the next integer from the input.
         */
        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Solves a maze pathfinding problem by testing all permutations of direction mappings.
 * It reads a grid and an instruction string, then counts how many permutations 
 * of the directions {1, 2, 3, 4} allow a path from 'S' to 'E' without hitting walls.
 */
public class GridPathSolver {

    // Constants for grid states
    private static final int WALL = -1;
    private static final int EMPTY = 0;
    private static final int START = 1;
    private static final int END = 2;

    // State variables
    private static int[][] grid;
    private static int startRow, startCol;
    private static String instruction;
    private static int successCount = 0;
    private static int[] directionOrder; // Stores permutation of {1, 2, 3, 4}

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {

            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            grid = new int[rows][cols];
            startRow = -1;
            startCol = -1;

            // Parse the grid
            for (int i = 0; i < rows; i++) {
                if (scanner.hasNext()) {
                    String line = scanner.next();
                    // Ensure we don't go out of bounds if line is shorter than cols
                    int len = Math.min(line.length(), cols);
                    for (int j = 0; j < len; j++) {
                        char c = line.charAt(j);
                        if (c == '#') {
                            grid[i][j] = WALL;
                        } else if (c == 'S') {
                            grid[i][j] = START;
                            startRow = i;
                            startCol = j;
                        } else if (c == 'E') {
                            grid[i][j] = END;
                        } else {
                            grid[i][j] = EMPTY;
                        }
                    }
                }
            }

            // Read the instruction string
            if (scanner.hasNext()) {
                instruction = scanner.next();
            }

            // Initialize direction mapping: 1=Up, 2=Right, 3=Down, 4=Left
            // We will permute these values to find valid paths.
            directionOrder = new int[]{1, 2, 3, 4};

            // Generate all permutations and count valid paths
            permute(directionOrder, 0);

            // Output the result
            System.out.println(successCount);

        } catch (Exception e) {
            // In a production environment, proper logging should be used.
            // For this script, we simply ignore or print stack trace if needed.
        }
    }

    /**
     * Recursively generates permutations of the direction array.
     * @param arr The array to permute
     * @param index The current index being fixed in the permutation
     */
    private static void permute(int[] arr, int index) {
        // Base case: If we have reached the end of the array, simulate the path
        if (index == arr.length) {
            simulatePath(arr);
            return;
        }

        for (int i = index; i < arr.length; i++) {
            // Swap elements
            swap(arr, index, i);

            // Recurse for the next index
            permute(arr, index + 1);

            // Backtrack (swap back to restore original state)
            swap(arr, index, i);
        }
    }

    /**
     * Swaps two elements in an array.
     */
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the path based on the current direction permutation.
     * @param currentDirectionOrder The current permutation of directions to test.
     */
    private static void simulatePath(int[] currentDirectionOrder) {
        int currentR = startRow;
        int currentC = startCol;
        boolean reachedEnd = false;

        for (int i = 0; i < instruction.length(); i++) {
            // Check if current position is valid and not a wall
            if (!isInside(currentR, currentC) || grid[currentR][currentC] == WALL) {
                break;
            }

            // Check if we have reached the destination
            if (grid[currentR][currentC] == END) {
                successCount++;
                reachedEnd = true;
                break;
            }

            // Determine direction from instruction
            char moveChar = instruction.charAt(i);
            int index = Character.getNumericValue(moveChar);

            // Safety check for index bounds
            // Original code used Character.getNumericValue(c) which is 1-based for digits '1'-'9'.
            // Array indices are 0-based. If input is '4', index is 4, which is out of bounds for size 4.
            // We check to prevent crash.
            if (index < 0 || index >= currentDirectionOrder.length) {
                // Invalid move index, stop path
                break;
            }

            int direction = currentDirectionOrder[index];

            // Apply movement based on direction value
            // 1: Up, 2: Right, 3: Down, 4: Left
            switch (direction) {
                case 1: currentR--; break;
                case 2: currentC++; break;
                case 3: currentR++; break;
                case 4: currentC--; break;
                default: break; 
            }
        }

        // Check if the path ended exactly on the destination
        // (Handles the case where the last move lands on 'E' after the loop finishes)
        if (!reachedEnd) {
            if (isInside(currentR, currentC) && grid[currentR][currentC] == END) {
                successCount++;
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isInside(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.util.Scanner;

public class GridSolver {

    // Direction definitions: Right, Left, Up, Down
    // Indices: 0 -> Right, 1 -> Left, 2 -> Up, 3 -> Down
    // Changes in row (dr) and column (dc)
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {1, -1, 0, 0};

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the integers

            char[][] grid = new char[n][m];
            int startRow = 0;
            int startCol = 0;

            // Read the grid and find the starting position 'S'
            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                    for (int j = 0; j < grid[i].length; j++) {
                        if (grid[i][j] == 'S') {
                            startRow = i;
                            startCol = j;
                        }
                    }
                }
            }

            // Read the direction string
            String directionInput = scanner.hasNextLine() ? scanner.nextLine() : "";
            char[] path = directionInput.toCharArray();

            // Array to represent the permutation of digits {0, 1, 2, 3}
            // perm[k] stores the digit that corresponds to direction index k
            // k=0 (Right), k=1 (Left), k=2 (Up), k=3 (Down)
            int[] perm = {0, 1, 2, 3};

            // Count valid permutations
            int validCount = countValidPermutations(perm, 0, grid, path, startRow, startCol);

            System.out.println(validCount);
        }
    }

    /**
     * Recursively generates all permutations of the digit array and counts valid paths.
     */
    private static int countValidPermutations(int[] perm, int k, char[][] grid, char[] path, int startRow, int startCol) {
        if (k == perm.length) {
            // Base case: A complete permutation is formed. Check if the path is valid.
            return isPathValid(grid, path, startRow, startCol, perm) ? 1 : 0;
        }

        int count = 0;
        for (int i = k; i < perm.length; i++) {
            // Swap elements to generate permutations
            swap(perm, k, i);

            // Recurse
            count += countValidPermutations(perm, k + 1, grid, path, startRow, startCol);

            // Backtrack
            swap(perm, k, i);
        }
        return count;
    }

    /**
     * Checks if a path is valid given a specific digit-to-direction mapping.
     */
    private static boolean isPathValid(char[][] grid, char[] path, int startRow, int startCol, int[] perm) {
        // Build a lookup table: digit -> directionIndex
        // perm[0] is the digit for Right (index 0)
        // perm[1] is the digit for Left (index 1)
        // perm[2] is the digit for Up (index 2)
        // perm[3] is the digit for Down (index 3)
        int[] digitToDirIndex = new int[4];
        digitToDirIndex[perm[0]] = 0;
        digitToDirIndex[perm[1]] = 1;
        digitToDirIndex[perm[2]] = 2;
        digitToDirIndex[perm[3]] = 3;

        int r = startRow;
        int c = startCol;

        for (char moveChar : path) {
            int digit = moveChar - '0';

            // Safety check for invalid digits in input
            if (digit < 0 || digit > 3) {
                return false; 
            }

            int dirIndex = digitToDirIndex[digit];

            // Move
            r += DR[dirIndex];
            c += DC[dirIndex];

            // Check boundaries
            if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
                return false;
            }

            // Check for wall
            if (grid[r][c] == '#') {
                return false;
            }

            // Check for exit
            if (grid[r][c] == 'E') {
                return true;
            }
        }

        // If path ends without reaching 'E'
        return false;
    }

    /**
     * Swaps two elements in an integer array.
     */
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid path simulation.
 * Improvements:
 * - Removed unused methods (LOG2, power, gcd) and fields (mod)
 * - Extracted magic numbers/characters to named constants
 * - Replaced deeply nested condition with cleaner loop continuation
 * - Extracted simulation logic into a dedicated method for readability
 * - Removed unused 'end' position tracking
 * - Improved naming, indentation, and added JavaDoc comments
 */
public class GridPathSimulation {

    // Direction vectors: Up, Left, Down, Right
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    private static final char WALL = '*';
    private static final char OBSTACLE = '#';
    private static final char START = 'S';
    private static final char END = 'E';

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = 1;
        new Task().solve(testCases, in, out);

        out.flush();
        out.close();
    }

    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // Create grid with padded boundaries to simplify boundary checks
            char[][] grid = new char[n + 2][m + 2];
            for (int i = 0; i < m + 2; i++) {
                grid[0][i] = WALL;
                grid[n + 1][i] = WALL;
            }
            for (int i = 0; i < n + 2; i++) {
                grid[i][0] = WALL;
                grid[i][m + 1] = WALL;
            }

            Position start = new Position(0, 0);
            for (int i = 1; i <= n; i++) {
                String row = in.next();
                for (int j = 1; j <= m; j++) {
                    char c = row.charAt(j - 1);
                    grid[i][j] = c;
                    if (c == START) {
                        start = new Position(i, j);
                    }
                }
            }

            String directionSequence = in.next();
            char[] moves = directionSequence.toCharArray();

            int validPaths = 0;

            // Iterate over all permutations of 4 directions (0-3)
            // Each permutation maps input digits (0-3) to actual movement directions
            for (int d1 = 0; d1 < 4; d1++) {
                for (int d2 = 0; d2 < 4; d2++) {
                    if (d2 == d1) continue;
                    for (int d3 = 0; d3 < 4; d3++) {
                        if (d3 == d1 || d3 == d2) continue;
                        for (int d4 = 0; d4 < 4; d4++) {
                            if (d4 == d1 || d4 == d2 || d4 == d3) continue;

                            int[] perm = {d1, d2, d3, d4};
                            if (simulatePath(grid, start, moves, perm)) {
                                validPaths++;
                            }
                        }
                    }
                }
            }

            out.println(validPaths);
        }

        /**
         * Simulates movement from start position according to the direction sequence
         * and a specific direction permutation.
         * Returns true if the path reaches the END cell without hitting a wall or obstacle.
         */
        private boolean simulatePath(char[][] grid, Position start, char[] moves, int[] perm) {
            Position current = new Position(start.x, start.y);
            for (char moveChar : moves) {
                int dirIndex = moveChar - '0';
                if (dirIndex < 0 || dirIndex > 3) {
                    continue; // Skip invalid direction indices
                }

                int direction = perm[dirIndex];
                current.move(DX[direction], DY[direction]);

                char cell = grid[current.x][current.y];
                if (cell == WALL || cell == OBSTACLE) {
                    return false; // Path blocked
                }
                if (cell == END) {
                    return true; // Reached destination
                }
            }
            return false;
        }
    }

    static class Position {
        int x, y;
        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
        void move(int dx, int dy) {
            this.x += dx;
            this.y += dy;
        }
    }

    // Standard competitive programming InputReader
    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar, snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int a[] = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String next() {
            return readString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Simulates pathfinding on a grid for all permutations of directional sequences.
 * Reads a grid, identifies start/end points, and counts how many of the 24 possible
 * direction orderings successfully reach the destination.
 */
public class GridPathSimulator {

    // Grid cell constants
    private static final int WALL = -1;
    private static final int START = 1;
    private static final int END = 2;

    // Direction deltas: indices 0-3 map to LEFT, UP, RIGHT, DOWN respectively.
    // Matches original logic: ci={0,-1,0,1}, cj={-1,0,1,0}
    private static final int[] DELTA_ROW = {0, -1, 0, 1};
    private static final int[] DELTA_COL = {-1, 0, 1, 0};

    public static void main(String[] args) {
        // Use try-with-resources to ensure PrintWriter is properly flushed and closed
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastScanner sc = new FastScanner(System.in);

            int rows = sc.nextInt();
            int cols = sc.nextInt();

            int[][] grid = new int[rows][cols];
            int startRow = 0;
            int startCol = 0;

            // Parse grid and locate start position
            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    char ch = line.charAt(j);
                    if (ch == '#') {
                        grid[i][j] = WALL;
                    } else if (ch == 'S') {
                        grid[i][j] = START;
                        startRow = i;
                        startCol = j;
                    } else if (ch == 'E') {
                        grid[i][j] = END;
                    }
                }
            }

            // Parse direction sequence string into integer codes
            String directionSequence = sc.next();
            int[] dirCodes = new int[directionSequence.length()];
            for (int i = 0; i < directionSequence.length(); i++) {
                dirCodes[i] = directionSequence.charAt(i) - '0';
            }

            // Track successful path permutations
            int[] successCount = new int[1];
            int[] currentPerm = new int[4];
            boolean[] used = new boolean[4];

            // Generate all 24 permutations and simulate each
            generatePermutations(currentPerm, used, 0, dirCodes, grid, rows, cols, startRow, startCol, successCount);

            out.println(successCount[0]);
        }
    }

    /**
     * Recursively generates all permutations of direction indices [0, 1, 2, 3].
     * For each valid permutation, simulates the path and increments the counter if successful.
     */
    private static void generatePermutations(int[] current, boolean[] used, int depth, int[] dirSequence,
                                             int[][] grid, int rows, int cols, int startRow, int startCol, int[] count) {
        if (depth == 4) {
            if (simulatePath(current, dirSequence, grid, rows, cols, startRow, startCol)) {
                count[0]++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current[depth] = i;
                generatePermutations(current, used, depth + 1, dirSequence, grid, rows, cols, startRow, startCol, count);
                used[i] = false; // Backtrack
            }
        }
    }

    /**
     * Simulates movement along a given direction sequence.
     * Returns true if the destination 'E' is reached, false otherwise.
     */
    private static boolean simulatePath(int[] perm, int[] dirSequence, int[][] grid, int rows, int cols,
                                        int startRow, int startCol) {
        int r = startRow;
        int c = startCol;

        for (int dirCode : dirSequence) {
            int nextR = r + DELTA_ROW[dirCode];
            int nextC = c + DELTA_COL[dirCode];

            // Check grid boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                return false;
            }

            // Check for walls
            if (grid[nextR][nextC] == WALL) {
                return false;
            }

            // Move to next cell
            r = nextR;
            c = nextC;

            // Check if destination reached
            if (grid[r][c] == END) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast input reader for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new RuntimeException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after m

        char[][] grid = new char[n][];
        int startRow = -1;
        int startCol = -1;

        // Read grid and find Start position
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < line.length(); j++) {
                if (line.charAt(j) == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Read command string
        String commands = scanner.next();
        scanner.close();

        // Logic to count valid mappings
        // We need to assign digits 0, 1, 2, 3 to directions Left, Right, Up, Down.
        // This is equivalent to generating all permutations of [0, 1, 2, 3].
        int[] digits = {0, 1, 2, 3};
        int validMappingsCount = countValidPermutations(grid, startRow, startCol, commands, digits, 0);

        System.out.println(validMappingsCount);
    }

    /**
     * Recursively generates permutations of the digits array and counts how many
     * result in a successful path (reaching 'E').
     * 
     * @param grid The game grid
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param commands The command string
     * @param digits Array of digits [0, 1, 2, 3] to permute
     * @param index Current index in the permutation process
     * @return Number of valid mappings found
     */
    private static int countValidPermutations(char[][] grid, int startRow, int startCol, 
                                              String commands, int[] digits, int index) {
        if (index == digits.length) {
            // digits array is fully permuted.
            // We interpret the permutation as a mapping of digits to directions:
            // digits[0] -> Left
            // digits[1] -> Right
            // digits[2] -> Up
            // digits[3] -> Down
            // (Note: The order of assignment to directions corresponds to the 
            // original code's variables l, r, u, d).

            if (simulatePath(grid, startRow, startCol, commands, 
                             digits[0], digits[1], digits[2], digits[3])) {
                return 1;
            }
            return 0;
        }

        int count = 0;
        for (int i = index; i < digits.length; i++) {
            swap(digits, index, i);
            count += countValidPermutations(grid, startRow, startCol, commands, digits, index + 1);
            swap(digits, index, i); // Backtrack
        }
        return count;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the path based on the digit-to-direction mapping.
     * 
     * @param grid The game grid
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param commands The command string
     * @param leftVal The digit that triggers a Left move
     * @param rightVal The digit that triggers a Right move
     * @param upVal The digit that triggers an Up move
     * @param downVal The digit that triggers a Down move
     * @return true if 'E' is reached, false otherwise
     */
    private static boolean simulatePath(char[][] grid, int startRow, int startCol, 
                                        String commands, int leftVal, int rightVal, 
                                        int upVal, int downVal) {
        int r = startRow;
        int c = startCol;
        int rows = grid.length;
        int cols = (rows > 0) ? grid[0].length : 0;

        // Validate starting position
        if (r < 0 || r >= rows || c < 0 || c >= cols) return false;

        // Check starting cell
        if (grid[r][c] == 'E') return true;
        if (grid[r][c] == '#') return false;

        for (char cmd : commands.toCharArray()) {
            int digit = cmd - '0';
            int nextR = r;
            int nextC = c;

            // Determine move based on digit value
            if (digit == leftVal) {
                nextC--; // Left
            } else if (digit == rightVal) {
                nextC++; // Right
            } else if (digit == upVal) {
                nextR--; // Up
            } else if (digit == downVal) {
                nextR++; // Down
            }
            // Note: Since leftVal, rightVal, upVal, downVal are a permutation of 0-3,
            // and digit is 0-3, one of these conditions will always be true.

            // Check boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                return false;
            }

            r = nextR;
            c = nextC;

            // Check current cell after move
            if (grid[r][c] == 'E') return true;
            if (grid[r][c] == '#') return false;
        }

        // If commands exhausted, check if we are on 'E'?
        // The loop checks 'E' immediately after move.
        // If we landed on 'E' in the last step, it returned true.
        // So if we are here, we are not on 'E'.
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid pathfinding problem by testing all permutations of directional mappings.
 * Refactored for improved maintainability, performance, and code clarity.
 */
public class GridPathSolver {

    private static final char[] DIRECTIONS = {'u', 'd', 'l', 'r'};
    private static final int DIR_COUNT = DIRECTIONS.length;

    public static void main(String[] args) {
        // Standard competitive programming I/O setup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastReader in = new FastReader(reader);
            new GridPathSolver().solve(in, out);
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }

    /**
     * Orchestrates reading input, generating permutations, and counting successful paths.
     */
    public void solve(FastReader in, PrintWriter out) throws IOException {
        String nStr = in.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        int startRow = -1;
        int startCol = -1;

        // Read grid and locate the starting position
        for (int i = 0; i < n; i++) {
            String line = in.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Read the sequence of instructions (digits 0-3)
        String instructionSequence = in.next();

        // Pre-generate all unique permutations of the 4 directions
        List<char[]> directionPermutations = generateDirectionPermutations();
        int successCount = 0;

        // Simulate path for each permutation and count successes
        for (char[] permutation : directionPermutations) {
            if (simulatePath(instructionSequence, grid, permutation, startRow, startCol)) {
                successCount++;
            }
        }

        out.println(successCount);
    }

    /**
     * Generates all permutations of the 4 directions using backtracking.
     * Pre-allocates capacity since 4! = 24 permutations.
     */
    private List<char[]> generateDirectionPermutations() {
        List<char[]> permutations = new ArrayList<>(24);
        boolean[] used = new boolean[DIR_COUNT];
        char[] current = new char[DIR_COUNT];
        backtrackPermutations(permutations, current, used, 0);
        return permutations;
    }

    private void backtrackPermutations(List<char[]> permutations, char[] current, boolean[] used, int index) {
        if (index == DIR_COUNT) {
            permutations.add(current.clone());
            return;
        }
        for (int i = 0; i < DIR_COUNT; i++) {
            if (!used[i]) {
                used[i] = true;
                current[index] = DIRECTIONS[i];
                backtrackPermutations(permutations, current, used, index + 1);
                used[i] = false;
            }
        }
    }

    /**
     * Initiates recursive path simulation from the starting coordinates.
     */
    private boolean simulatePath(String instructionSequence, char[][] grid, char[] directionMapping, int row, int col) {
        return simulatePathRecursive(instructionSequence, grid, directionMapping, 0, row, col);
    }

    /**
     * Recursively simulates movement based on instruction sequence and direction mapping.
     * Optimized to avoid object allocation by computing coordinates inline.
     */
    private boolean simulatePathRecursive(String instructionSequence, char[][] grid, char[] directionMapping, 
                                          int step, int row, int col) {
        // Boundary and obstacle checks
        if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] == '#') {
            return false;
        }
        // Success condition: reached exit
        if (grid[row][col] == 'E') {
            return true;
        }
        // No more instructions to process
        if (step >= instructionSequence.length()) {
            return false;
        }

        // Map instruction digit to direction character
        int dirIndex = instructionSequence.charAt(step) - '0';
        char direction = directionMapping[dirIndex];

        // Compute next position without allocating int[] arrays
        int nextRow = row;
        int nextCol = col;
        switch (direction) {
            case 'u': nextRow++; break;
            case 'd': nextRow--; break;
            case 'l': nextCol--; break;
            case 'r': nextCol++; break;
            default: break;
        }

        return simulatePathRecursive(instructionSequence, grid, directionMapping, step + 1, nextRow, nextCol);
    }

    /**
     * High-performance input reader for competitive programming scenarios.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.*;

public class BuggyBot {
    // Constants for grid characters and direction offsets
    private static final char START = 'S';
    private static final char END = 'E';
    private static final char BLOCK = '#';

    // Direction vectors: Down, Right, Up, Left
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /**
     * Encapsulates the parsed grid and the starting coordinates.
     * Replaces scattered static state with clean, immutable data.
     */
    private static class GridInfo {
        final char[][] grid;
        final int startX;
        final int startY;

        GridInfo(char[][] grid, int startX, int startY) {
            this.grid = grid;
            this.startX = startX;
            this.startY = startY;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int m = sc.nextInt();
        String moves = sc.next();

        // Parse grid with automatic boundary padding and start position detection
        GridInfo gridInfo = parseGrid(n, m, sc);

        // Generate all 24 possible direction mappings
        List<int[]> directionMappings = generateDirectionMappings();

        int validCount = 0;
        for (int[] mapping : directionMappings) {
            if (isValid(gridInfo.startX, gridInfo.startY, moves, mapping, gridInfo.grid)) {
                validCount++;
            }
        }

        System.out.println(validCount);
    }

    /**
     * Reads the grid from input, pads it with BLOCK characters on all sides,
     * and locates the starting position.
     */
    private static GridInfo parseGrid(int n, int m, Scanner sc) {
        // Allocate grid with 1-cell padding on all sides
        char[][] grid = new char[n + 2][m + 2];
        for (int i = 0; i < grid.length; i++) {
            Arrays.fill(grid[i], BLOCK);
        }

        int startX = -1, startY = -1;
        for (int i = 1; i <= n; i++) {
            String line = sc.next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = line.charAt(j - 1);
                if (grid[i][j] == START) {
                    startX = i;
                    startY = j;
                }
            }
        }
        return new GridInfo(grid, startX, startY);
    }

    /**
     * Validates if a sequence of moves reaches the END position 
     * given a specific direction mapping.
     */
    private static boolean isValid(int startX, int startY, String moves, int[] mapping, char[][] grid) {
        int x = startX;
        int y = startY;

        for (int i = 0; i < moves.length(); i++) {
            char moveChar = moves.charAt(i);
            // Map the move character ('0'-'3') to a direction index (0-3)
            int direction = mapping[moveChar - '0'];

            x += DX[direction];
            y += DY[direction];

            if (grid[x][y] == BLOCK) {
                return false; // Hit a wall
            }
            if (grid[x][y] == END) {
                return true; // Reached destination
            }
        }
        return false; // Path exhausted without reaching END
    }

    /**
     * Generates all permutations of direction mappings {0, 1, 2, 3}.
     * Each permutation represents a unique assignment of '0','1','2','3' 
     * to the four cardinal directions.
     */
    private static List<int[]> generateDirectionMappings() {
        List<int[]> mappings = new ArrayList<>();
        int[] current = {0, 1, 2, 3};
        permute(mappings, current, 0);
        return mappings;
    }

    private static void permute(List<int[]> result, int[] arr, int start) {
        if (start == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            permute(result, arr, start + 1);
            swap(arr, start, i); // Backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    // Direction deltas: 0->Right, 1->Up, 2->Left, 3->Down
    // Matches original mapping: 0:y++, 1:x--, 2:y--, 3:x++
    private static final int[] DR = {0, -1, 0, 1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) {
        MyReader reader = new MyReader(System.in);
        MyWriter writer = new MyWriter(System.out);

        try {
            run(reader, writer);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try {
                writer.close();
            } catch (IOException ignored) {
                // Ignore close errors
            }
        }
    }

    /**
     * Orchestrates reading input, processing the grid, and writing the result.
     */
    private static void run(MyReader reader, MyWriter writer) throws IOException {
        int n = reader.nextInt();
        int m = reader.nextInt();
        char[][] grid = reader.nextCharMatrix(n);

        // Locate starting position
        int startRow = 0, startCol = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String path = reader.nextString();
        if (path == null) {
            writer.print(0);
            return;
        }

        int[] directions = {0, 1, 2, 3};
        int[] successCount = {0};

        // Generate all permutations and simulate each path
        generatePermutations(directions, 0, path, grid, n, m, startRow, startCol, successCount);
        writer.print(successCount[0]);
    }

    /**
     * Recursively generates all permutations of the direction array.
     */
    private static void generatePermutations(int[] arr, int l, String path, char[][] grid, 
                                             int n, int m, int startRow, int startCol, int[] count) {
        if (l == arr.length) {
            if (simulatePath(arr, path, grid, n, m, startRow, startCol)) {
                count[0]++;
            }
            return;
        }

        for (int i = l; i < arr.length; i++) {
            swap(arr, l, i);
            generatePermutations(arr, l + 1, path, grid, n, m, startRow, startCol, count);
            swap(arr, l, i); // Backtrack
        }
    }

    /**
     * Simulates movement along the path using the given direction permutation.
     * Returns true if 'E' is reached, false otherwise.
     */
    private static boolean simulatePath(int[] perm, String path, char[][] grid, 
                                        int n, int m, int startRow, int startCol) {
        int r = startRow;
        int c = startCol;

        for (int k = 0; k < path.length(); k++) {
            int dir = perm[path.charAt(k) - '0'];
            r += DR[dir];
            c += DC[dir];

            // Explicit bounds checking instead of catching exceptions
            if (r < 0 || r >= n || c < 0 || c >= m) {
                return false;
            }
            if (grid[r][c] == '#') {
                return false; // Hit obstacle
            }
            if (grid[r][c] == 'E') {
                return true; // Reached exit
            }
        }
        return false;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Fast input reader using a custom buffer.
     */
    static class MyReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int bufferPointer = 0;
        private int bytesRead = 0;

        public MyReader(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                bytesRead = in.read(buffer, 0, buffer.length);
                if (bytesRead == -1) {
                    bufferPointer = 0;
                    return -1;
                }
            }
            return buffer[bufferPointer++];
        }

        public int nextInt() throws IOException {
            return (int) nextLong();
        }

        public long nextLong() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) throw new EOFException();
                c = read();
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = read();
            }
            long result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = read();
            }
            return negative ? -result : result;
        }

        public String nextString() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return null;
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        public char[][] nextCharMatrix(int n) throws IOException {
            char[][] matrix = new char[n][];
            for (int i = 0; i < n; i++) {
                String line = nextString();
                if (line == null) throw new EOFException();
                matrix[i] = line.toCharArray();
            }
            return matrix;
        }
    }

    /**
     * Fast output writer using a custom buffer.
     */
    static class MyWriter {
        private final OutputStream out;
        private final byte[] buffer = new byte[1 << 16];
        private int bufferPointer = 0;

        public MyWriter(OutputStream out) {
            this.out = out;
        }

        private void writeByte(byte b) throws IOException {
            if (bufferPointer == buffer.length) {
                flush();
            }
            buffer[bufferPointer++] = b;
        }

        public void print(long x) throws IOException {
            if (x < 0) {
                writeByte('-');
                x = -x;
            }
            if (x == 0) {
                writeByte('0');
                return;
            }
            byte[] digits = new byte[20];
            int i = 0;
            while (x > 0) {
                digits[i++] = (byte) (x % 10 + '0');
                x /= 10;
            }
            for (int j = i - 1; j >= 0; j--) {
                writeByte(digits[j]);
            }
        }

        public void print(String s) throws IOException {
            for (int i = 0; i < s.length(); i++) {
                writeByte((byte) s.charAt(i));
            }
        }

        public void print(char c) throws IOException {
            writeByte((byte) c);
        }

        public void flush() throws IOException {
            out.write(buffer, 0, bufferPointer);
            out.flush();
            bufferPointer = 0;
        }

        public void close() throws IOException {
            flush();
            out.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridSolver solver = new GridSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the grid navigation problem.
     * Finds the number of valid permutations of direction mappings (0-3)
     * that allow reaching 'E' from 'S' using the given command sequence.
     */
    static class GridSolver {
        // Direction deltas: Up, Down, Left, Right
        // Index 0: Up (-1, 0)
        // Index 1: Down (1, 0)
        // Index 2: Left (0, -1)
        // Index 3: Right (0, 1)
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        private int height;
        private int width;
        private char[][] grid;
        private int startRow;
        private int startCol;
        private String commands;

        public void solve(FastScanner in, PrintWriter out) {
            // Read dimensions
            if (!in.hasNext()) return;
            height = in.nextInt();
            width = in.nextInt();

            // Read grid and find start position
            grid = new char[height][width];
            startRow = -1;
            startCol = -1;

            for (int r = 0; r < height; r++) {
                String rowStr = in.next();
                grid[r] = rowStr.toCharArray();
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] == 'S') {
                        startRow = r;
                        startCol = c;
                    }
                }
            }

            // Read commands
            commands = in.next();

            // Solve: Count valid permutations of direction mappings
            // directionMapping[digit] = directionIndex
            int[] directionMapping = new int[4];
            boolean[] usedDirections = new boolean[4];

            int validPermutations = countValidPermutations(0, usedDirections, directionMapping);

            out.println(validPermutations);
        }

        /**
         * Recursively generates all permutations of direction assignments for digits 0-3.
         *
         * @param digitIndex      The current digit (0-3) being assigned a direction.
         * @param usedDirections  Tracks which direction indices (0-3) are already assigned.
         * @param directionMapping Stores the mapping: directionMapping[digit] = directionIndex.
         * @return The number of valid permutations found.
         */
        private int countValidPermutations(int digitIndex, boolean[] usedDirections, int[] directionMapping) {
            // Base case: All digits 0-3 have been assigned a direction
            if (digitIndex == 4) {
                return isValidPath(directionMapping) ? 1 : 0;
            }

            int count = 0;
            // Iterate through all possible directions (0-3)
            for (int dirIndex = 0; dirIndex < 4; dirIndex++) {
                if (!usedDirections[dirIndex]) {
                    // Assign this direction to the current digit
                    directionMapping[digitIndex] = dirIndex;
                    usedDirections[dirIndex] = true;

                    // Recurse to assign a direction to the next digit
                    count += countValidPermutations(digitIndex + 1, usedDirections, directionMapping);

                    // Backtrack: unassign direction to try others
                    usedDirections[dirIndex] = false;
                }
            }
            return count;
        }

        /**
         * Simulates the path based on the current direction mapping to check if 'E' is reachable.
         *
         * @param directionMapping The current mapping of digits to directions.
         * @return true if 'E' is reached, false otherwise.
         */
        private boolean isValidPath(int[] directionMapping) {
            int currentRow = startRow;
            int currentCol = startCol;

            for (int i = 0; i < commands.length(); i++) {
                char commandChar = commands.charAt(i);
                int digit = commandChar - '0';
                int directionIndex = directionMapping[digit];

                // Update position based on direction
                currentRow += DR[directionIndex];
                currentCol += DC[directionIndex];

                // Check boundaries
                if (currentRow < 0 || currentRow >= height ||
                    currentCol < 0 || currentCol >= width) {
                    return false;
                }

                // Check for obstacle
                if (grid[currentRow][currentCol] == '#') {
                    return false;
                }

                // Check for exit
                if (grid[currentRow][currentCol] == 'E') {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public boolean hasNext() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return false;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        public String next() {
            if (hasNext()) {
                return tokenizer.nextToken();
            }
            return null;
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Solves a grid-based pathfinding problem where a robot must reach an endpoint 'E'
 * from a start point 'S' following a sequence of commands ('0'-'3').
 * Each command digit maps to a unique direction (up, down, left, right).
 * The program counts how many valid permutations of direction mappings allow success.
 */
public class RobotPathSolver {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {1, 0},  // Down
        {0, -1}, // Left
        {0, 1}   // Right
    };
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = '#';
    private static final int DIRECTION_COUNT = 4;

    private final int height;
    private final int width;
    private final String[] grid;
    private final String commands;
    private int startRow;
    private int startCol;

    /**
     * Initializes the solver with grid dimensions, map data, and command sequence.
     */
    public RobotPathSolver(int height, int width, String[] grid, String commands) {
        this.height = height;
        this.width = width;
        this.grid = grid;
        this.commands = commands;
        this.startRow = -1;
        this.startCol = -1;
        locateStartPosition();
    }

    /**
     * Locates the starting position 'S' in the grid.
     */
    private void locateStartPosition() {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r].charAt(c) == START_CHAR) {
                    startRow = r;
                    startCol = c;
                    return;
                }
            }
        }
    }

    /**
     * Initiates the permutation search and returns the count of valid direction mappings.
     */
    public int solve() {
        int[] directionMapping = new int[DIRECTION_COUNT];
        boolean[] used = new boolean[DIRECTION_COUNT];
        return countValidPermutations(0, directionMapping, used);
    }

    /**
     * Recursively generates all permutations of direction mappings using backtracking.
     */
    private int countValidPermutations(int index, int[] directionMapping, boolean[] used) {
        if (index == DIRECTION_COUNT) {
            return isValidPath(directionMapping) ? 1 : 0;
        }

        int validCount = 0;
        for (int dir = 0; dir < DIRECTION_COUNT; dir++) {
            if (!used[dir]) {
                used[dir] = true;
                directionMapping[index] = dir;
                validCount += countValidPermutations(index + 1, directionMapping, used);
                used[dir] = false; // Backtrack
            }
        }
        return validCount;
    }

    /**
     * Simulates the robot's movement with a given direction mapping.
     * Returns true if the robot successfully reaches 'E' without hitting obstacles or boundaries.
     */
    private boolean isValidPath(int[] directionMapping) {
        int row = startRow;
        int col = startCol;

        for (char cmd : commands.toCharArray()) {
            int cmdIndex = cmd - '0';
            if (cmdIndex < 0 || cmdIndex >= DIRECTION_COUNT) {
                return false; // Invalid command character
            }

            int[] move = DIRECTIONS[directionMapping[cmdIndex]];
            row += move[0];
            col += move[1];

            // Check grid boundaries
            if (row < 0 || row >= height || col < 0 || col >= width) {
                return false;
            }

            char cell = grid[row].charAt(col);
            if (cell == OBSTACLE_CHAR) {
                return false;
            }
            if (cell == END_CHAR) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        scanner.nextLine(); // Consume the remainder of the first line

        String[] grid = new String[height];
        for (int i = 0; i < height; i++) {
            grid[i] = scanner.nextLine().trim();
        }

        String commands = scanner.next().trim();
        scanner.close();

        RobotPathSolver solver = new RobotPathSolver(height, width, grid, commands);
        System.out.println(solver.solve());
    }
}

