public class NewYearAndBuggyBot_908B {

    // Direction vectors: Up, Down, Left, Right
    // Represents changes in (row, column)
    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {1, 0},  // Down
        {0, -1}, // Left
        {0, 1}   // Right
    };

    public static void main(String[] args) {
        // Use try-with-resources to ensure streams are closed and flushed automatically
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out;
             InputReader in = new InputReader(inputStream);
             PrintWriter out = new PrintWriter(outputStream)) {

            TaskB solver = new TaskB();
            solver.solve(in, out);
            out.flush(); // Ensure all output is written

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class TaskB {
        private int n, m;
        private char[][] grid;
        private int startX, startY;
        private String steps;

        public void solve(InputReader in, PrintWriter out) {
            try {
                // Read grid dimensions
                n = in.nextInt();
                m = in.nextInt();

                grid = new char[n][m];

                // Read grid rows and locate the start position 'S'
                for (int i = 0; i < n; i++) {
                    String row = in.next();
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = row.charAt(j);
                        if (grid[i][j] == 'S') {
                            startX = i;
                            startY = j;
                        }
                    }
                }

                // Read the sequence of move instructions
                steps = in.next();

                // Calculate and print the number of valid permutations
                int validPaths = countValidPermutations();
                out.println(validPaths);

            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        /**
         * Counts how many permutations of directions result in a valid path from 'S' to 'E'.
         * The input string contains digits '0'-'3'. We must find a bijection (permutation)
         * mapping these digits to the 4 physical directions such that the path is valid.
         */
        private int countValidPermutations() {
            int[] mapping = new int[4]; // mapping[digit] = directionIndex (0-3)
            boolean[] usedDirections = new boolean[4];
            return generatePermutations(0, mapping, usedDirections);
        }

        /**
         * Recursive backtracking to generate all permutations of directions.
         */
        private int generatePermutations(int digit, int[] mapping, boolean[] usedDirections) {
            // Base case: All digits 0-3 have been assigned a unique direction
            if (digit == 4) {
                return simulatePath(mapping) ? 1 : 0;
            }

            int count = 0;
            for (int dirIdx = 0; dirIdx < 4; dirIdx++) {
                if (!usedDirections[dirIdx]) {
                    // Assign this direction to the current digit
                    usedDirections[dirIdx] = true;
                    mapping[digit] = dirIdx;

                    // Recurse for the next digit
                    count += generatePermutations(digit + 1, mapping, usedDirections);

                    // Backtrack: unmark direction for other permutations
                    usedDirections[dirIdx] = false;
                }
            }
            return count;
        }

        /**
         * Simulates the path based on the current direction mapping.
         * Returns true if 'E' is reached, false otherwise.
         */
        private boolean simulatePath(int[] mapping) {
            int currX = startX;
            int currY = startY;

            for (int i = 0; i < steps.length(); i++) {
                char ch = steps.charAt(i);
                int digit = ch - '0'; // Convert char '0'-'3' to int 0-3

                // Retrieve the physical direction index for this digit
                int dirIdx = mapping[digit];
                int[] dir = DIRECTIONS[dirIdx];

                int nextX = currX + dir[0];
                int nextY = currY + dir[1];

                // Check boundaries
                if (nextX < 0 || nextX >= n || nextY < 0 || nextY >= m) {
                    return false;
                }

                // Check for walls ('#')
                if (grid[nextX][nextY] == '#') {
                    return false;
                }

                // Move to next cell
                currX = nextX;
                currY = nextY;

                // Check if destination reached
                if (grid[currX][currY] == 'E') {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast Input Reader for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }

