import java.util.Scanner;

/**
 * Refactored solution for Grid Path Permutation problem.
 * Original class name R2017B renamed to GridPathSolver for better maintainability.
 * 
 * This program determines how many permutations of direction mappings (0-3)
 * allow a path from 'S' to 'E' on a grid, following a sequence of digits.
 */
public class GridPathSolver {

    // Direction Constants
    private static final int UP = 0;
    private static final int DOWN = 1;
    private static final int RIGHT = 2;
    private static final int LEFT = 3;

    // Movement deltas corresponding to UP, DOWN, RIGHT, LEFT
    // UP: row - 1, DOWN: row + 1, RIGHT: col + 1, LEFT: col - 1
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    // Grid dimensions
    private int rows;
    private int cols;

    // Grid content
    private char[][] grid;

    // Start and End coordinates
    private int startRow, startCol;
    private int endRow, endCol;

    // Sequence of directions to follow
    private String directionSequence;

    // Counter for valid permutations
    private int validPermutationCount;

    public static void main(String[] args) {
        GridPathSolver solver = new GridPathSolver();
        solver.solve();
    }

    /**
     * Orchestrates the input reading and simulation logic.
     */
    public void solve() {
        Scanner scanner = new Scanner(System.in);
        try {
            if (!scanner.hasNextInt()) {
                return;
            }

            this.rows = scanner.nextInt();
            this.cols = scanner.nextInt();

            this.grid = new char[this.rows][this.cols];

            for (int i = 0; i < this.rows; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < this.cols; j++) {
                    this.grid[i][j] = rowString.charAt(j);
                    if (this.grid[i][j] == 'S') {
                        this.startRow = i;
                        this.startCol = j;
                    } else if (this.grid[i][j] == 'E') {
                        this.endRow = i;
                        this.endCol = j;
                    }
                }
            }

            this.directionSequence = scanner.next();
        } finally {
            scanner.close();
        }

        this.validPermutationCount = 0;

        // 'used' array tracks which digits (0-3) have been assigned to a direction
        boolean[] used = new boolean[4];
        // 'directionMapping' stores the digit assigned to each direction index (0-3)
        // directionMapping[dirIndex] = digit
        int[] directionMapping = new int[4];

        generatePermutations(used, directionMapping, 0);

        System.out.println(this.validPermutationCount);
    }

    /**
     * Generates all permutations of digits 0-3 assigned to directions.
     * 
     * @param used   Tracks which digits are currently used in the permutation
     * @param mapping The current permutation state (Direction Index -> Digit)
     * @param index  The current direction index being assigned (0 to 3)
     */
    private void generatePermutations(boolean[] used, int[] mapping, int index) {
        if (index == 4) {
            // All directions assigned a unique digit, simulate the path
            if (simulatePath(mapping)) {
                this.validPermutationCount++;
            }
            return;
        }

        // Try assigning each available digit to the current direction
        for (int digit = 0; digit < 4; digit++) {
            if (!used[digit]) {
                used[digit] = true;
                mapping[index] = digit;
                generatePermutations(used, mapping, index + 1);
                used[digit] = false; // Backtrack
            }
        }
    }

    /**
     * Simulates the path based on the provided digit-to-direction mapping.
     * 
     * @param mapping An array where mapping[dir] is the digit that triggers movement in 'dir'
     * @return true if the path reaches 'E', false otherwise
     */
    private boolean simulatePath(int[] mapping) {
        // Create a reverse lookup: Digit -> Direction
        // Since mapping is a permutation, this is a bijection.
        int[] digitToDirection = new int[4];
        for (int dir = 0; dir < 4; dir++) {
            digitToDirection[mapping[dir]] = dir;
        }

        int currR = this.startRow;
        int currC = this.startCol;
        int stepIndex = 0;
        int sequenceLength = this.directionSequence.length();

        // Process the sequence step by step
        // Note: The original code used a Queue, but since the path is deterministic
        // given a specific mapping, a simple pointer iteration is sufficient and more efficient.
        while (true) {
            // Check if we have reached the destination
            if (currR == this.endRow && currC == this.endCol) {
                return true;
            }

            // If we have no more instructions and haven't reached destination
            if (stepIndex == sequenceLength) {
                return false;
            }

            // Get the digit for the current step
            char digitChar = this.directionSequence.charAt(stepIndex);
            int digit = digitChar - '0'; // Convert char to int (0-3)

            // Find the direction corresponding to this digit
            // Note: Assumes valid input digits 0-3. 
            if (digit < 0 || digit > 3) {
                return false; // Invalid digit encountered
            }

            int direction = digitToDirection[digit];

            // Calculate next position
            int nextR = currR + DR[direction];
            int nextC = currC + DC[direction];

            // Check bounds and obstacles
            if (!isInBounds(nextR, nextC) || this.grid[nextR][nextC] == '#') {
                return false; // Blocked
            }

            // Move to next position
            currR = nextR;
            currC = nextC;
            stepIndex++;
        }
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < this.rows && c >= 0 && c < this.cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors corresponding to indices 0, 1, 2, 3
    // 0: Up, 1: Down, 2: Left, 3: Right
    private static final int[][] DIRECTIONS = {
        {0, -1}, // Up
        {0, 1},  // Down
        {-1, 0}, // Left
        {1, 0}   // Right
    };

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        GridPathSolver solver = new GridPathSolver();
        solver.solve(in, out);
        out.flush();
    }

    static class GridPathSolver {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            String[] grid = new String[n];
            int startX = -1, startY = -1;

            // Read grid and locate the starting position once
            for (int i = 0; i < n; i++) {
                grid[i] = in.next();
                for (int j = 0; j < grid[i].length(); j++) {
                    if (grid[i].charAt(j) == 'S') {
                        startX = i;
                        startY = j;
                    }
                }
            }
            String sequence = in.next();

            int[] directionOrder = {0, 1, 2, 3};
            int validCount = 0;

            // Test all permutations of direction mappings
            do {
                if (isValidPath(grid, startX, startY, sequence, directionOrder)) {
                    validCount++;
                }
            } while (nextPermutation(directionOrder));

            out.println(validCount);
        }

        private boolean isValidPath(String[] grid, int startX, int startY, String sequence, int[] directionOrder) {
            int n = grid.length;
            int m = grid[0].length();
            int x = startX;
            int y = startY;

            for (int i = 0; i < sequence.length(); i++) {
                int dirIndex = sequence.charAt(i) - '0';
                int[] dir = DIRECTIONS[directionOrder[dirIndex]];
                x += dir[0];
                y += dir[1];

                // Check bounds and obstacles
                if (x < 0 || x >= n || y < 0 || y >= m || grid[x].charAt(y) == '#') {
                    return false;
                }
                // Check if destination is reached
                if (grid[x].charAt(y) == 'E') {
                    return true;
                }
            }
            return false;
        }

        private boolean nextPermutation(int[] array) {
            if (array == null || array.length <= 1) return false;

            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            if (i < 0) return false;

            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            swap(array, i, j);

            int left = i + 1;
            int right = array.length - 1;
            while (left < right) {
                swap(array, left, right);
                left++;
                right--;
            }
            return true;
        }

        private void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }

    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line = readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        private String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
    }
}

