            int shortestPath = findShortestPath(grid, sx, sy, ex, ey, h, w);
            out.println(shortestPath);
        } finally {
            out.flush();
        }
    }

    /**
     * Finds the shortest path from (sx, sy) to (ex, ey) using Dijkstra's algorithm.
     * Adjacent moves cost 0, while jumps within radius 2 cost 1.
     */
    private static int findShortestPath(char[][] grid, int sx, int sy, int ex, int ey, int h, int w) {
        PriorityQueue<State> pq = new PriorityQueue<>(Comparator.comparingInt(s -> s.distance));
        pq.add(new State(sx, sy, 0));

        boolean[][] visited = new boolean[h][w];
        int[][] minDist = new int[h][w];
        for (int[] row : minDist) {
            Arrays.fill(row, INF);
        }
        minDist[sx][sy] = 0;

        while (!pq.isEmpty()) {
            State current = pq.poll();
            int cx = current.x;
            int cy = current.y;
            int dist = current.distance;

            // Target reached
            if (cx == ex && cy == ey) {
                return dist;
            }
            // Skip already processed nodes
            if (visited[cx][cy]) {
                continue;
            }
            visited[cx][cy] = true;

            // 1. Move to adjacent cells (cost 0)
            for (int[] dir : DIRECTIONS) {
                int nx = cx + dir[0];
                int ny = cy + dir[1];
                if (isValid(nx, ny, h, w) && !visited[nx][ny] && grid[nx][ny] != '#') {
                    if (minDist[nx][ny] > dist) {
                        minDist[nx][ny] = dist;
                        pq.add(new State(nx, ny, dist));
                    }
                }
            }

            // 2. Jump to cells within radius 2 (cost 1)
            int minX = Math.max(0, cx - JUMP_RADIUS);
            int maxX = Math.min(h - 1, cx + JUMP_RADIUS);
            int minY = Math.max(0, cy - JUMP_RADIUS);
            int maxY = Math.min(w - 1, cy + JUMP_RADIUS);

            for (int i = minX; i <= maxX; i++) {
                for (int j = minY; j <= maxY; j++) {
                    if (i == cx && j == cy) continue;
                    if (visited[i][j] || grid[i][j] == '#') continue;

                    int newDist = dist + 1;
                    if (minDist[i][j] > newDist) {
                        minDist[i][j] = newDist;
                        pq.add(new State(i, j, newDist));
                    }
                }
            }
        }
        return -1; // No valid path found
    }

    private static boolean isValid(int x, int y, int h, int w) {
        return x >= 0 && x < h && y >= 0 && y < w;
    }

    /**
     * Represents a state in the priority queue: grid coordinates and current distance.
     */
    private static class State {
        int x, y, distance;
        State(int x, int y, int distance) {
            this.x = x;
            this.y = y;
            this.distance = distance;
        }
    }

    /**
     * Fast and robust input scanner for competitive programming / CLI tools.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private final StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int[] nextIntArray(int size) throws IOException {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                String token = next();
                arr[i] = token == null ? 0 : Integer.parseInt(token);
            }
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Use half of MAX_VALUE to prevent overflow when adding edge weights
    private static final int INF = Integer.MAX_VALUE / 2;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        FastPrinter out = new FastPrinter(System.out);
        new Main().solve(sc, out);
        out.flush();
    }

    void solve(FastScanner sc, FastPrinter out) {
        int h = sc.nextInt();
        int w = sc.nextInt();
        int sy = sc.nextInt() - 1;
        int sx = sc.nextInt() - 1;
        int gy = sc.nextInt() - 1;
        int gx = sc.nextInt() - 1;

        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Distance matrix initialized to infinity
        int[][] dist = new int[h][w];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }
        dist[sy][sx] = 0;

        // Priority Queue for Dijkstra's algorithm
        PriorityQueue<State> pq = new PriorityQueue<>();
        pq.add(new State(sx, sy, 0));

        // 4-directional adjacent movement vectors
        int[] dxAdj = {0, 0, 1, -1};
        int[] dyAdj = {1, -1, 0, 0};

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int cx = cur.x;
            int cy = cur.y;
            int cDist = cur.dist;

            // Skip stale entries: if we already found a shorter path, ignore this one
            if (cDist > dist[cy][cx]) {
                continue;
            }

            // Move to adjacent cells (cost 1 per step)
            for (int i = 0; i < 4; i++) {
                int nx = cx + dxAdj[i];
                int ny = cy + dyAdj[i];
                if (isValid(nx, ny, h, w) && grid[ny][nx] == '.' && dist[ny][nx] > cDist + 1) {
                    dist[ny][nx] = cDist + 1;
                    pq.add(new State(nx, ny, cDist + 1));
                }
            }

            // Jump up to 2 cells in any of the 8 directions (cost 1 per jump)
            for (int dxj = -2; dxj <= 2; dxj++) {
                for (int dyj = -2; dyj <= 2; dyj++) {
                    if (dxj == 0 && dyj == 0) continue;
                    int nx = cx + dxj;
                    int ny = cy + dyj;
                    if (isValid(nx, ny, h, w) && grid[ny][nx] == '.' && dist[ny][nx] > cDist + 1) {
                        dist[ny][nx] = cDist + 1;
                        pq.add(new State(nx, ny, cDist + 1));
                    }
                }
            }
        }

        out.println(dist[gy][gx] >= INF ? -1 : dist[gy][gx]);
    }

    /** Checks if coordinates are within grid bounds */
    private boolean isValid(int x, int y, int h, int w) {
        return x >= 0 && x < w && y >= 0 && y < h;
    }

    /** Immutable state class for Dijkstra's priority queue */
    private static class State implements Comparable<State> {
        final int x, y, dist;

        State(int x, int y, int dist) {
            this.x = x;
            this.y = y;
            this.dist = dist;
        }

        @Override
        public int compareTo(State other) {
            return Integer.compare(this.dist, other.dist);
        }
    }

    /** High-performance input reader */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("End of input");
            return Integer.parseInt(s);
        }
    }

    /** High-performance output writer */
    private static class FastPrinter {
        private final PrintWriter out;

        FastPrinter(OutputStream stream) {
            out = new PrintWriter(new BufferedOutputStream(stream));
        }

        void println(Object obj) {
            out.println(obj);
        }

        void flush() {
            out.flush();
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.PriorityQueue;

public class Main {
    private static final int DEFAULT_STACK_SIZE = 1 << 27;

    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new SolverTask(), "Solver", DEFAULT_STACK_SIZE);
        thread.start();
        thread.join();
    }

    private static class SolverTask implements Runnable {
        @Override
        public void run() {
            FastReader in = new FastReader(System.in);
            PrintWriter out = new PrintWriter(System.out);
            try {
                new MazeSolver().solve(in, out);
            } finally {
                out.flush();
                out.close();
            }
        }
    }

    public static class MazeSolver {
        private static final int[][] DIRECTION_DELTA = {
            {1, -1, 0, 0},
            {0, 0, 1, -1}
        };
        private static final int JUMP_RANGE = 2;

        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            // Grid with padding to simplify boundary checks
            char[][] grid = new char[rows + 2][cols + 2];
            for (char[] row : grid) {
                Arrays.fill(row, '#');
            }

            int startRow = in.nextInt();
            int startCol = in.nextInt();
            int targetRow = in.nextInt();
            int targetCol = in.nextInt();

            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    grid[i][j] = in.nextChar();
                }
            }

            int[][] distances = new int[rows + 2][cols + 2];
            for (int[] row : distances) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            distances[startRow][startCol] = 0;
            PriorityQueue<Node> queue = new PriorityQueue<>();
            queue.add(new Node(startRow, startCol, 0));

            while (!queue.isEmpty()) {
                Node current = queue.poll();

                // Skip outdated entries (lazy deletion in Dijkstra)
                if (current.distance > distances[current.row][current.col]) {
                    continue;
                }

                // Normal moves (cost 0)
                for (int[] dir : DIRECTION_DELTA) {
                    int nextRow = current.row + dir[0];
                    int nextCol = current.col + dir[1];

                    if (distances[nextRow][nextCol] > current.distance && grid[nextRow][nextCol] != '#') {
                        distances[nextRow][nextCol] = current.distance;
                        queue.add(new Node(nextRow, nextCol, current.distance));
                    }
                }

                // Jump moves (cost 1)
                for (int dr = -JUMP_RANGE; dr <= JUMP_RANGE; dr++) {
                    for (int dc = -JUMP_RANGE; dc <= JUMP_RANGE; dc++) {
                        if (dr == 0 && dc == 0) continue;

                        int nextRow = current.row + dr;
                        int nextCol = current.col + dc;

                        if (nextRow >= 1 && nextRow <= rows &&
                            nextCol >= 1 && nextCol <= cols &&
                            distances[nextRow][nextCol] > current.distance + 1 &&
                            grid[nextRow][nextCol] != '#') {
                            distances[nextRow][nextCol] = current.distance + 1;
                            queue.add(new Node(nextRow, nextCol, current.distance + 1));
                        }
                    }
                }
            }

            int result = distances[targetRow][targetCol];
            out.println(result == Integer.MAX_VALUE ? -1 : result);
        }
    }

    private static class Node implements Comparable<Node> {
        private final int row;
        private final int col;
        private final int distance;

        public Node(int row, int col, int distance) {
            this.row = row;
            this.col = col;
            this.distance = distance;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.distance, other.distance);
        }
    }

    public static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPos;
        private int bytesRead;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (bufferPos >= bytesRead) {
                bufferPos = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException("Failed to read input", e);
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Invalid integer");
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));

            return result * sign;
        }

        public char nextChar() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors for 4-connected movement
    private static final int[][] MOVES = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Read grid dimensions
        int h = reader.nextInt();
        int w = reader.nextInt();

        // Read start and end coordinates (convert to 0-indexed)
        int startI = reader.nextInt() - 1;
        int startJ = reader.nextInt() - 1;
        int endI = reader.nextInt() - 1;
        int endJ = reader.nextInt() - 1;

        // Read grid
        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Step 1: Identify connected components of '.' cells
        int[][] componentId = new int[h][w];
        int componentCount = 0;

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (componentId[i][j] == 0 && grid[i][j] == '.') {
                    componentCount++;
                    bfsFillComponent(grid, componentId, i, j, componentCount, h, w);
                }
            }
        }

        // Step 2: Build adjacency graph between components
        // Nodes are 1-based component IDs (0 represents walls/empty space)
        List<Set<Integer>> adj = new ArrayList<>(componentCount + 1);
        for (int i = 0; i <= componentCount; i++) {
            adj.add(new HashSet<>());
        }

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                int compA = componentId[i][j];
                if (compA == 0) continue;

                // Check all cells within a 5x5 window (Chebyshev distance <= 2)
                for (int di = -2; di <= 2; di++) {
                    for (int dj = -2; dj <= 2; dj++) {
                        int ni = i + di;
                        int nj = j + dj;
                        if (!isValid(ni, nj, h, w)) continue;

                        int compB = componentId[ni][nj];
                        // Add bidirectional edge if neighbor belongs to a different component
                        if (compB != 0 && compB != compA) {
                            adj.get(compA).add(compB);
                            adj.get(compB).add(compA);
                        }
                    }
                }
            }
        }

        // Step 3: BFS to find shortest path (in component hops) between start and end
        int startComp = componentId[startI][startJ];
        int endComp = componentId[endI][endJ];
        int result = bfsShortestPath(adj, startComp, endComp, componentCount);

        out.println(result);
        out.flush();
    }

    /**
     * Performs BFS to label all cells in a connected component with the same ID.
     */
    private static void bfsFillComponent(char[][] grid, int[][] componentId, 
                                         int r, int c, int id, int h, int w) {
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{r, c});
        componentId[r][c] = id;

        while (!q.isEmpty()) {
            int[] curr = q.poll();
            for (int[] move : MOVES) {
                int nr = curr[0] + move[0];
                int nc = curr[1] + move[1];
                if (isValid(nr, nc, h, w) && grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                    componentId[nr][nc] = id;
                    q.offer(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int h, int w) {
        return r >= 0 && r < h && c >= 0 && c < w;
    }

    /**
     * Finds the shortest path (in number of component hops) between two components.
     * Returns -1 if unreachable.
     */
    private static int bfsShortestPath(List<Set<Integer>> adj, int start, int end, int maxNodes) {
        if (start == end) return 0;

        int[] dist = new int[maxNodes + 1];
        Arrays.fill(dist, -1);
        dist[start] = 0;

        Queue<Integer> q = new ArrayDeque<>();
        q.offer(start);

        while (!q.isEmpty()) {
            int curr = q.poll();
            for (int neighbor : adj.get(curr)) {
                if (dist[neighbor] == -1) {
                    dist[neighbor] = dist[curr] + 1;
                    if (neighbor == end) return dist[neighbor];
                    q.offer(neighbor);
                }
            }
        }
        return -1;
    }

    /**
     * Fast I/O helper for competitive programming environments.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

