/**
 * Immutable coordinate class for grid positions.
 * Replaces the original PPKEY class with a modern, concise record.
 */
record Coordinate(int row, int col) {}

/**
 * Encapsulates the grid pathfinding logic.
 * Solves for the minimum steps to reach the target from the start,
 * allowing adjacent movement and jumps up to 2 cells (Chebyshev distance).
 */
class GridSolver {
    private final int height, width;
    private final char[][] grid;
    private final boolean[][] visited;
    private final int startRow, startCol, targetRow, targetCol;

    // Direction vectors for up, left, right, down
    private static final int[] DR = {-1, 0, 0, 1};
    private static final int[] DC = {0, -1, 1, 0};

    private final PrintWriter out;

    public GridSolver(FastScanner scanner, PrintWriter out) {
        this.height = scanner.nextInt();
        this.width = scanner.nextInt();
        this.startRow = scanner.nextInt() - 1;
        this.startCol = scanner.nextInt() - 1;
        this.targetRow = scanner.nextInt() - 1;
        this.targetCol = scanner.nextInt() - 1;

        this.grid = new char[height][];
        for (int i = 0; i < height; i++) {
            this.grid[i] = scanner.next().toCharArray();
        }

        this.visited = new boolean[height][width];
        this.out = out;
    }

    public void solve() {
        Set<Coordinate> currentFrontier = new HashSet<>();
        currentFrontier.add(new Coordinate(startRow, startCol));

        for (int step = 0; ; step++) {
            Set<Coordinate> visitedThisStep = new HashSet<>();
            boolean targetReached = false;

            // Attempt BFS from each cell in the current frontier
            for (Coordinate cell : currentFrontier) {
                visitedThisStep.add(cell);
                visited[cell.row()][cell.col()] = true;

                if (bfsFrom(cell, visitedThisStep)) {
                    targetReached = true;
                    break;
                }
            }

            if (targetReached) {
                out.println(step);
                return;
            }

            // Generate next frontier: cells within a 5x5 area (radius 2)
            Set<Coordinate> nextFrontier = new HashSet<>();
            for (Coordinate cell : visitedThisStep) {
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = cell.row() + dr;
                        int nc = cell.col() + dc;
                        if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                            visited[nr][nc] = true;
                            nextFrontier.add(new Coordinate(nr, nc));
                        }
                    }
                }
            }

            if (nextFrontier.isEmpty()) {
                out.println("-1");
                return;
            }

            currentFrontier = nextFrontier;
        }
    }

    /**
     * Performs a BFS starting from the given cell.
     * Marks visited cells globally and tracks them in visitedThisStep.
     * Returns true if the target is reached.
     */
    private boolean bfsFrom(Coordinate start, Set<Coordinate> visitedThisStep) {
        if (start.row() == targetRow && start.col() == targetCol) {
            return true;
        }

        Deque<Coordinate> queue = new ArrayDeque<>();
        queue.add(start);

        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = curr.row() + DR[i];
                int nc = curr.col() + DC[i];

                if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    if (nr == targetRow && nc == targetCol) {
                        return true;
                    }
                    visited[nr][nc] = true;
                    visitedThisStep.add(new Coordinate(nr, nc));
                    queue.add(new Coordinate(nr, nc));
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

