    }

    /**
     * Encapsulates the 0-1 BFS logic for finding shortest path on the grid.
     * Separates state and behavior from the main entry point for better testability.
     */
    static class GridSolver {
        private final int height;
        private final int width;
        private final boolean[][] walkable;
        private final int[][] distances;
        private final Deque<Point> queue;
        private final Deque<Point> cornerQueue;

        public GridSolver(int height, int width, boolean[][] walkable) {
            this.height = height;
            this.width = width;
            this.walkable = walkable;
            this.distances = new int[height][width];
            for (int[] row : distances) {
                for (int j = 0; j < width; j++) {
                    row[j] = -1;
                }
            }
            this.queue = new ArrayDeque<>();
            this.cornerQueue = new ArrayDeque<>();
        }

        public void solve(int startH, int startW, int endH, int endW) {
            distances[startH][startW] = 0;
            queue.add(new Point(startH, startW));

            while (!queue.isEmpty()) {
                // Process all nodes reachable with current cost (0-cost moves)
                while (!queue.isEmpty()) {
                    Point current = queue.remove();
                    boolean up = tryMove(current, 0, -1, 0);
                    boolean down = tryMove(current, 0, 1, 0);
                    boolean left = tryMove(current, 0, 0, -1);
                    boolean right = tryMove(current, 0, 0, 1);

                    // If any cardinal direction is blocked or unreachable, 
                    // mark as a candidate for warp moves
                    if (!up || !down || !left || !right) {
                        cornerQueue.add(current);
                    }
                }

                // Process "corner" nodes with warp moves (1-cost moves)
                while (!cornerQueue.isEmpty()) {
                    Point current = cornerQueue.remove();
                    for (int[] delta : WARP_DELTA) {
                        tryMove(current, 1, delta[0], delta[1]);
                    }
                }
            }
        }

        /**
         * Attempts to move to an adjacent cell. Updates distance and queue if a shorter path is found.
         * Returns true if the move was successfully processed, false otherwise.
         */
        private boolean tryMove(Point current, int cost, int dh, int dw) {
            int nh = current.h + dh;
            int nw = current.w + dw;

            if (nh < 0 || nh >= height || nw < 0 || nw >= width) {
                return false;
            }
            if (!walkable[nh][nw]) {
                return false;
            }

            int newDist = distances[current.h][current.w] + cost;
            if (distances[nh][nw] == -1 || newDist < distances[nh][nw]) {
                distances[nh][nw] = newDist;
                // 0-cost moves go to front, 1-cost moves go to back (0-1 BFS optimization)
                if (cost == 0) {
                    queue.addFirst(new Point(nh, nw));
                } else {
                    queue.add(new Point(nh, nw));
                }
                return true;
            }
            return false;
        }

        public int getDistance(int h, int w) {
            return distances[h][w];
        }

        /**
         * Immutable coordinate holder. Removed unused 'warp' field from original.
         */
        static class Point {
            final int h;
            final int w;

            Point(int h, int w) {
                this.h = h;
                this.w = w;
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

/**
 * Refactored program to solve the grid shortest path problem.
 * 
 * Improvements made:
 * 1. Improved variable naming (e.g., 'h' -> 'rows', 'grd' -> 'isWall', 'memo' -> 'distances').
 * 2. Encapsulated logic into methods (parsing, solving, validation) for better structure.
 * 3. Replaced magic numbers with named constants (INF, JUMP_RADIUS).
 * 4. Used a Point class for better coordinate handling readability.
 * 5. Fixed the direction logic to explicitly cover all 4 cardinal directions (Up, Down, Left, Right).
 * 6. Added comments explaining the 0-1 BFS algorithm and logic.
 * 7. Optimized input reading using sc.nextInt() where appropriate.
 */
public class Main {

    // Constants
    private static final int INF = Integer.MAX_VALUE;
    private static final int JUMP_RADIUS = 2;

    // Direction vectors for 4-connected movement (Up, Down, Left, Right)
    // dy: {-1, 1, 0, 0}, dx: {0, 0, -1, 1}
    private static final int[] DY = {-1, 1, 0, 0};
    private static final int[] DX = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 1. Input Parsing
        // Check if input exists to prevent exceptions on empty input
        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        // Convert 1-based input coordinates to 0-based
        int startY = sc.nextInt() - 1;
        int startX = sc.nextInt() - 1;
        int targetY = sc.nextInt() - 1;
        int targetX = sc.nextInt() - 1;

        // Read the grid
        boolean[][] isWall = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                isWall[i][j] = (line.charAt(j) == '#');
            }
        }

        // 2. Solve
        int result = solveBFS(rows, cols, startY, startX, targetY, targetX, isWall);

        // 3. Output
        System.out.println(result);

        sc.close();
    }

    /**
     * Solves the shortest path problem using 0-1 BFS.
     * - Moving to an adjacent non-wall cell costs 0.
     * - Jumping to a cell within distance 2 (Chebyshev distance <= 2) costs 1.
     */
    private static int solveBFS(int rows, int cols, int startY, int startX, 
                                int targetY, int targetX, boolean[][] isWall) {

        // Distance matrix initialized to infinity
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        // Deque for 0-1 BFS
        Deque<Point> deque = new ArrayDeque<>();

        // Initialize start point
        Point start = new Point(startY, startX);
        distances[startY][startX] = 0;
        deque.addFirst(start);

        while (!deque.isEmpty()) {
            Point current = deque.poll();
            int cy = current.y;
            int cx = current.x;
            int currentDist = distances[cy][cx];

            // If we reached the target, return the distance.
            // 0-1 BFS guarantees that the first time we pop a node, 
            // it is via the shortest path.
            if (cy == targetY && cx == targetX) {
                return currentDist;
            }

            // Move Type 1: Adjacent cells (Cost 0)
            // Check 4 neighbors (Up, Down, Left, Right)
            for (int i = 0; i < 4; i++) {
                int ny = cy + DY[i];
                int nx = cx + DX[i];

                if (isValid(ny, nx, rows, cols) && !isWall[ny][nx]) {
                    // If we found a shorter path to this neighbor
                    if (distances[ny][nx] > currentDist) {
                        distances[ny][nx] = currentDist;
                        deque.addFirst(new Point(ny, nx)); // 0 cost -> add to front
                    }
                }
            }

            // Move Type 2: Jump within range [y-2, y+2] x [x-2, x+2] (Cost 1)
            // This allows moving to any cell within a 5x5 area centered at current position.
            int minY = Math.max(0, cy - JUMP_RADIUS);
            int maxY = Math.min(rows - 1, cy + JUMP_RADIUS);
            int minX = Math.max(0, cx - JUMP_RADIUS);
            int maxX = Math.min(cols - 1, cx + JUMP_RADIUS);

            for (int ny = minY; ny <= maxY; ny++) {
                for (int nx = minX; nx <= maxX; nx++) {
                    if (!isWall[ny][nx]) {
                        // Check if jumping here is better than current known distance
                        if (distances[ny][nx] > currentDist + 1) {
                            distances[ny][nx] = currentDist + 1;
                            deque.addLast(new Point(ny, nx)); // 1 cost -> add to back
                        }
                    }
                }
            }
        }

        // If target is unreachable
        return -1;
    }

    private static boolean isValid(int y, int x, int rows, int cols) {
        return y >= 0 && y < rows && x >= 0 && x < cols;
    }

    // Helper class to store coordinates
    private static class Point {
        int y, x;
        Point(int y, int x) {
            this.y = y;
            this.x = x;
        }
    }
}

import java.util.Deque;
import java.util.LinkedList;
import java.util.Scanner;
import java.util.Arrays;

public class Main {

    // Constant for representing infinity distance
    private static final int INF = 1_000_000_000;

    // Directions: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /**
     * Inner class representing a cell in the grid with its current distance.
     */
    private static class Cell {
        int row;
        int col;
        int distance;

        Cell(int row, int col, int distance) {
            this.row = row;
            this.col = col;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read start position (convert 1-based input to 0-based)
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;

        // Read target position (convert 1-based input to 0-based)
        int targetRow = scanner.nextInt() - 1;
        int targetCol = scanner.nextInt() - 1;

        // Read the map
        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }

        // Initialize distance array with infinity
        // Using dynamic sizing based on input instead of hardcoded 1003
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        // BFS Initialization
        Deque<Cell> deque = new LinkedList<>();
        deque.add(new Cell(startRow, startCol, 0));
        distances[startRow][startCol] = 0;

        // BFS Loop
        while (!deque.isEmpty()) {
            Cell current = deque.pollFirst();
            int r = current.row;
            int c = current.col;
            int dist = current.distance;

            // 1. Move to adjacent cells (Up, Down, Left, Right)
            // Logic: Cost remains the same (0-weight edge)
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc, rows, cols) && grid[nr].charAt(nc) != '#'
                        && distances[nr][nc] > dist) {
                    distances[nr][nc] = dist;
                    deque.addFirst(new Cell(nr, nc, dist));
                }
            }

            // 2. Move to cells within range 2 (Jump)
            // Logic: Cost increases by 1 (1-weight edge)
            // We check a 5x5 area centered at the current cell
            int minR = Math.max(0, r - 2);
            int maxR = Math.min(rows - 1, r + 2);
            int minC = Math.max(0, c - 2);
            int maxC = Math.min(cols - 1, c + 2);

            for (int i = minR; i <= maxR; i++) {
                for (int j = minC; j <= maxC; j++) {
                    if (grid[i].charAt(j) != '#' && distances[i][j] > dist + 1) {
                        distances[i][j] = dist + 1;
                        deque.addLast(new Cell(i, j, dist + 1));
                    }
                }
            }
        }

        // Output result
        int result = distances[targetRow][targetCol];
        System.out.println(result == INF ? -1 : result);

        scanner.close();
    }

    // Helper method to check bounds
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {

    private static final int MAGIC_RANGE = 2;

    public static void main(String[] args) {
        new Main().solve();
    }

    private void solve() {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer tokenizer = new StringTokenizer(line);
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            tokenizer = new StringTokenizer(reader.readLine());
            int startX = Integer.parseInt(tokenizer.nextToken()) - 1;
            int startY = Integer.parseInt(tokenizer.nextToken()) - 1;

            tokenizer = new StringTokenizer(reader.readLine());
            int endX = Integer.parseInt(tokenizer.nextToken()) - 1;
            int endY = Integer.parseInt(tokenizer.nextToken()) - 1;

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowLine = reader.readLine();
                if (rowLine != null) {
                    grid[i] = rowLine.toCharArray();
                }
            }

            // Step 1: Identify Connected Components (Flood Fill)
            // Replaces 'roads' array. Stores the component ID for each cell.
            int[][] componentIds = new int[rows][cols];
            for (int[] row : componentIds) {
                Arrays.fill(row, -1);
            }

            int componentCount = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentIds[i][j] == -1) {
                        floodFill(grid, componentIds, i, j, componentCount++, rows, cols);
                    }
                }
            }

            // Step 2: Build Adjacency Graph between components
            // Replaces 'connectedTo' array. Uses List<Set> to avoid generic array warnings.
            List<Set<Integer>> adjacencyList = new ArrayList<>(componentCount);
            for (int i = 0; i < componentCount; i++) {
                adjacencyList.add(new HashSet<>());
            }

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '#') continue;

                    int currentComponent = componentIds[i][j];

                    // Check neighbors within MAGIC_RANGE (5x5 area centered at current cell)
                    // This replaces the nested loops for 'goodMagic' check
                    for (int di = -MAGIC_RANGE; di <= MAGIC_RANGE; di++) {
                        for (int dj = -MAGIC_RANGE; dj <= MAGIC_RANGE; dj++) {
                            int ni = i + di;
                            int nj = j + dj;

                            if (isValid(ni, nj, rows, cols) && grid[ni][nj] == '.') {
                                int neighborComponent = componentIds[ni][nj];
                                // Connect if it's a different component
                                if (currentComponent != neighborComponent) {
                                    adjacencyList.get(currentComponent).add(neighborComponent);
                                }
                            }
                        }
                    }
                }
            }

            // Step 3: BFS to find the shortest path between start and end components
            // Replaces 'shortesPathToRoad' logic (typo fixed)
            int startComponent = componentIds[startX][startY];
            int endComponent = componentIds[endX][endY];

            // Handle edge case where start or end is on a wall '#'
            if (startComponent == -1 || endComponent == -1) {
                out.println(-1);
            } else {
                int result = bfsShortestPath(adjacencyList, startComponent, endComponent, componentCount);
                out.println(result);
            }

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Performs BFS to label connected components of '.' cells.
     * Replaces the manual queue logic in the original code.
     */
    private void floodFill(char[][] grid, int[][] componentIds, int startR, int startC, int componentId, int rows, int cols) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        componentIds[startR][startC] = componentId;

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int k = 0; k < 4; k++) {
                int nr = curr.r + dr[k];
                int nc = curr.c + dc[k];

                // Replaces 'goodAdjacent' check
                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentIds[nr][nc] == -1) {
                    componentIds[nr][nc] = componentId;
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Performs BFS to find the shortest path between two components in the graph.
     * Replaces the second BFS loop in the original code.
     */
    private int bfsShortestPath(List<Set<Integer>> graph, int startNode, int endNode, int numNodes) {
        if (startNode == endNode) return 0;

        int[] distances = new int[numNodes];
        Arrays.fill(distances, -1);
        distances[startNode] = 0;

        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(startNode);

        while (!queue.isEmpty()) {
            int u = queue.poll();

            if (u == endNode) return distances[u];

            for (int v : graph.get(u)) {
                if (distances[v] == -1) {
                    distances[v] = distances[u] + 1;
                    queue.add(v);
                    if (v == endNode) return distances[v];
                }
            }
        }
        return -1;
    }

    /**
     * Simple class to represent a coordinate point, replacing int[] arrays for readability.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    // Use a value safely below Integer.MAX_VALUE to prevent overflow during addition
    private static final int INF = Integer.MAX_VALUE / 2;

    public static void main(String[] args) {
        // Support optional debug file input
        InputStream inputStream = System.in;
        if (args.length > 0) {
            try {
                inputStream = Files.newInputStream(Paths.get(args[0]));
            } catch (IOException e) {
                throw new UncheckedIOException("Failed to open debug file", e);
            }
        }

        // Run in a thread with increased stack size (common in competitive programming)
        new Thread(null, () -> solve(inputStream), "solver", 64 * 1024 * 1024).start();
    }

    private static void solve(InputStream inputStream) {
        FastReader sc = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int h = sc.nextInt();
            int w = sc.nextInt();

            int[] start = new int[]{sc.nextInt(), sc.nextInt()};
            int[] goal = new int[]{sc.nextInt(), sc.nextInt()};

            // Padded grid to simplify boundary checks (indices 1..h, 1..w are used)
            char[][] grid = new char[h + 2][w + 2];
            for (int i = 1; i <= h; i++) {
                String line = sc.next();
                for (int j = 1; j <= w; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }

            int[][] distances = dijkstra(grid, start, goal);
            int result = distances[goal[0]][goal[1]];

            out.println(result >= INF ? -1 : result);
        } finally {
            out.flush();
        }
    }

    private static int[][] dijkstra(char[][] grid, int[] start, int[] goal) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        // PriorityQueue stores (distance, row, col). Stale entries are skipped during polling.
        // This replaces the buggy TreeSet approach where dynamic distance changes broke ordering.
        PriorityQueue<Node> pq = new PriorityQueue<>();
        distances[start[0]][start[1]] = 0;
        pq.add(new Node(start[0], start[1], 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();

            // If we found a shorter path to this cell already, skip this stale entry
            if (current.dist > distances[current.r][current.c]) {
                continue;
            }

            // Early exit optimization
            if (current.r == goal[0] && current.c == goal[1]) {
                break;
            }

            // Explore all cells within a 2x2 radius
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    int nr = current.r + dr;
                    int nc = current.c + dc;

                    // Boundary check
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                        continue;
                    }

                    // Only walkable cells
                    if (grid[nr][nc] != '.') {
                        continue;
                    }

                    // Cost: 0 for adjacent cells (Manhattan distance <= 1), 1 otherwise
                    int cost = (Math.abs(dr) + Math.abs(dc) <= 1) ? 0 : 1;
                    int newDist = current.dist + cost;

                    if (newDist < distances[nr][nc]) {
                        distances[nr][nc] = newDist;
                        pq.add(new Node(nr, nc, newDist));
                    }
                }
            }
        }

        return distances;
    }

    // Immutable data class for Dijkstra priority queue elements
    private static class Node implements Comparable<Node> {
        final int r, c, dist;

        Node(int r, int c, int dist) {
            this.r = r;
            this.c = c;
            this.dist = dist;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.dist, other.dist);
        }
    }

    // Fast I/O helper class to replace verbose static methods
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) throw new EOFException();
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {

    // Constants to eliminate magic numbers and improve readability
    private static final int WARP_RADIUS = 2;
    private static final int START_INDEX_OFFSET = 1; // Input coordinates are 1-based
    private static final int UNREACHABLE = -1;
    private static final int MAX_WARPS = Integer.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int[] dimensions = readLineInts(br, 2);
            int height = dimensions[0];
            int width = dimensions[1];

            int[] startCoords = readLineInts(br, 2);
            int startRow = startCoords[0] - START_INDEX_OFFSET;
            int startCol = startCoords[1] - START_INDEX_OFFSET;

            int[] destCoords = readLineInts(br, 2);
            int destRow = destCoords[0] - START_INDEX_OFFSET;
            int destCol = destCoords[1] - START_INDEX_OFFSET;

            char[][] grid = readGrid(br, height);

            int result = solve(height, width, startRow, startCol, destRow, destCol, grid);
            System.out.println(result);
        }
    }

    /**
     * Reads a line from the BufferedReader and parses it into an array of integers.
     * Uses StringTokenizer for robust whitespace handling.
     */
    private static int[] readLineInts(BufferedReader br, int count) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] result = new int[count];
        for (int i = 0; i < count; i++) {
            result[i] = Integer.parseInt(st.nextToken());
        }
        return result;
    }

    /**
     * Reads the grid rows into a char[][] for O(1) access and easier manipulation.
     */
    private static char[][] readGrid(BufferedReader br, int height) throws IOException {
        char[][] grid = new char[height][];
        for (int i = 0; i < height; i++) {
            grid[i] = br.readLine().trim().toCharArray();
        }
        return grid;
    }

    /**
     * Core BFS algorithm to find the minimum number of warps required.
     */
    private static int solve(int h, int w, int startH, int startW, int destH, int destW, char[][] grid) {
        if (startH == destH && startW == destW) {
            return 0;
        }

        int[][] warpCount = new int[h][w];
        for (int[] row : warpCount) {
            Arrays.fill(row, MAX_WARPS);
        }

        warpCount[startH][startW] = 0;

        // Current layer: normal moves within the same warp step
        Deque<Player> currentLayer = new ArrayDeque<>();
        // Next layer: destinations reached via a warp
        Deque<Player> nextLayer = new ArrayDeque<>();
        // Candidates for the next warp step
        Set<Player> warpCandidates = new HashSet<>();

        currentLayer.add(new Player(startH, startW));
        int currentWarpCount = 0;

        while (!currentLayer.isEmpty()) {
            // Process all positions in the current warp step
            while (!currentLayer.isEmpty()) {
                Player player = currentLayer.poll();

                // Early exit: BFS guarantees the first time we reach the destination,
                // it is via the shortest path.
                if (player.h == destH && player.w == destW) {
                    return currentWarpCount;
                }

                // Try normal moves (cost 0 relative to current warp count)
                addNormalMove(player.h - 1, player.w, h, w, grid, warpCount, currentWarpCount, currentLayer);
                addNormalMove(player.h + 1, player.w, h, w, grid, warpCount, currentWarpCount, currentLayer);
                addNormalMove(player.h, player.w - 1, h, w, grid, warpCount, currentWarpCount, currentLayer);
                addNormalMove(player.h, player.w + 1, h, w, grid, warpCount, currentWarpCount, currentLayer);

                // Try warp moves (cost 1)
                for (int i = player.h - WARP_RADIUS; i <= player.h + WARP_RADIUS; i++) {
                    for (int j = player.w - WARP_RADIUS; j <= player.w + WARP_RADIUS; j++) {
                        if (isValidWarpTarget(i, j, player, h, w, grid)) {
                            int newWarpCount = currentWarpCount + 1;
                            if (warpCount[i][j] > newWarpCount) {
                                warpCount[i][j] = newWarpCount;
                                warpCandidates.add(new Player(i, j));
                            }
                        }
                    }
                }
            }

            // Prepare for the next warp step
            currentWarpCount++;
            for (Player p : warpCandidates) {
                if (warpCount[p.h][p.w] == currentWarpCount) {
                    nextLayer.add(p);
                }
            }
            warpCandidates.clear();

            // Swap layers
            currentLayer = nextLayer;
            nextLayer = new ArrayDeque<>();
        }

        return warpCount[destH][destW] == MAX_WARPS ? UNREACHABLE : warpCount[destH][destW];
    }

    /**
     * Validates and enqueues a normal move if it improves the warp count.
     */
    private static void addNormalMove(int r, int c, int h, int w, char[][] grid, int[][] warpCount, 
                                      int currentWarpCount, Deque<Player> queue) {
        if (r >= 0 && r < h && c >= 0 && c < w && grid[r][c] == '.' && warpCount[r][c] > currentWarpCount) {
            warpCount[r][c] = currentWarpCount;
            queue.add(new Player(r, c));
        }
    }

    /**
     * Checks if a cell is a valid warp target.
     */
    private static boolean isValidWarpTarget(int r, int c, Player player, int h, int w, char[][] grid) {
        return r >= 0 && r < h && c >= 0 && c < w
            && (r != player.h || c != player.w)
            && grid[r][c] == '.';
    }

    /**
     * Represents a coordinate in the grid.
     * Implemented as an immutable value object with proper equals/hashCode for HashSet usage.
     */
    static class Player {
        final int h;
        final int w;

        Player(int h, int w) {
            this.h = h;
            this.w = w;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Player)) return false;
            Player player = (Player) o;
            return h == player.h && w == player.w;
        }

        @Override
        public int hashCode() {
            return 31 * h + w;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {

    // Constants for grid traversal and algorithm behavior
    private static final int MAX_JUMP = 2;
    private static final int ADJACENT_COST = 0;
    private static final int LONG_JUMP_COST = 1;
    private static final int UNVISITED = -1;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter writer = new PrintWriter(System.out);
        try {
            solve(scanner, writer);
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter writer) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        boolean[][] grid = readGrid(scanner, rows, cols);
        int[][] distances = initializeDistances(rows, cols);

        distances[startRow][startCol] = 0;
        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.add(new Node(startRow, startCol, 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();
            int currentDist = distances[current.row][current.col];

            // Skip stale entries: if we already found a shorter path, ignore this one
            if (current.dist > currentDist) {
                continue;
            }

            // Early exit if we reached the destination
            if (current.row == endRow && current.col == endCol) {
                break;
            }

            // Explore all possible moves within the jump range
            for (int dr = -MAX_JUMP; dr <= MAX_JUMP; dr++) {
                for (int dc = -MAX_JUMP; dc <= MAX_JUMP; dc++) {
                    if (dr == 0 && dc == 0) continue;

                    int r = current.row + dr;
                    int c = current.col + dc;

                    if (!isValid(r, c, rows, cols) || !grid[r][c]) {
                        continue;
                    }

                    int moveCost = (Math.abs(dr) + Math.abs(dc) == 1) ? ADJACENT_COST : LONG_JUMP_COST;
                    int newDist = currentDist + moveCost;

                    if (distances[r][c] == UNVISITED || newDist < distances[r][c]) {
                        distances[r][c] = newDist;
                        pq.add(new Node(r, c, newDist));
                    }
                }
            }
        }

        writer.println(distances[endRow][endCol]);
    }

    private static boolean[][] readGrid(FastScanner scanner, int rows, int cols) {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j) == '.';
            }
        }
        return grid;
    }

    private static int[][] initializeDistances(int rows, int cols) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNVISITED);
        }
        return distances;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a grid cell and its current shortest distance in Dijkstra's algorithm.
     */
    private static final class Node implements Comparable<Node> {
        final int row;
        final int col;
        final int dist;

        Node(int row, int col, int dist) {
            this.row = row;
            this.col = col;
            this.dist = dist;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.dist, other.dist);
        }
    }

    /**
     * Fast I/O helper optimized for competitive programming style input reading.
     */
    private static final class FastScanner {
        private final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer tokenizer = new StringTokenizer("");

        String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class Main {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is automatically closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // Read grid dimensions
            String[] dims = readTokens(br);
            int height = Integer.parseInt(dims[0]);
            int width = Integer.parseInt(dims[1]);

            // Read start coordinates and convert to 0-based indexing
            String[] start = readTokens(br);
            int startX = Integer.parseInt(start[0]) - 1;
            int startY = Integer.parseInt(start[1]) - 1;

            // Read end coordinates and convert to 0-based indexing
            String[] end = readTokens(br);
            int endX = Integer.parseInt(end[0]) - 1;
            int endY = Integer.parseInt(end[1]) - 1;

            // Read the grid board
            char[][] board = new char[height][width];
            for (int i = 0; i < height; i++) {
                String line = br.readLine();
                if (line != null) {
                    board[i] = line.trim().toCharArray();
                }
            }

            // Execute pathfinding and print result
            Pathfinder pathfinder = new Pathfinder(board, height, width);
            int shortestDistance = pathfinder.findShortestPath(startX, startY, endX, endY);
            System.out.println(shortestDistance);
        }
    }

    /**
     * Reads the next non-empty line from the buffer and splits it into whitespace-delimited tokens.
     */
    private static String[] readTokens(BufferedReader br) throws IOException {
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) {
            throw new IOException("Unexpected end of input");
        }
        return line.trim().split("\\s+");
    }

    /**
     * Encapsulates the grid data and the BFS algorithm for pathfinding.
     * Eliminates global state and groups related logic together.
     */
    static class Pathfinder {
        private final char[][] board;
        private final int height;
        private final int width;

        // Direction vectors for adjacent moves (up, left, down, right)
        private static final int[][] ADJACENT_DIRECTIONS = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};
        private static final char WALKABLE_CELL = '.';

        public Pathfinder(char[][] board, int height, int width) {
            this.board = board;
            this.height = height;
            this.width = width;
        }

        /**
         * Performs a 0-1 BFS to find the shortest path from start to end.
         * Adjacent moves have a cost of 0, while 2-step jumps have a cost of 1.
         */
        public int findShortestPath(int startX, int startY, int endX, int endY) {
            int[][] distances = new int[height][width];
            for (int[] row : distances) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            Deque<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startX, startY});
            distances[startX][startY] = 0;

            while (!queue.isEmpty()) {
                int[] current = queue.pollFirst();
                int currentX = current[0];
                int currentY = current[1];
                int currentDist = distances[currentX][currentY];

                // Process adjacent cells (cost 0)
                for (int[] dir : ADJACENT_DIRECTIONS) {
                    int nextX = currentX + dir[0];
                    int nextY = currentY + dir[1];
                    if (isLegal(nextX, nextY) && distances[nextX][nextY] > currentDist) {
                        distances[nextX][nextY] = currentDist;
                        queue.addFirst(new int[]{nextX, nextY});
                    }
                }

                // Process 2-step jumps (cost 1)
                for (int dx = -2; dx <= 2; dx++) {
                    for (int dy = -2; dy <= 2; dy++) {
                        int nextX = currentX + dx;
                        int nextY = currentY + dy;
                        if (isLegal(nextX, nextY) && distances[nextX][nextY] > currentDist + 1) {
                            distances[nextX][nextY] = currentDist + 1;
                            queue.addLast(new int[]{nextX, nextY});
                        }
                    }
                }
            }

            return distances[endX][endY] == Integer.MAX_VALUE ? -1 : distances[endX][endY];
        }

        /**
         * Checks if a coordinate is within grid bounds and points to a walkable cell.
         */
        private boolean isLegal(int x, int y) {
            return x >= 0 && x < height && y >= 0 && y < width && board[x][y] == WALKABLE_CELL;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

public class Main {

    /**
     * Represents a state in the BFS queue.
     * Stores the row, column, and the distance to reach that cell.
     */
    static class State {
        int r, c, dist;

        State(int r, int c, int dist) {
            this.r = r;
            this.c = c;
            this.dist = dist;
        }
    }

    /**
     * FastScanner class for efficient input reading.
     * Replaces the custom Input class with a standard, robust implementation.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read grid dimensions
        int H = sc.nextInt();
        int W = sc.nextInt();

        // Read start and destination coordinates (convert 1-based to 0-based)
        int startR = sc.nextInt() - 1;
        int startC = sc.nextInt() - 1;
        int targetR = sc.nextInt() - 1;
        int targetC = sc.nextInt() - 1;

        // Initialize distance grid
        // -1 represents a wall, Integer.MAX_VALUE represents unvisited
        int[][] dist = new int[H][W];
        for (int r = 0; r < H; r++) {
            String row = sc.next();
            for (int c = 0; c < W; c++) {
                if (row.charAt(c) == '#') {
                    dist[r][c] = -1;
                } else {
                    dist[r][c] = Integer.MAX_VALUE;
                }
            }
        }

        // BFS Initialization
        // Using a Deque for 0-1 BFS (since edge weights are 0 or 1)
        // This allows O(V+E) complexity instead of O(E log V) for Dijkstra
        Deque<State> deque = new ArrayDeque<>();

        // Set start distance to 0
        dist[startR][startC] = 0;
        deque.addFirst(new State(startR, startC, 0));

        while (!deque.isEmpty()) {
            State current = deque.pollFirst();
            int r = current.r;
            int c = current.c;
            int d = current.dist;

            // If the popped distance is greater than the recorded distance, 
            // it means we found a shorter path to this cell already. Skip processing.
            if (dist[r][c] < d) {
                continue;
            }

            // Optimization: If we reached the target, we can stop.
            // In 0-1 BFS, the first time a node is popped, its distance is optimal.
            if (r == targetR && c == targetC) {
                break; 
            }

            // Define the range of neighbors to check.
            // The original logic iterates a 5x5 area (Chebyshev distance <= 2).
            int minR = Math.max(0, r - 2);
            int maxR = Math.min(H - 1, r + 2);
            int minC = Math.max(0, c - 2);
            int maxC = Math.min(W - 1, c + 2);

            for (int nr = minR; nr <= maxR; nr++) {
                for (int nc = minC; nc <= maxC; nc++) {
                    // Skip the current cell itself
                    if (nr == r && nc == c) continue;

                    // Skip walls
                    if (dist[nr][nc] == -1) continue;

                    // Calculate movement cost based on original logic:
                    // 1. Orthogonal neighbors (Manhattan distance 1) have cost 0.
                    // 2. Other neighbors within range 2 have cost 1.
                    int manhattanDist = Math.abs(nr - r) + Math.abs(nc - c);
                    int moveCost = (manhattanDist == 1) ? 0 : 1;

                    // Relaxation step: check if we found a shorter path
                    if (dist[nr][nc] > d + moveCost) {
                        dist[nr][nc] = d + moveCost;

                        // 0-1 BFS logic for queue ordering:
                        // If cost is 0, add to front of deque (priority).
                        // If cost is 1, add to back of deque.
                        if (moveCost == 0) {
                            deque.addFirst(new State(nr, nc, d));
                        } else {
                            deque.addLast(new State(nr, nc, d + 1));
                        }
                    }
                }
            }
        }

        // Output result
        if (dist[targetR][targetC] == Integer.MAX_VALUE) {
            out.println(-1);
        } else {
            out.println(dist[targetR][targetC]);
        }

        out.flush();
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

/**
 * A refactored solution for finding the shortest path on a grid using 0-1 BFS.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed global static state (r, c, a) to make the code stateless and reusable.
 * 2. Naming Conventions: Used descriptive variable names (rows, cols, grid, distanceMap) instead of single letters.
 * 3. Data Structures: Replaced LinkedList with ArrayDeque for better performance and replaced the generic Pair class 
 *    with a semantic Coordinate class.
 * 4. Modularity: Separated the BFS logic into a dedicated method and validation into a helper method.
 * 5. Resource Management: Used try-with-resources for the Scanner.
 * 6. Constants: Defined magic numbers (like jump radius) as constants for readability.
 * 7. Optimization: Added an early exit condition when the destination is reached.
 */
public class Main {

    /**
     * Represents a coordinate (x, y) in the grid.
     */
    private static class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner sc = new Scanner(System.in)) {

            // 1. Read Grid Dimensions
            if (!sc.hasNextInt()) return;
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            // 2. Read Start and End Coordinates
            // Input is 1-based, converting to 0-based index for internal logic
            int startRow = sc.nextInt() - 1;
            int startCol = sc.nextInt() - 1;
            int endRow = sc.nextInt() - 1;
            int endCol = sc.nextInt() - 1;

            // 3. Read Grid Content
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                grid[i] = line.toCharArray();
            }

            // 4. Execute BFS Algorithm
            int result = solveShortestPath(rows, cols, grid, startRow, startCol, endRow, endCol);

            // 5. Output Result
            System.out.println(result);
        }
    }

    /**
     * Solves the shortest path problem using 0-1 BFS.
     * 
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @param grid The 2D character array representing the map
     * @param startRow Starting row index (0-based)
     * @param startCol Starting column index (0-based)
     * @param endRow Ending row index (0-based)
     * @param endCol Ending column index (0-based)
     * @return The minimum cost to reach the destination, or -1 if unreachable
     */
    private static int solveShortestPath(int rows, int cols, char[][] grid, 
                                         int startRow, int startCol, 
                                         int endRow, int endCol) {

        // Distance matrix initialized to infinity
        int[][] distanceMap = new int[rows][cols];
        for (int[] row : distanceMap) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        // Distance to start is 0
        distanceMap[startRow][startCol] = 0;

        // Deque for 0-1 BFS (Double-ended queue)
        // ArrayDeque is generally faster than LinkedList for queue operations
        Deque<Coordinate> deque = new ArrayDeque<>();
        deque.addFirst(new Coordinate(startRow, startCol));

        // Directions for adjacent moves: Up, Down, Left, Right
        // Cost for these moves is 0
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        // Constant for the jump radius (checks a 5x5 area centered at current cell)
        // Cost for these moves is 1
        final int JUMP_RADIUS = 2;

        while (!deque.isEmpty()) {
            Coordinate current = deque.removeFirst();
            int cx = current.x;
            int cy = current.y;

            // Optimization: If we reached the end, we can return immediately 
            // as 0-1 BFS guarantees the first time we pop a node, it has the shortest distance.
            if (cx == endRow && cy == endCol) {
                return distanceMap[cx][cy];
            }

            // 1. Explore adjacent neighbors (Cost 0)
            for (int i = 0; i < 4; i++) {
                int nx = cx + dx[i];
                int ny = cy + dy[i];

                if (isValid(nx, ny, rows, cols, grid)) {
                    // If we found a shorter path to neighbor
                    if (distanceMap[nx][ny] > distanceMap[cx][cy]) {
                        distanceMap[nx][ny] = distanceMap[cx][cy];
                        deque.addFirst(new Coordinate(nx, ny)); // Add to front for 0 cost
                    }
                }
            }

            // 2. Explore jump neighbors (Cost 1)
            // Iterates through the 5x5 box centered at (cx, cy)
            for (int i = cx - JUMP_RADIUS; i <= cx + JUMP_RADIUS; i++) {
                for (int j = cy - JUMP_RADIUS; j <= cy + JUMP_RADIUS; j++) {
                    if (isValid(i, j, rows, cols, grid)) {
                        // If we found a shorter path to jump target
                        if (distanceMap[i][j] > distanceMap[cx][cy] + 1) {
                            distanceMap[i][j] = distanceMap[cx][cy] + 1;
                            deque.addLast(new Coordinate(i, j)); // Add to back for 1 cost
                        }
                    }
                }
            }
        }

        // If destination was never reached
        int finalDist = distanceMap[endRow][endCol];
        return (finalDist == Integer.MAX_VALUE) ? -1 : finalDist;
    }

    /**
     * Checks if a coordinate is within grid bounds and not an obstacle.
     */
    private static boolean isValid(int x, int y, int rows, int cols, char[][] grid) {
        // Check bounds
        if (x < 0 || x >= rows || y < 0 || y >= cols) {
            return false;
        }
        // Check for obstacle
        return grid[x][y] != '#';
    }
}

import java.util.*;
import java.io.*;

public class Main {
    // Extracted constants to replace magic numbers
    private static final int INF = 1_000_000_000;
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};
    private static final int EXPLOSION_RADIUS = 2;

    // Encapsulated state to avoid static pollution and improve testability
    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] dist;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            Main solver = new Main();
            solver.run(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates input reading, solving, and output.
     */
    private void run(Scanner scanner, PrintWriter out) {
        if (!scanner.hasNextInt()) return;

        rows = scanner.nextInt();
        cols = scanner.nextInt();

        // Adjust 1-based input to 0-based indexing
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        grid = new char[rows][cols];
        dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        for (int r = 0; r < rows; r++) {
            grid[r] = scanner.next().toCharArray();
        }

        int result = bfs(startRow, startCol, endRow, endCol);
        out.println(result == INF ? -1 : result);
    }

    /**
     * Implements 0-1 BFS to find the shortest path on the grid.
     * Adjacent moves cost 0, radius-2 moves cost 1.
     */
    private int bfs(int startRow, int startCol, int endRow, int endCol) {
        ArrayDeque<Integer> rowQueue = new ArrayDeque<>();
        ArrayDeque<Integer> colQueue = new ArrayDeque<>();

        rowQueue.addFirst(startRow);
        colQueue.addFirst(startCol);
        dist[startRow][startCol] = 0;

        while (!rowQueue.isEmpty()) {
            int r = rowQueue.removeFirst();
            int c = colQueue.removeFirst();

            // Early exit: 0-1 BFS guarantees shortest path upon first dequeue
            if (r == endRow && c == endCol) {
                return dist[r][c];
            }

            // 0-cost moves (adjacent cells: up, right, down, left)
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];
                if (isValid(nr, nc) && dist[nr][nc] > dist[r][c]) {
                    dist[nr][nc] = dist[r][c];
                    rowQueue.addFirst(nr);
                    colQueue.addFirst(nc);
                }
            }

            // 1-cost moves (cells within a 5x5 radius centered at current cell)
            for (int nr = r - EXPLOSION_RADIUS; nr <= r + EXPLOSION_RADIUS; nr++) {
                for (int nc = c - EXPLOSION_RADIUS; nc <= c + EXPLOSION_RADIUS; nc++) {
                    if (isValid(nr, nc) && dist[nr][nc] > dist[r][c] + 1) {
                        dist[nr][nc] = dist[r][c] + 1;
                        rowQueue.addLast(nr);
                        colQueue.addLast(nc);
                    }
                }
            }
        }
        return dist[endRow][endCol] == INF ? -1 : dist[endRow][endCol];
    }

    /**
     * Checks if a cell is within bounds and not an obstacle.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

public class Main {

    // Constants
    private static final int INF = 100_000_000;
    // Orthogonal directions (Up, Down, Left, Right) - Cost 0
    private static final int[] DX_ORTHOGONAL = {1, -1, 0, 0};
    private static final int[] DY_ORTHOGONAL = {0, 0, 1, -1};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(sc, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) throws IOException {
        // Read dimensions
        String nStr = sc.next();
        if (nStr == null) return; // Handle empty input

        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();

        // Read start and target coordinates (convert 1-based to 0-based)
        int startX = sc.nextInt() - 1;
        int startY = sc.nextInt() - 1;
        int targetX = sc.nextInt() - 1;
        int targetY = sc.nextInt() - 1;

        // Read grid
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Initialize distance matrix with infinity
        int[][] dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        // BFS Initialization
        // Using ArrayDeque for 0-1 BFS (Double-ended queue)
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        dist[startX][startY] = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // 1. Process Orthogonal Neighbors (Cost 0)
            // These moves are added to the front of the deque to be processed immediately
            for (int i = 0; i < 4; i++) {
                int nx = current.x + DX_ORTHOGONAL[i];
                int ny = current.y + DY_ORTHOGONAL[i];

                if (isValid(nx, ny, n, m, grid)) {
                    // If we found a path with the same distance (cost 0), update and push front
                    if (dist[nx][ny] > dist[current.x][current.y]) {
                        dist[nx][ny] = dist[current.x][current.y];
                        queue.addFirst(new Point(nx, ny));
                    }
                }
            }

            // 2. Process Extended Neighbors (Cost 1)
            // Range [-2, 2] in both x and y.
            // These moves are added to the back of the deque.
            // Note: This loop includes orthogonal neighbors, but they are skipped 
            // by the distance check because they were already optimized in step 1.
            for (int dx = -2; dx <= 2; dx++) {
                for (int dy = -2; dy <= 2; dy++) {
                    // Skip the current cell itself
                    if (dx == 0 && dy == 0) continue;

                    int nx = current.x + dx;
                    int ny = current.y + dy;

                    if (isValid(nx, ny, n, m, grid)) {
                        // If we found a shorter path with cost 1, update and push back
                        if (dist[nx][ny] > dist[current.x][current.y] + 1) {
                            dist[nx][ny] = dist[current.x][current.y] + 1;
                            queue.addLast(new Point(nx, ny));
                        }
                    }
                }
            }
        }

        // Output result
        int result = dist[targetX][targetY];
        out.println(result >= INF ? -1 : result);
    }

    /**
     * Checks if the given coordinates are within bounds and not an obstacle.
     */
    private static boolean isValid(int x, int y, int n, int m, char[][] grid) {
        return x >= 0 && y >= 0 && x < n && y < m && grid[x][y] != '#';
    }

    /**
     * Helper class to represent a point on the grid.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * FastScanner for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        GridSolver solver = new GridSolver(reader);
        System.out.println(solver.findShortestPath());
    }

    /**
     * Handles fast and reliable input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String nextString() throws IOException {
            return next();
        }
    }

    /**
     * Encapsulates grid parsing and 0-1 BFS execution.
     */
    static class GridSolver {
        private final int n, m;
        private final int startRow, startCol, endRow, endCol;
        private final boolean[][] walkable;
        private static final int INF = Integer.MAX_VALUE / 2;

        public GridSolver(FastReader reader) throws IOException {
            this.n = reader.nextInt();
            this.m = reader.nextInt();
            this.startRow = reader.nextInt() - 1;
            this.startCol = reader.nextInt() - 1;
            this.endRow = reader.nextInt() - 1;
            this.endCol = reader.nextInt() - 1;

            this.walkable = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String row = reader.nextString();
                for (int j = 0; j < m; j++) {
                    walkable[i][j] = row.charAt(j) == '.';
                }
            }
        }

        public long findShortestPath() {
            long[][] dist = new long[n][m];
            for (long[] row : dist) {
                Arrays.fill(row, INF);
            }

            dist[startRow][startCol] = 0;
            Deque<int[]> deque = new ArrayDeque<>();
            deque.addFirst(new int[]{startRow, startCol});

            // 4-directional adjacent moves (cost 0)
            int[] dRow4 = {1, -1, 0, 0};
            int[] dCol4 = {0, 0, -1, 1};

            while (!deque.isEmpty()) {
                int[] curr = deque.pollFirst();
                int r = curr[0];
                int c = curr[1];
                long currentDist = dist[r][c];

                // Relax 0-cost edges
                for (int k = 0; k < 4; k++) {
                    int nr = r + dRow4[k];
                    int nc = c + dCol4[k];
                    if (isValid(nr, nc) && dist[nr][nc] > currentDist) {
                        dist[nr][nc] = currentDist;
                        deque.addFirst(new int[]{nr, nc});
                    }
                }

                // Relax 1-cost edges (within distance 2)
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        if (dr == 0 && dc == 0) continue;
                        int nr = r + dr;
                        int nc = c + dc;
                        if (isValid(nr, nc) && dist[nr][nc] > currentDist + 1) {
                            dist[nr][nc] = currentDist + 1;
                            deque.addLast(new int[]{nr, nc});
                        }
                    }
                }
            }

            long answer = dist[endRow][endCol];
            return answer >= INF ? -1 : answer;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m && walkable[r][c];
        }
    }
}
